// Module-load URL-param capture. Two signals stick to localStorage so they
// survive across sessions and keep working after we strip them from the
// visible URL:
//
//   ?lang=tr  → AI Coach defaults to Turkish from message #1.
//               ?lang=en explicitly opts out.
//
//   ?ref=foo  → affiliate attribution. Persists for 30 days (last-click).
//               First time we see a new code we POST a 'click' event to
//               track-referral so the dashboard can compute click→signup
//               conversion. URL strip happens later in a useEffect (see
//               near the admin/challenge param block) — module-load runs
//               before React mounts so we can't replaceState here without
//               racing the rest of the URL-param consumers.
if (typeof window !== 'undefined' && typeof localStorage !== 'undefined') {
  try {
    const params = new URLSearchParams(window.location.search);

    const lang = params.get('lang');
    if (lang === 'tr') {
      localStorage.setItem('sqlquest_lang', 'tr');
    } else if (lang === 'en') {
      localStorage.removeItem('sqlquest_lang');
    }

    const ref = normalizeRefCode(params.get('ref'));
    if (ref) {
      const prev = localStorage.getItem('sqlquest_referrer');
      localStorage.setItem('sqlquest_referrer', ref);
      localStorage.setItem('sqlquest_referrer_at', String(Date.now()));
      // Fire 'click' event only when the ref code actually changed —
      // refreshing the same `?ref=foo` link shouldn't repeatedly count.
      // Best-effort, never blocks the page.
      if (prev !== ref && window.SUPABASE_URL && window.SUPABASE_ANON_KEY) {
        fetch(`${window.SUPABASE_URL}/functions/v1/track-referral`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            apikey: window.SUPABASE_ANON_KEY,
            Authorization: `Bearer ${window.SUPABASE_ANON_KEY}`,
          },
          body: JSON.stringify({
            ref_code: ref,
            event_type: 'click',
            metadata: {
              path: window.location.pathname,
              search: window.location.search.slice(0, 200),
              lang: localStorage.getItem('sqlquest_lang') || null,
            },
          }),
        }).catch(() => {});
      }
    }

    // ?src=<slug> → first-touch arrival attribution. SEO/landing CTAs tag
    // their /app/ links (e.g. ?src=sql-practice-comparison); company/sector
    // deep links get a derived source so those pages attribute without their
    // own tag. First touch wins — a returning visitor keeps the door they
    // originally came through, so funnel events credit the page that
    // actually acquired them.
    if (!localStorage.getItem('sqlquest_arrival_src')) {
      const explicitSrc = params.get('src') || params.get('utm_source');
      const derivedSrc = params.get('company') ? `company:${params.get('company')}`
        : params.get('sector') ? `sector:${params.get('sector')}`
        : null;
      // Referrer fallback: 110 of the last fortnight's arrivals carried no
      // source at all and converted at 11% vs home's 48% — our biggest and
      // worst-performing door, and we couldn't say what it was. When there's
      // no explicit tag, stamp the external referrer hostname (ref:google.com,
      // ref:chatgpt.com…). Hostname only — no paths, no query strings.
      let referrerSrc = null;
      try {
        if (document.referrer) {
          const host = new URL(document.referrer).hostname;
          if (host && !host.endsWith('sqlquest.app') && host !== window.location.hostname) {
            referrerSrc = `ref:${host}`;
          }
        }
      } catch (_) { /* malformed referrer — skip */ }
      const arrivalSrc = explicitSrc || derivedSrc || referrerSrc;
      if (arrivalSrc) {
        localStorage.setItem('sqlquest_arrival_src', String(arrivalSrc).slice(0, 64));
      }
    }
  } catch (_) {}
}

