// Format cell values — preserve the SQL solution's natural decimal precision.
// Previously forced every non-integer through .toFixed(2), which meant a
// query using ROUND(.., 1) would display `63.0` as `63.00` in the expected
// output column. Students (like Murat's trial) would read that as "the
// expected answer has 2 decimals" and write ROUND(.., 2), producing a
// mismatch against the 1-decimal ground truth. Now we honor the value's
// own precision and only cap ugly repeating floats at 4 decimals.
// SkillSparkline — minimal SVG trend chart for skill trajectories. Pure
// SVG, no external charting library. Used by the "Your last 30 days"
// panel on the skill radar view to visualize cumulative solves per skill.
// Takes a numeric array (any length), produces an area+line chart.
// Named SkillSparkline to avoid collision with an older single-series
// Sparkline already defined further down in this file.
function SkillSparkline({ data, color = '#06b6d4', width = 180, height = 32, fillOpacity = 0.15 }) {
  if (!data || data.length === 0) return null;
  const max = Math.max(...data, 1);
  const range = max || 1;
  const xStep = data.length > 1 ? width / (data.length - 1) : width;
  const points = data.map((v, i) => {
    const x = i * xStep;
    const y = height - (v / range) * (height - 2) - 1;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  // Area fill polygon closes back to the baseline at both ends
  const area = `0,${height} ${points} ${(data.length - 1) * xStep},${height}`;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ display: 'block', minWidth: 0 }}>
      <polygon points={area} fill={color} fillOpacity={fillOpacity} />
      <polyline points={points} fill="none" stroke={color} strokeWidth="1.5" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

const formatCell = (cell, maxLength = null, columnDecimals = 0) => {
  if (cell === null || cell === undefined) return 'NULL';

  // Check if it's a number or a numeric string
  const numValue = typeof cell === 'number' ? cell : (typeof cell === 'string' && !isNaN(cell) && cell.trim() !== '' ? parseFloat(cell) : null);

  if (numValue !== null && typeof numValue === 'number' && !isNaN(numValue)) {
    if (!Number.isInteger(numValue)) {
      const str = numValue.toString();
      const decMatch = str.match(/\.(\d+)$/);
      let formatted;
      if (decMatch && decMatch[1].length > 4) {
        // Dirty float like 62.9629629... — round to 4 and strip trailing zeros
        formatted = numValue.toFixed(4).replace(/0+$/, '').replace(/\.$/, '');
      } else {
        // Already a clean ROUND(.., 1/2/3/4) result — display as-is
        formatted = str;
      }
      return maxLength ? formatted.slice(0, maxLength) : formatted;
    }
    // Whole-number branch. If the column has decimals elsewhere, format
    // this whole number with the same precision so ROUND(5.0, 1) reads as
    // "5.0" instead of "5". Without this, students running a query that
    // returns a clean whole number believe their ROUND didn't work.
    if (columnDecimals > 0) {
      const formatted = numValue.toFixed(columnDecimals);
      return maxLength ? formatted.slice(0, maxLength) : formatted;
    }
    return maxLength ? String(numValue).slice(0, maxLength) : String(numValue);
  }
  return maxLength ? String(cell).slice(0, maxLength) : String(cell);
};

// ============ SQL SYNTAX HIGHLIGHTING ============

// Helper function to highlight SQL code using Prism.js
const highlightSQL = (code) => {
  if (!code) return '';
  try {
    if (window.Prism && window.Prism.languages.sql) {
      return window.Prism.highlight(code, window.Prism.languages.sql, 'sql');
    }
  } catch (e) {
    console.warn('Prism highlighting failed:', e);
  }
  return code.replace(/</g, '&lt;').replace(/>/g, '&gt;');
};

// Component to display highlighted SQL (read-only)
const SQLHighlight = ({ code, className = '' }) => {
  if (!code) return null;
  return (
    <pre className={`language-sql m-0 p-0 bg-transparent ${className}`}>
      <code 
        className="language-sql"
        dangerouslySetInnerHTML={{ __html: highlightSQL(code) }} 
      />
    </pre>
  );
};

// ============================================================================
// Onboarding Tour — 6-step spotlight walkthrough for a user's first challenge.
// Discovered as a need during Murat's Preply trial (2026-04-21): a 50-year-old
// SAP expert with 20+ years of enterprise data experience needed 2 minutes of
// human walkthrough to understand the challenge UI. Cabin-crew career-switchers
// from Fortune's referral would churn at this wall. This component removes it.
// ============================================================================
const OnboardingTour = ({ steps, onComplete, onSkip }) => {
  const [stepIdx, setStepIdx] = useState(0);
  const [rect, setRect] = useState(null);

  const computeRect = (selector) => {
    const el = document.querySelector(selector);
    if (!el) return null;
    // Use instant scroll so the rect we measure is the post-scroll position.
    // Smooth scrolling can take 400-800ms and our measurement fires mid-animation,
    // leaving the spotlight ring floating in the pre-scroll location.
    // On mobile (narrow viewport), scroll to 'start' so the bottom-pinned
    // tooltip doesn't cover the target. On desktop, center is fine since
    // tooltip is placed beside/below the target.
    const isNarrow = typeof window !== 'undefined' && window.innerWidth < 500;
    el.scrollIntoView({ behavior: 'auto', block: isNarrow ? 'start' : 'center' });
    return new Promise(resolve => {
      // Small RAF-style delay so layout engine finishes applying the scroll.
      setTimeout(() => {
        const r = el.getBoundingClientRect();
        resolve({ top: r.top, left: r.left, width: r.width, height: r.height });
      }, 120);
    });
  };

  useEffect(() => {
    const step = steps[stepIdx];
    if (!step) return;
    let cancelled = false;
    (async () => {
      let r = await computeRect(step.selector);
      // Target not in DOM yet (e.g., Expected Output hasn't rendered because
      // db is still loading). Retry once after a longer delay.
      if (!r && !cancelled) {
        await new Promise(res => setTimeout(res, 800));
        r = await computeRect(step.selector);
      }
      if (!cancelled) setRect(r);
    })();
    // Recompute on resize so tooltip stays glued to target
    const onResize = async () => {
      const r = await computeRect(step.selector);
      if (!cancelled) setRect(r);
    };
    window.addEventListener('resize', onResize);
    return () => { cancelled = true; window.removeEventListener('resize', onResize); };
  }, [stepIdx, steps]);

  if (stepIdx >= steps.length) return null;
  const step = steps[stepIdx];
  const isLast = stepIdx === steps.length - 1;

  // If target isn't found (DOM not ready), show a centered fallback tooltip
  const fallback = !rect;
  const PAD = 10;
  const spotlightStyle = rect && !fallback ? {
    position: 'fixed',
    top: rect.top - PAD,
    left: rect.left - PAD,
    width: rect.width + PAD * 2,
    height: rect.height + PAD * 2,
    boxShadow: '0 0 0 9999px rgba(0, 0, 0, 0.72)',
    borderRadius: 14,
    pointerEvents: 'none',
    zIndex: 9998,
    transition: 'all 300ms ease',
    border: '2px solid rgba(253, 224, 71, 0.85)',
  } : null;

  // Tooltip placement: prefer below target; if too low, go above.
  let tooltipStyle;
  if (fallback) {
    tooltipStyle = {
      position: 'fixed',
      top: '50%',
      left: '50%',
      transform: 'translate(-50%, -50%)',
      width: 340,
      zIndex: 9999,
    };
  } else {
    const isNarrow = window.innerWidth < 500;
    if (isNarrow) {
      // Mobile: pin the tooltip to the BOTTOM of the viewport, full-width
      // minus side padding. Avoids the desktop "place above/below the target"
      // logic which was covering step-1's Problem heading on narrow screens.
      // Discovered during Chromium mobile emulation, 2026-04-22.
      tooltipStyle = {
        position: 'fixed',
        bottom: 16,
        left: 16,
        right: 16,
        width: 'auto',
        maxWidth: 'none',
        zIndex: 9999,
      };
    } else {
      const tooltipWidth = 340;
      const viewportH = window.innerHeight;
      const spaceBelow = viewportH - (rect.top + rect.height);
      const placeAbove = spaceBelow < 200;
      tooltipStyle = {
        position: 'fixed',
        top: placeAbove ? Math.max(16, rect.top - 200) : rect.top + rect.height + 16,
        left: Math.max(16, Math.min(rect.left, window.innerWidth - tooltipWidth - 16)),
        width: tooltipWidth,
        zIndex: 9999,
      };
    }
  }

  return (
    <>
      {/* Backdrop — covers everything except the spotlight cutout */}
      {fallback && (
        <div
          style={{
            position: 'fixed', inset: 0, background: 'rgba(0, 0, 0, 0.72)',
            zIndex: 9997, pointerEvents: 'none',
          }}
        />
      )}
      {/* Spotlight ring */}
      {spotlightStyle && <div style={spotlightStyle} />}
      {/* Tooltip card */}
      <div
        style={tooltipStyle}
        className="bg-gray-900 border-2 border-yellow-400/80 rounded-xl p-4 shadow-2xl"
      >
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-bold text-yellow-400 uppercase tracking-wider">
            {i18n_t('tour', 'stepXofY', { n: stepIdx + 1, total: steps.length })}
          </span>
          <button
            onClick={onSkip}
            className="text-xs text-gray-500 hover:text-gray-300"
            aria-label={i18n_t('tour', 'skipTour')}
          >
            {i18n_t('tour', 'skipTour')}
          </button>
        </div>
        <h4 className="font-bold text-[#F2F0EA] text-base mb-2">{step.titleKey ? i18n_t('tour', step.titleKey) : step.title}</h4>
        <p className="text-sm text-gray-300 leading-relaxed mb-4">{step.bodyKey ? i18n_t('tour', step.bodyKey) : step.body}</p>
        <div className="flex items-center justify-between">
          <div className="flex gap-1">
            {steps.map((_, i) => (
              <div
                key={i}
                className={`h-1.5 rounded-full transition-all ${i === stepIdx ? 'w-6 bg-yellow-400' : i < stepIdx ? 'w-1.5 bg-yellow-600' : 'w-1.5 bg-gray-600'}`}
              />
            ))}
          </div>
          <button
            onClick={() => {
              if (isLast) onComplete();
              else setStepIdx(stepIdx + 1);
            }}
            className="px-4 py-1.5 bg-yellow-400 hover:bg-yellow-300 text-gray-900 rounded-lg text-sm font-bold transition-all"
          >
            {isLast ? i18n_t('tour', 'gotIt') : i18n_t('tour', 'next')}
          </button>
        </div>
      </div>
    </>
  );
};

