// Reusable SQL editor powered by CodeMirror 5
const SQLEditor = ({ value, onChange, onKeyDown, placeholder, height = '10rem', disabled = false, className = '' }) => {
  const containerRef = useRef(null);
  const editorRef = useRef(null);
  const onChangeRef = useRef(onChange);
  const onKeyDownRef = useRef(onKeyDown);
  const isExternalUpdate = useRef(false);

  onChangeRef.current = onChange;
  onKeyDownRef.current = onKeyDown;

  useEffect(() => {
    if (!containerRef.current || !window.CodeMirror) return;
    const cm = window.CodeMirror(containerRef.current, {
      value: value || '',
      mode: 'text/x-sql',
      theme: 'material-darker',
      lineNumbers: false,
      matchBrackets: true,
      autoCloseBrackets: true,
      placeholder: placeholder || '',
      lineWrapping: true,
      readOnly: disabled ? 'nocursor' : false,
      extraKeys: {
        'Ctrl-Space': 'autocomplete',
        'Tab': function(cm) { cm.replaceSelection('  ', 'end'); }
      }
    });
    editorRef.current = cm;

    cm.on('change', () => {
      if (isExternalUpdate.current) return;
      const val = cm.getValue();
      if (onChangeRef.current) onChangeRef.current(val);
    });

    cm.on('keydown', (cm, e) => {
      if (onKeyDownRef.current) onKeyDownRef.current(e);
    });

    return () => { cm.toTextArea && cm.toTextArea(); };
  }, []);

  // Sync external value changes into CodeMirror
  useEffect(() => {
    if (editorRef.current && value !== editorRef.current.getValue()) {
      isExternalUpdate.current = true;
      editorRef.current.setValue(value || '');
      isExternalUpdate.current = false;
    }
  }, [value]);

  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.setOption('readOnly', disabled ? 'nocursor' : false);
    }
  }, [disabled]);

  return (
    <div
      ref={containerRef}
      className={`sql-cm-editor rounded-lg overflow-hidden ${className}`}
      style={{ height, minHeight: height }}
    />
  );
};

// ============ USER STORAGE HELPERS ============

// Production-ready password hashing with fallback for non-HTTPS environments
const generateSalt = () => {
  try {
    const array = new Uint8Array(16);
    crypto.getRandomValues(array);
    return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
  } catch (e) {
    // Fallback for environments without crypto
    return Math.random().toString(36).substring(2) + Date.now().toString(36);
  }
};

// Simple but effective hash function (works everywhere)
const simpleHash = (str) => {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  // Make it longer and more secure-looking
  const hex = Math.abs(hash).toString(16);
  return hex.padStart(8, '0') + hex.split('').reverse().join('').padStart(8, '0');
};

// Try to use Web Crypto API, fall back to simple hash
const hashPassword = async (password, salt) => {
  try {
    if (window.crypto && window.crypto.subtle) {
      const encoder = new TextEncoder();
      const data = encoder.encode(salt + password);
      const hashBuffer = await crypto.subtle.digest('SHA-256', data);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      return hashArray.map(byte => byte.toString(16).padStart(2, '0')).join('');
    }
  } catch (e) {
    console.warn('Web Crypto not available, using fallback');
  }
  // Fallback
  return simpleHash(salt + password + salt);
};

const verifyPassword = async (password, salt, storedHash) => {
  const hash = await hashPassword(password, salt);
  return hash === storedHash;
};

// Password strength checker
const getPasswordStrength = (password) => {
  if (!password) return { score: 0, label: '', color: '', feedback: [] };
  
  let score = 0;
  const feedback = [];
  
  // Length checks
  if (password.length >= 6) score += 1;
  if (password.length >= 8) score += 1;
  if (password.length >= 12) score += 1;
  
  // Character type checks
  if (/[a-z]/.test(password)) score += 1;
  if (/[A-Z]/.test(password)) score += 1;
  if (/[0-9]/.test(password)) score += 1;
  if (/[^a-zA-Z0-9]/.test(password)) score += 1;
  
  // Feedback
  if (password.length < 8) feedback.push('Use at least 8 characters');
  if (!/[a-z]/.test(password)) feedback.push('Add lowercase letters');
  if (!/[A-Z]/.test(password)) feedback.push('Add uppercase letters');
  if (!/[0-9]/.test(password)) feedback.push('Add numbers');
  if (!/[^a-zA-Z0-9]/.test(password)) feedback.push('Add special characters (!@#$%)');
  
  // Determine strength level
  let label, color;
  if (score <= 2) {
    label = 'Weak';
    color = 'red';
  } else if (score <= 4) {
    label = 'Fair';
    color = 'orange';
  } else if (score <= 5) {
    label = 'Good';
    color = 'yellow';
  } else {
    label = 'Strong';
    color = 'green';
  }
  
  return { score, label, color, feedback, percent: Math.min((score / 7) * 100, 100) };
};

// ============ SUPABASE HELPERS ============
const isSupabaseConfigured = () => {
  return window.SUPABASE_URL && window.SUPABASE_ANON_KEY && 
         window.SUPABASE_URL.length > 0 && window.SUPABASE_ANON_KEY.length > 0;
};

// Initialize Supabase client for Auth
//
// PKCE flow: protects email-link auth (password reset, signup confirm,
// magic link) from being silently consumed by email-provider link
// scanners. Yahoo Mail and Microsoft SafeLinks pre-fetch every link in
// every email to scan for malware; in the default implicit flow this
// burns the one-time recovery token, so when the real user clicks they
// hit `error_code=otp_expired`. PKCE stores a code_verifier in this
// browser's localStorage at request time and only the same browser can
// complete the exchange — the scanner can prefetch all it wants but
// can't burn the token. See Supabase docs:
// https://supabase.com/docs/guides/auth/sessions/pkce-flow
//
// Backward-compat: existing implicit-flow reset emails (sent before
// this change) still work because detectSessionInUrl handles both
// `#access_token=...` (implicit) and `?code=...` (PKCE) shapes.
const getSupabaseClient = () => {
  if (!isSupabaseConfigured() || !window.supabase) return null;
  if (!window._supabaseClient) {
    window._supabaseClient = window.supabase.createClient(
      window.SUPABASE_URL,
      window.SUPABASE_ANON_KEY,
      {
        auth: {
          flowType: 'pkce',
          detectSessionInUrl: true,
          persistSession: true,
          autoRefreshToken: true
        }
      }
    );
  }
  return window._supabaseClient;
};

// Password Reset Functions
const sendPasswordResetEmail = async (email) => {
  const client = getSupabaseClient();
  if (!client) {
    throw new Error('Supabase not configured');
  }
  
  const { data, error } = await client.auth.resetPasswordForEmail(email, {
    redirectTo: window.location.origin + window.location.pathname + '?reset=true'
  });
  
  if (error) throw error;
  return data;
};

const updatePasswordWithToken = async (newPassword) => {
  const client = getSupabaseClient();
  if (!client) {
    throw new Error('Supabase not configured');
  }

  // Wait for the auth session to be established. With PKCE, the
  // `?code=...` exchange is async — Supabase JS calls /token in the
  // background, and if the user fills the new password and clicks
  // Update before that round-trip finishes, updateUser fails with
  // "Auth session missing!" Poll briefly so the realistic case (~200ms
  // exchange) doesn't get reported as a hard failure.
  let session = null;
  const params = new URLSearchParams(window.location.search);
  const pkceCode = params.get('code');
  if (pkceCode) {
    // Drive the exchange ourselves so we don't depend on the
    // detectSessionInUrl auto-runner having reached this code yet.
    try {
      await client.auth.exchangeCodeForSession(pkceCode);
    } catch (err) {
      // Auto-runner may already have exchanged it — that throws but
      // leaves a valid session in storage, which the poll below picks
      // up. Real failures (verifier missing, token used) also surface
      // there, with a clearer error.
    }
  }
  for (let i = 0; i < 30; i++) {
    const { data: sd } = await client.auth.getSession();
    if (sd?.session) {
      session = sd.session;
      break;
    }
    await new Promise(r => setTimeout(r, 100));
  }
  if (!session) {
    throw new Error(
      'Şifre sıfırlama oturumu kurulamadı. Linki email\'den tekrar tıkla; eğer aynı hata sürerse "Şifremi unuttum" ile yeni bir link iste.'
    );
  }

  const { data, error } = await client.auth.updateUser({
    password: newPassword
  });

  if (error) throw error;
  return data;
};

// Resend verification email
const resendVerificationEmail = async (email) => {
  const client = getSupabaseClient();
  if (!client) {
    throw new Error('Supabase not configured');
  }
  
  const { data, error } = await client.auth.resend({
    type: 'signup',
    email: email,
    options: {
      emailRedirectTo: window.location.origin + window.location.pathname + '?verified=true'
    }
  });
  
  if (error) throw error;
  return data;
};

// Check if this is an email verification callback.
// Supabase puts `type=signup|email` in different places depending on the
// auth flow type — query string for PKCE, URL hash for implicit. Read
// both so the detection survives a flow-type switch.
const checkEmailVerificationCallback = () => {
  const params = new URLSearchParams(window.location.search);
  const hashParams = new URLSearchParams(window.location.hash.substring(1));
  const t = params.get('type') || hashParams.get('type');

  if (params.get('verified') === 'true' || t === 'signup' || t === 'email') {
    return true;
  }
  return false;
};

// Check if this is a password reset callback.
// `?reset=true` is set by us in redirectTo and survives both flow types
// (Supabase preserves query params and appends `&code=...` for PKCE or
// `#access_token=...` for implicit). The `type=recovery` check is the
// belt-and-suspenders fallback for emails sent without our reset query.
const checkPasswordResetCallback = () => {
  const params = new URLSearchParams(window.location.search);
  const hashParams = new URLSearchParams(window.location.hash.substring(1));
  const t = params.get('type') || hashParams.get('type');

  if (params.get('reset') === 'true' || t === 'recovery') {
    return true;
  }
  return false;
};

// Check if Supabase redirected us back with an auth error (expired link,
// already-used token, etc). Shown to the user via a toast so they see
// "Reset link expired" instead of silently landing on the home page,
// which is the experience that has been confusing Yahoo/Outlook users.
const checkAuthErrorCallback = () => {
  const hashParams = new URLSearchParams(window.location.hash.substring(1));
  const params = new URLSearchParams(window.location.search);
  const errorCode = hashParams.get('error_code') || params.get('error_code');
  const errorDescription =
    hashParams.get('error_description') || params.get('error_description');
  if (errorCode || errorDescription) {
    return {
      code: errorCode || 'unknown',
      description: (errorDescription || '').replace(/\+/g, ' ')
    };
  }
  return null;
};

const supabaseFetch = async (endpoint, options = {}) => {
  if (!isSupabaseConfigured()) return null;

  try {
    const response = await fetch(`${window.SUPABASE_URL}/rest/v1/${endpoint}`, {
      ...options,
      headers: {
        'apikey': window.SUPABASE_ANON_KEY,
        'Authorization': `Bearer ${window.SUPABASE_ANON_KEY}`,
        'Content-Type': 'application/json',
        // Default to 'return=minimal' for writes — we rarely need the echoed
        // row, and asking for it doubles egress on user-data syncs that can
        // be 100KB+ each. Callers that actually need the row back set
        // Prefer: return=representation explicitly.
        'Prefer': 'return=minimal',
        ...options.headers
      }
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('Supabase error:', response.status, errorText);
      return null;
    }

    const text = await response.text();
    return text ? JSON.parse(text) : null;
  } catch (err) {
    console.error('Supabase fetch error:', err);
    return null;
  }
};

// ============ USER DATA FUNCTIONS ============
//
// Cloud-sync egress budget:
//   Before: every call did (a) GET user row (~100KB echoed back), then
//   (b) PATCH with return=representation (full row echoed back again) or
//   POST insert. So ~300KB of egress per save. With 47 call sites firing
//   on every state change, this racked up 10+ GB/month for 5 users.
//
//   After:
//     1. Debounce: saveUserData coalesces rapid calls into one network
//        write every 5s. Local storage still writes synchronously so UI
//        state is never lost.
//     2. Upsert: use INSERT ... ON CONFLICT via PostgREST's 'resolution=
//        merge-duplicates' so we never need the existence-check GET.
//     3. return=minimal everywhere. Server doesn't echo the saved row.
//
const _cloudSaveQueue = new Map(); // username → { data, timer }
const CLOUD_SAVE_DEBOUNCE_MS = 5000;

const _flushCloudSave = async (username, data) => {
  if (!isSupabaseConfigured()) return { ok: true, skipped: true };
  try {
    const cloudData = {
      username,
      password_hash: data.passwordHash || '',
      salt: data.salt || '',
      email: data.email || null,
      data,
      updated_at: new Date().toISOString(),
      created_at: new Date().toISOString(), // ignored on conflict-merge
    };
    // Upsert via ON CONFLICT (username). One request, minimal response.
    // Requires a unique index on users.username — which the old lookup-
    // then-patch code relied on implicitly too. If that index is missing,
    // add it: `create unique index if not exists users_username_key on
    // public.users (username);`
    await supabaseFetch('users?on_conflict=username', {
      method: 'POST',
      headers: {
        'Prefer': 'resolution=merge-duplicates,return=minimal',
      },
      body: JSON.stringify(cloudData),
    });
    return { ok: true };
  } catch (err) {
    console.error('Cloud sync failed:', err);
    return { ok: false, error: err };
  }
};

// saveUserData(username, data, options?)
//   options.force = true  → bypass debounce, await cloud write, propagate failure.
//                           USE FOR: password change, signup, password reset —
//                           anywhere a stale cloud copy would lock the user out.
//                           Returns { ok: true } on success, throws on failure.
//   default               → existing 5s debounced behaviour (fine for XP, streaks,
//                           solved challenges — losing the very last write to a
//                           tab close is acceptable for those).
const saveUserData = async (username, data, options = {}) => {
  // 0. Affiliate attribution stamp — happens on the FIRST save of a
  //    freshly-created account. Detection: data.createdAt is within the
  //    last 60s AND no refCode field yet. This is reliable because:
  //      - Both signup paths (convertGuestToUser + auth modal register)
  //        set createdAt: Date.now() right before the first saveUserData.
  //      - Subsequent autosaves keep the same createdAt, so the age check
  //        will fail and we won't restamp ref onto pre-existing users.
  //    We also fire a 'signup' event on the same hook so we don't have to
  //    sprinkle attribution calls across every signup site.
  if (data && !data.refCode && data.createdAt) {
    try {
      const created = typeof data.createdAt === 'number'
        ? data.createdAt
        : Date.parse(data.createdAt);
      const ageMs = Number.isFinite(created) ? Date.now() - created : Infinity;
      if (ageMs >= 0 && ageMs < 60_000) {
        const ref = (typeof localStorage !== 'undefined')
          ? localStorage.getItem('sqlquest_referrer')
          : null;
        // Last-click attribution with a 30-day window (see referrals.js).
        // If the partner click happened months ago and the user is only
        // signing up now, treat it as organic — don't credit the partner.
        const refAtRaw = ref ? parseInt(localStorage.getItem('sqlquest_referrer_at') || '0', 10) : 0;
        const fresh = ref ? isReferrerFresh(refAtRaw || null) : false;
        if (ref && fresh) {
          data.refCode = ref;
          data.refCodeAt = Number.isFinite(refAtRaw) && refAtRaw > 0 ? refAtRaw : Date.now();
          // Fire 'signup' event so the dashboard funnel (clicks → signups)
          // updates. Best-effort — never block the actual save.
          if (typeof fetch !== 'undefined' && window.SUPABASE_URL && window.SUPABASE_ANON_KEY) {
            fetch(`${window.SUPABASE_URL}/functions/v1/track-referral`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                apikey: window.SUPABASE_ANON_KEY,
                Authorization: `Bearer ${window.SUPABASE_ANON_KEY}`,
              },
              body: JSON.stringify({
                ref_code: ref,
                event_type: 'signup',
                username,
                metadata: {
                  lang: (typeof localStorage !== 'undefined')
                    ? (localStorage.getItem('sqlquest_lang') || null)
                    : null,
                },
              }),
            }).catch(() => {});
          }
        }
      }
    } catch (_) { /* attribution failures must never break a save */ }
  }

  // 1. Local write — synchronous, no debounce. UI state must never be lost.
  try {
    localStorage.setItem(`sqlquest_user_${username}`, JSON.stringify(data));
  } catch (err) {
    console.error('Failed to save to localStorage:', err);
  }

  // 2. Cloud sync.
  if (!isSupabaseConfigured()) return true;

  // 2a. Force path — high-stakes writes (password ops, signup) must NOT debounce.
  //     The bug: debounced write fires 5s later; if the user navigates / logs out
  //     / closes the tab in that window, cloud has the stale value while
  //     localStorage looks correct, and the next login fails with "Invalid".
  //     This is what bit Murat (mbalkose) on 2026-05-07 — password "successfully
  //     changed" client-side, but cloud never received the new hash.
  if (options.force === true) {
    const existing = _cloudSaveQueue.get(username);
    if (existing && existing.timer) clearTimeout(existing.timer);
    _cloudSaveQueue.delete(username);
    const result = await _flushCloudSave(username, data);
    if (!result.ok) {
      // Surface the failure so the caller can show an error and not pretend
      // the change persisted.
      throw new Error('Cloud sync failed: ' + (result.error?.message || 'unknown'));
    }
    return true;
  }

  // 2b. Normal path — debounced upsert. Rapid calls collapse into one write
  //     every CLOUD_SAVE_DEBOUNCE_MS. Uses the LATEST data at flush time so
  //     nothing is lost, just batched.
  const existing = _cloudSaveQueue.get(username);
  if (existing && existing.timer) clearTimeout(existing.timer);
  const timer = setTimeout(() => {
    const entry = _cloudSaveQueue.get(username);
    _cloudSaveQueue.delete(username);
    if (entry) _flushCloudSave(username, entry.data);
  }, CLOUD_SAVE_DEBOUNCE_MS);
  _cloudSaveQueue.set(username, { data, timer });

  // Best-effort flush on tab close so the last save reaches cloud. Uses
  // fetch with { keepalive: true } so the request survives page unload —
  // PostgREST needs the apikey header which sendBeacon can't set.
  if (typeof window !== 'undefined' && !window.__cloudFlushBound) {
    window.__cloudFlushBound = true;
    window.addEventListener('beforeunload', () => {
      for (const [user, entry] of _cloudSaveQueue.entries()) {
        if (entry.timer) clearTimeout(entry.timer);
        try {
          const body = JSON.stringify({
            username: user,
            password_hash: entry.data.passwordHash || '',
            salt: entry.data.salt || '',
            email: entry.data.email || null,
            data: entry.data,
            updated_at: new Date().toISOString(),
            created_at: new Date().toISOString(),
          });
          fetch(`${window.SUPABASE_URL}/rest/v1/users?on_conflict=username`, {
            method: 'POST',
            keepalive: true,
            headers: {
              'apikey': window.SUPABASE_ANON_KEY,
              'Authorization': `Bearer ${window.SUPABASE_ANON_KEY}`,
              'Content-Type': 'application/json',
              'Prefer': 'resolution=merge-duplicates,return=minimal',
            },
            body,
          });
        } catch (_) { /* best-effort */ }
      }
      _cloudSaveQueue.clear();
    });
  }

  return true;
};

const loadUserData = async (username, allowLocalFallback = true) => {
  
  // Try cloud first if configured
  if (isSupabaseConfigured()) {
    try {
      const cloudData = await supabaseFetch(`users?username=eq.${encodeURIComponent(username)}`);
      
      if (cloudData && cloudData.length > 0) {
        const userData = cloudData[0].data;
        // Guard: an effectively-EMPTY cloud blob must not clobber local
        // progress. This was eating every guest's work on every load: the
        // guest's cloud row is created at first visit but the autosave loop
        // never updated it (gated on !isGuest until 2026-07-24), so each
        // reload pulled the empty row over the local blob that held their
        // real progress. 91 guests solved 215 challenges in the last
        // fortnight; every one of their server rows was empty. Prefer local
        // when it has progress and cloud has none — the next autosave then
        // uploads the local truth and the two converge.
        try {
          const cloudHasProgress = (userData?.solvedChallenges?.length || 0) > 0 || (userData?.xp || 0) > 0;
          if (!cloudHasProgress) {
            const localRaw = localStorage.getItem(`sqlquest_user_${username}`);
            const local = localRaw ? JSON.parse(localRaw) : null;
            const localHasProgress = (local?.solvedChallenges?.length || 0) > 0 || (local?.xp || 0) > 0;
            if (localHasProgress) return local;
          }
        } catch (_) { /* fall through to cloud copy */ }
        // Also update localStorage with cloud data
        localStorage.setItem(`sqlquest_user_${username}`, JSON.stringify(userData));
        return userData;
      } else {
        // User not found in Supabase
        if (!allowLocalFallback) {
          // For login, don't allow localStorage fallback - user must exist in cloud
          localStorage.removeItem(`sqlquest_user_${username}`);
          return null;
        }
        // If local fallback is allowed, fall through to localStorage read below
      }
    } catch (err) {
      console.error('Failed to load from cloud:', err);
    }
  }
  
  // Fall back to localStorage (only if allowed)
  if (allowLocalFallback) {
    try {
      const result = localStorage.getItem(`sqlquest_user_${username}`);
      return result ? JSON.parse(result) : null;
    } catch (err) {
      console.error('Failed to load user data:', err);
      return null;
    }
  }
  
  return null;
};

const saveToLeaderboard = async (username, xp, solvedCount) => {
  // Save locally
  try {
    const leaderboard = JSON.parse(localStorage.getItem('sqlquest_leaderboard') || '{}');
    leaderboard[username] = { username, xp, solvedCount, timestamp: Date.now() };
    localStorage.setItem('sqlquest_leaderboard', JSON.stringify(leaderboard));
  } catch (err) {
    console.error('Failed to save to leaderboard:', err);
  }
  return true;
};

// NOTE (2026-04-21): An April-4 "one-time password reset" block for
// test2/test11 lived here. It overwrote those accounts' password hashes
// in Supabase the first time the app booted in any browser, locking the
// legitimate owner out of their own accounts. Removed. If you need to
// reset a test account, do it via the admin panel (Ctrl+Shift+A) or
// directly in Supabase SQL — never via a client-side auto-run.

// Seed users for leaderboard (appear alongside real users)
// The leaderboard used to be padded with 49 fabricated accounts here —
// generated names in three styles, algorithmic daily XP, a 30% chance of a
// simulated rest day — merged in and rendered indistinguishably from real
// people. Removed 2026-07-26 along with the switch to leagues: a board that
// matches you against peers by engagement cannot be built on invented
// engagement. 134 real users have XP and the top real user is ~5x the top
// seed was, so the padding had outlived its reason anyway.

const loadLeaderboard = async () => {
  let realUsers = [];
  
  // If Supabase configured, load from cloud
  if (isSupabaseConfigured()) {
    try {
      const cloudUsers = await supabaseFetch('users?select=username,data&order=data->>xp.desc&limit=50');
      if (cloudUsers && cloudUsers.length > 0) {
        realUsers = cloudUsers.map(u => ({
          username: u.username,
          xp: u.data?.xp || 0,
          solvedCount: u.data?.solvedChallenges?.length || 0,
          timestamp: Date.now(),
          isSeeded: false
        }));
      }
    } catch (err) {
      console.error('Failed to load cloud leaderboard:', err);
    }
  }
  
  // Fall back to local leaderboard if no cloud users
  if (realUsers.length === 0) {
    try {
      const leaderboard = JSON.parse(localStorage.getItem('sqlquest_leaderboard') || '{}');
      realUsers = Object.values(leaderboard).map(u => ({ ...u, isSeeded: false }));
    } catch (err) {
      console.error('Failed to load leaderboard:', err);
      realUsers = [];
    }
  }
  
  // Real users only — see the note above the deleted seed block.
  return realUsers.sort((a, b) => b.xp - a.xp);
};

