const skillTracks = window.skillTracksData || [];
const levels = window.gameLevels || [{ name: 'Novice', minXP: 0 }];
const achievements = window.gameAchievements || [];
const dailyChallenges = window.dailyChallengesData || [];
const mockInterviews = window.mockInterviewsData || [];
const interviewCategories = window.interviewCategories || [];

// ============ STATIC TOPIC EXPLANATIONS ============
// Pre-written explanations for SQL concepts - shown instantly without AI call
const TOPIC_EXPLANATIONS = {
  'SELECT': {
    title: 'SELECT Statement',
    explanation: `SELECT is how you retrieve data from a database table.

Basic syntax:
  SELECT column1, column2 FROM table_name;

Use * to get all columns:
  SELECT * FROM employees;

Pick specific columns:
  SELECT name, salary FROM employees;

Use LIMIT to restrict rows:
  SELECT name FROM employees LIMIT 5;

Key points:
- SELECT always comes first in a query
- FROM specifies which table to read from
- Column names are separated by commas
- LIMIT controls how many rows you get back`
  },
  'WHERE': {
    title: 'Filtering with WHERE',
    explanation: `WHERE filters rows based on conditions. Only rows that match are returned.

Basic syntax:
  SELECT * FROM employees WHERE salary > 50000;

Comparison operators: =, !=, <, >, <=, >=
  SELECT name FROM movies WHERE rating >= 8.0;
  SELECT * FROM passengers WHERE sex = 'female';

Use AND / OR to combine conditions:
  SELECT * FROM passengers WHERE pclass = 1 AND survived = 1;
  SELECT * FROM movies WHERE genre = 'Action' OR genre = 'Comedy';

Use NOT to negate:
  SELECT * FROM passengers WHERE NOT survived = 0;

Key points:
- WHERE goes after FROM
- Text values need single quotes: 'value'
- Numbers don't need quotes
- AND requires ALL conditions true, OR requires ANY`
  },
  'AND': {
    title: 'Combining Conditions with AND/OR',
    explanation: `AND and OR let you combine multiple conditions in WHERE.

AND - ALL conditions must be true:
  SELECT * FROM passengers WHERE sex = 'female' AND survived = 1;

OR - ANY condition can be true:
  SELECT * FROM passengers WHERE pclass = 1 OR pclass = 2;

Combine both (use parentheses for clarity):
  SELECT * FROM passengers WHERE (age < 18 OR age > 60) AND survived = 1;

NOT negates a condition:
  SELECT * FROM employees WHERE NOT department = 'HR';

Key points:
- AND is more restrictive (fewer results)
- OR is more inclusive (more results)
- Use parentheses when mixing AND/OR to control order
- Without parentheses, AND is evaluated before OR`
  },
  'OR': null, // mapped to AND
  'NOT': null, // mapped to AND
  'ORDER BY': {
    title: 'Sorting with ORDER BY',
    explanation: `ORDER BY sorts your results by one or more columns.

Ascending (default, smallest first):
  SELECT * FROM movies ORDER BY year ASC;

Descending (largest first):
  SELECT * FROM movies ORDER BY rating DESC;

Sort by multiple columns:
  SELECT * FROM movies ORDER BY year DESC, rating DESC;
  (First by year, then by rating within each year)

Combine with LIMIT for "top N":
  SELECT * FROM movies ORDER BY revenue_millions DESC LIMIT 10;

Key points:
- ASC is the default (can be omitted)
- DESC = descending (largest/newest first)
- ORDER BY goes near the end of the query
- Multiple sort columns are separated by commas
- Often combined with LIMIT for "top 10" style queries`
  },
  'Aggregation': {
    title: 'Aggregate Functions',
    explanation: `Aggregate functions calculate a single value from multiple rows.

Five key functions:
  COUNT(*) - count rows:           SELECT COUNT(*) FROM movies;
  SUM(col) - add values:           SELECT SUM(salary) FROM employees;
  AVG(col) - average:              SELECT AVG(rating) FROM movies;
  MIN(col) - smallest:             SELECT MIN(price) FROM orders;
  MAX(col) - largest:              SELECT MAX(salary) FROM employees;

Combine with WHERE:
  SELECT COUNT(*), AVG(rating) FROM movies WHERE genre = 'Action';

Key points:
- COUNT(*) counts all rows, COUNT(col) skips NULLs
- Aggregates collapse many rows into one result row
- Often used with GROUP BY to get aggregates per group
- You can use multiple aggregates in one SELECT`
  },
  'COUNT': null, // mapped to Aggregation
  'SUM': null,
  'AVG': null,
  'MIN': null,
  'MAX': null,
  'GROUP BY': {
    title: 'GROUP BY',
    explanation: `GROUP BY splits rows into groups and applies aggregates to each group.

Basic syntax:
  SELECT department, COUNT(*) FROM employees GROUP BY department;

This gives you one row per department with the count of employees in each.

More examples:
  SELECT genre, AVG(rating) FROM movies GROUP BY genre;
  SELECT category, SUM(total) FROM orders GROUP BY category;

Multiple groups:
  SELECT department, position, AVG(salary) FROM employees GROUP BY department, position;

Key points:
- Every non-aggregate column in SELECT must be in GROUP BY
- GROUP BY goes after WHERE (if any)
- Each unique value (or combination) becomes one output row
- Always pair with aggregate functions (COUNT, SUM, AVG, etc.)`
  },
  'HAVING': {
    title: 'HAVING Clause',
    explanation: `HAVING filters groups AFTER aggregation. WHERE filters rows BEFORE.

Basic syntax:
  SELECT department, COUNT(*) FROM employees
  GROUP BY department
  HAVING COUNT(*) > 5;

WHERE vs HAVING:
  WHERE filters individual rows (before grouping)
  HAVING filters groups (after grouping)

Example with both:
  SELECT department, AVG(salary) FROM employees
  WHERE hire_date > '2020-01-01'
  GROUP BY department
  HAVING AVG(salary) > 60000;

Key points:
- HAVING goes after GROUP BY
- Use HAVING for conditions on aggregates (COUNT, SUM, AVG)
- Use WHERE for conditions on individual row values
- You can use both WHERE and HAVING in one query`
  },
  'JOIN': {
    title: 'JOIN Basics',
    explanation: `JOIN combines rows from two or more tables based on a related column.

INNER JOIN - only matching rows from both tables:
  SELECT orders.product, customers.name
  FROM orders
  JOIN customers ON orders.customer_id = customers.customer_id;

LEFT JOIN - all rows from left table, matching from right:
  SELECT customers.name, orders.product
  FROM customers
  LEFT JOIN orders ON customers.customer_id = orders.customer_id;

With aliases (shorter names):
  SELECT o.product, c.name
  FROM orders o
  JOIN customers c ON o.customer_id = c.customer_id;

Key points:
- ON specifies which columns to match
- INNER JOIN (or just JOIN) only returns matches
- LEFT JOIN keeps all rows from the first table
- The join column usually has the same name in both tables
- You can join more than 2 tables by chaining JOINs`
  },
  'INNER JOIN': null, // mapped to JOIN
  'LEFT JOIN': null,
  'Subquery': {
    title: 'Subqueries',
    explanation: `A subquery is a SELECT inside another SELECT. It lets you use one query's result in another.

In WHERE clause (most common):
  SELECT * FROM movies
  WHERE rating > (SELECT AVG(rating) FROM movies);
  (Finds movies rated above average)

With IN:
  SELECT * FROM customers
  WHERE customer_id IN (SELECT customer_id FROM orders WHERE total > 100);

As a derived table (in FROM):
  SELECT dept, avg_sal FROM (
    SELECT department AS dept, AVG(salary) AS avg_sal
    FROM employees GROUP BY department
  ) WHERE avg_sal > 60000;

Key points:
- Inner query runs first, result feeds to outer query
- Scalar subquery returns one value (use with =, >, <)
- List subquery returns multiple values (use with IN)
- Subqueries must be in parentheses`
  },
  'Window Function': {
    title: 'Window Functions',
    explanation: `Window functions calculate values across rows related to current row WITHOUT collapsing them.

ROW_NUMBER - unique sequential number:
  SELECT name, salary, ROW_NUMBER() OVER (ORDER BY salary DESC) AS rank
  FROM employees;

RANK / DENSE_RANK - ranking with ties:
  SELECT title, rating, RANK() OVER (ORDER BY rating DESC) AS rank FROM movies;

PARTITION BY - window within groups:
  SELECT department, name, salary,
    RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS dept_rank
  FROM employees;

Running totals:
  SELECT order_date, total,
    SUM(total) OVER (ORDER BY order_date) AS running_total
  FROM orders;

Key points:
- OVER() defines the window
- PARTITION BY splits into groups (like GROUP BY but keeps all rows)
- ORDER BY in OVER() sets the order within each window
- Unlike GROUP BY, window functions keep every row`
  },
  'CASE': {
    title: 'CASE Expressions',
    explanation: `CASE adds if/then logic to your queries - like an IF statement in SQL.

Basic syntax:
  SELECT name,
    CASE WHEN salary > 80000 THEN 'High'
         WHEN salary > 50000 THEN 'Medium'
         ELSE 'Low' END AS salary_tier
  FROM employees;

In aggregation:
  SELECT
    COUNT(CASE WHEN survived = 1 THEN 1 END) AS survived,
    COUNT(CASE WHEN survived = 0 THEN 1 END) AS died
  FROM passengers;

With GROUP BY:
  SELECT
    CASE WHEN age < 18 THEN 'Child'
         WHEN age < 60 THEN 'Adult'
         ELSE 'Senior' END AS age_group,
    COUNT(*) AS count
  FROM passengers GROUP BY age_group;

Key points:
- CASE starts it, END finishes it
- WHEN condition THEN result
- ELSE handles everything not matched
- Can be used in SELECT, WHERE, ORDER BY, and aggregates`
  },
  'Date Functions': {
    title: 'Date Functions (SQLite)',
    explanation: `SQLite uses strftime() for date operations.

Extract parts of a date:
  strftime('%Y', date)  -- year (2024)
  strftime('%m', date)  -- month (01-12)
  strftime('%d', date)  -- day (01-31)
  strftime('%w', date)  -- day of week (0=Sunday)

Group by month:
  SELECT strftime('%Y-%m', order_date) AS month, COUNT(*)
  FROM orders GROUP BY month ORDER BY month;

Filter by year:
  SELECT * FROM orders WHERE strftime('%Y', order_date) = '2024';

Date differences:
  julianday('2024-12-31') - julianday('2024-01-01')  -- days between

Key points:
- Dates are typically stored as text: 'YYYY-MM-DD'
- strftime() is the main function for date manipulation
- Format codes: %Y=year, %m=month, %d=day, %H=hour, %M=minute
- Use GROUP BY with strftime() for time-series analysis`
  },
  'CTE': {
    title: 'Common Table Expressions (CTEs)',
    explanation: `CTEs (WITH clause) let you name a subquery and reference it like a table.

Basic syntax:
  WITH high_earners AS (
    SELECT * FROM employees WHERE salary > 80000
  )
  SELECT department, COUNT(*) FROM high_earners GROUP BY department;

Multiple CTEs:
  WITH dept_stats AS (
    SELECT department, AVG(salary) AS avg_sal FROM employees GROUP BY department
  ),
  high_depts AS (
    SELECT * FROM dept_stats WHERE avg_sal > 70000
  )
  SELECT * FROM high_depts;

Key points:
- WITH goes at the start, before SELECT
- Easier to read than nested subqueries
- Can reference earlier CTEs in later ones
- Same performance as subqueries in most databases`
  },
  'LIKE': {
    title: 'Pattern Matching with LIKE',
    explanation: `LIKE searches for patterns in text columns.

Wildcards:
  % matches any number of characters
  _ matches exactly one character

Examples:
  SELECT * FROM customers WHERE name LIKE 'J%';      -- starts with J
  SELECT * FROM movies WHERE title LIKE '%Love%';     -- contains Love
  SELECT * FROM employees WHERE name LIKE '___';      -- exactly 3 chars
  SELECT * FROM products WHERE code LIKE 'A_B%';      -- A, any char, B, then anything

Case sensitivity:
  LIKE is case-insensitive in SQLite by default for ASCII.

Key points:
- % = zero or more characters
- _ = exactly one character
- Use NOT LIKE to exclude patterns
- Often used for search/filter features`
  },
  'DISTINCT': {
    title: 'DISTINCT',
    explanation: `DISTINCT removes duplicate values from results.

Basic usage:
  SELECT DISTINCT genre FROM movies;
  (Lists each genre once)

With multiple columns:
  SELECT DISTINCT department, position FROM employees;
  (Unique combinations of department + position)

With COUNT:
  SELECT COUNT(DISTINCT genre) FROM movies;
  (How many unique genres exist)

Key points:
- DISTINCT goes right after SELECT
- Applies to the entire row (all selected columns together)
- COUNT(DISTINCT col) counts unique values
- Useful for finding unique categories, checking data variety`
  },
  'UNION': {
    title: 'UNION',
    explanation: `UNION combines results from two or more SELECT queries vertically.

UNION (removes duplicates):
  SELECT name FROM employees WHERE department = 'Engineering'
  UNION
  SELECT name FROM employees WHERE salary > 80000;

UNION ALL (keeps duplicates, faster):
  SELECT product FROM orders WHERE country = 'USA'
  UNION ALL
  SELECT product FROM orders WHERE country = 'UK';

Key points:
- Both SELECTs must have the same number of columns
- Column types should match
- UNION removes duplicates (slower), UNION ALL keeps them (faster)
- Column names come from the first SELECT`
  }
};

// Map skill/category names to topic explanation keys
const getTopicForSkill = (skill) => {
  const normalized = skill.trim();
  // Direct match
  if (TOPIC_EXPLANATIONS[normalized] !== undefined) {
    // If null, it's an alias - find the parent
    if (TOPIC_EXPLANATIONS[normalized] === null) {
      const aliases = { 'OR': 'AND', 'NOT': 'AND', 'COUNT': 'Aggregation', 'SUM': 'Aggregation', 'AVG': 'Aggregation', 'MIN': 'Aggregation', 'MAX': 'Aggregation', 'INNER JOIN': 'JOIN', 'LEFT JOIN': 'JOIN' };
      return aliases[normalized] || null;
    }
    return normalized;
  }
  // Fuzzy matching
  if (normalized.includes('JOIN')) return 'JOIN';
  if (normalized.includes('Window') || normalized.includes('RANK') || normalized.includes('ROW_NUMBER') || normalized.includes('PARTITION')) return 'Window Function';
  if (normalized.includes('Aggregate') || normalized.includes('Aggregation')) return 'Aggregation';
  if (normalized.includes('Subquer') || normalized.includes('subquer')) return 'Subquery';
  if (normalized.includes('CASE') || normalized.includes('Segment')) return 'CASE';
  if (normalized.includes('Date') || normalized.includes('date') || normalized.includes('strftime')) return 'Date Functions';
  if (normalized.includes('CTE') || normalized.includes('WITH')) return 'CTE';
  if (normalized.includes('LIKE') || normalized.includes('pattern')) return 'LIKE';
  if (normalized.includes('DISTINCT')) return 'DISTINCT';
  if (normalized.includes('UNION')) return 'UNION';
  if (normalized.includes('ORDER')) return 'ORDER BY';
  if (normalized.includes('GROUP')) return 'GROUP BY';
  if (normalized.includes('HAVING')) return 'HAVING';
  if (normalized.includes('WHERE') || normalized.includes('Filter')) return 'WHERE';
  if (normalized.includes('SELECT')) return 'SELECT';
  return null;
};

// Get the best topic explanation for a challenge based on its skills/category
const getTopicForChallenge = (challenge) => {
  if (!challenge) return null;
  // Priority: category first (most specific), then skills in order
  const categoryTopic = getTopicForSkill(challenge.category || '');
  if (categoryTopic) return categoryTopic;
  if (challenge.skills) {
    // Try skills in reverse order (later skills tend to be more advanced/relevant)
    for (let i = challenge.skills.length - 1; i >= 0; i--) {
      const topic = getTopicForSkill(challenge.skills[i]);
      if (topic) return topic;
    }
  }
  return null;
};

// Daily Challenge helpers - Resets at 11:00 GMT+3 daily
const getDailyChallengeDate = () => {
  const now = new Date();
  // Convert to GMT+3 (add 3 hours to UTC)
  const gmt3 = new Date(now.getTime() + (3 * 60 * 60 * 1000));
  const hours = gmt3.getUTCHours();
  
  // If before 11:00 GMT+3, use previous day
  if (hours < 11) {
    gmt3.setUTCDate(gmt3.getUTCDate() - 1);
  }
  
  return gmt3;
};

const getTodayString = () => {
  const date = getDailyChallengeDate();
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`;
};

// Get yesterday's date string using same GMT+3/11AM logic as getTodayString
const getYesterdayString = () => {
  const date = getDailyChallengeDate();
  date.setUTCDate(date.getUTCDate() - 1);
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`;
};

// Days between two YYYY-MM-DD strings (b - a). Positive if b > a.
const daysBetweenDateStrings = (a, b) => {
  const pa = new Date(a + 'T00:00:00Z').getTime();
  const pb = new Date(b + 'T00:00:00Z').getTime();
  return Math.round((pb - pa) / 86400000);
};

// YYYY-MM-DD that is N days before the given YYYY-MM-DD string.
const dateNDaysBefore = (dateStr, n) => {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() - n);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
};

// Get the current month/year prefix for filtering calendar dates (GMT+3 based)
const getCurrentMonthPrefix = () => {
  const date = getDailyChallengeDate();
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
};

// Get calendar display info (year, month, today's date) consistent with getTodayString
const getCalendarDisplayInfo = () => {
  const date = getDailyChallengeDate();
  return {
    year: date.getUTCFullYear(),
    month: date.getUTCMonth(),
    today: date.getUTCDate()
  };
};

const getChallengeForDayOffset = (offsetDays = 0, difficulty = null) => {
  if (dailyChallenges.length === 0) return null;
  const date = getDailyChallengeDate();
  // Use day of year to cycle through challenges
  const start = new Date(Date.UTC(date.getUTCFullYear(), 0, 0));
  const diff = date - start;
  const oneDay = 1000 * 60 * 60 * 24;
  const dayOfYear = Math.floor(diff / oneDay) + offsetDays;

  // Filter by difficulty if specified
  let availableChallenges = dailyChallenges;
  if (difficulty) {
    // Group similar difficulties
    const difficultyGroups = {
      'Easy': ['Easy'],
      'Medium': ['Easy', 'Medium'],
      'Hard': ['Medium', 'Hard']
    };
    const allowedDifficulties = difficultyGroups[difficulty] || [difficulty];
    availableChallenges = dailyChallenges.filter(c => allowedDifficulties.includes(c.difficulty));

    // Fallback to all challenges if no matches
    if (availableChallenges.length === 0) {
      availableChallenges = dailyChallenges;
    }
  }

  // JS modulo can be negative; normalize.
  const len = availableChallenges.length;
  const challengeIndex = ((dayOfYear % len) + len) % len;
  return availableChallenges[challengeIndex];
};

const getTodaysChallenge = (difficulty = null) => getChallengeForDayOffset(0, difficulty);
const getTomorrowsChallenge = (difficulty = null) => getChallengeForDayOffset(1, difficulty);

const getTimeUntilReset = () => {
  const now = new Date();
  // Convert to GMT+3
  const gmt3 = new Date(now.getTime() + (3 * 60 * 60 * 1000));
  const hours = gmt3.getUTCHours();
  const minutes = gmt3.getUTCMinutes();
  
  let hoursUntil, minutesUntil;
  if (hours >= 11) {
    // Next reset is tomorrow at 11:00
    hoursUntil = 24 - hours + 11 - 1;
    minutesUntil = 60 - minutes;
    if (minutesUntil === 60) {
      minutesUntil = 0;
      hoursUntil++;
    }
  } else {
    // Reset is today at 11:00
    hoursUntil = 11 - hours - 1;
    minutesUntil = 60 - minutes;
    if (minutesUntil === 60) {
      minutesUntil = 0;
      hoursUntil++;
    }
  }
  
  return { hours: hoursUntil, minutes: minutesUntil };
};

// ============ TOPIC DETECTION & RECOMMENDATION HELPERS ============

// Extract table names used in SQL query
const extractTablesFromSql = (sql, datasetTables) => {
  if (!sql || !datasetTables) return [];
  const upperSql = sql.toUpperCase();
  const tableNames = Object.keys(datasetTables);
  return tableNames.filter(table => {
    const upperTable = table.toUpperCase();
    // Check for FROM table, JOIN table, or table. references
    const patterns = [
      new RegExp(`FROM\\s+${upperTable}\\b`, 'i'),
      new RegExp(`JOIN\\s+${upperTable}\\b`, 'i'),
      new RegExp(`${upperTable}\\.`, 'i')
    ];
    return patterns.some(p => p.test(upperSql));
  });
};

// Format seconds to MM:SS
const formatTime = (seconds) => {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins}:${secs.toString().padStart(2, '0')}`;
};

// Paint a shareable PNG summary card of a weekly report onto a canvas.
// 1200×630 is social-ready (Twitter/LinkedIn cards, OpenGraph). Dark theme
// matches the app; hero stat pulls from top milestone when present, falls
// back to XP earned.
const drawShareCard = (canvas, { report, milestones = [], username, streak = 0 }) => {
  if (!canvas || !report) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  // Gradient background
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#1e1b4b');
  bg.addColorStop(1, '#0f172a');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // Purple accent stripe at top
  ctx.fillStyle = '#8b5cf6';
  ctx.fillRect(0, 0, W, 6);

  // Branding (top left)
  ctx.fillStyle = '#cbd5e1';
  ctx.font = '600 32px system-ui, -apple-system, sans-serif';
  ctx.fillText('SQL Quest', 60, 90);
  ctx.fillStyle = '#64748b';
  ctx.font = '400 20px system-ui, -apple-system, sans-serif';
  ctx.fillText('Weekly progress', 60, 118);

  // Week range (top right)
  ctx.fillStyle = '#94a3b8';
  ctx.font = '400 18px system-ui, -apple-system, sans-serif';
  ctx.textAlign = 'right';
  ctx.fillText(`${report.weekStart}  →  ${report.weekEnd}`, W - 60, 90);
  ctx.textAlign = 'left';

  // Hero line: top milestone OR "+XP earned"
  const heroMilestone = milestones[0];
  let heroText = heroMilestone
    ? `${heroMilestone.emoji}  ${heroMilestone.description}`
    : `+${report.summary.xpEarned} XP earned`;
  // Auto-shrink font if the string is long, rather than truncate and lose the number.
  ctx.fillStyle = '#f1f5f9';
  let heroFontSize = 56;
  if (heroText.length > 40) heroFontSize = 44;
  if (heroText.length > 52) heroFontSize = 36;
  ctx.font = `700 ${heroFontSize}px system-ui, -apple-system, sans-serif`;
  ctx.fillText(heroText, 60, 250);

  // Secondary stats row — 4 cells
  const stats = [
    ['Solved', String(report.summary.challengesSolved)],
    ['Daily', String(report.summary.dailyChallenges)],
    ['Streak', `${streak}d`],
    ['Avg', formatTime(report.summary.avgSolveTime)],
  ];
  const cellW = 270;
  const startY = 370;
  stats.forEach((s, i) => {
    const x = 60 + i * cellW;
    ctx.fillStyle = '#a78bfa';
    ctx.font = '700 54px system-ui, -apple-system, sans-serif';
    ctx.fillText(s[1], x, startY + 40);
    ctx.fillStyle = '#94a3b8';
    ctx.font = '500 20px system-ui, -apple-system, sans-serif';
    ctx.fillText(s[0], x, startY + 72);
  });

  // Skill callout — highest-rate skill this week. skillStats is ascending by rate,
  // so the last element is always the top.
  const topSkill = (report.skillStats && report.skillStats.length > 0)
    ? report.skillStats[report.skillStats.length - 1]
    : null;
  if (topSkill && topSkill.rate != null) {
    ctx.fillStyle = '#22c55e';
    ctx.font = '600 26px system-ui, -apple-system, sans-serif';
    ctx.fillText(`💪  ${topSkill.skill}: ${topSkill.rate}%`, 60, 550);
  }

  // Footer: username (left) + URL (right)
  ctx.fillStyle = '#64748b';
  ctx.font = '400 18px system-ui, -apple-system, sans-serif';
  if (username) ctx.fillText(`@${username}`, 60, H - 40);
  ctx.textAlign = 'right';
  ctx.fillText('sqlquest.app', W - 60, H - 40);
  ctx.textAlign = 'left';
};

// Inline SVG sparkline — renders a sequence of values as a tiny trend line.
// Used by the weekly report's Trend section. Self-contained, no deps.
// `values` is a number[] (most recent last). `invertTrend` flips the color
// logic so that "smaller is better" stats (like solve time) read correctly.
const Sparkline = ({ values = [], width = 120, height = 36, invertTrend = false, ariaLabel }) => {
  if (!values || values.length < 2) {
    return (
      <div style={{ width, height }} className="flex items-center justify-center text-xs text-gray-600">
        —
      </div>
    );
  }
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const pad = 3;
  const w = width - pad * 2;
  const h = height - pad * 2;
  const points = values.map((v, i) => {
    const x = pad + (i / (values.length - 1)) * w;
    const y = pad + h - ((v - min) / range) * h;
    return [x, y];
  });
  const path = points.map((p, i) => (i === 0 ? `M ${p[0]} ${p[1]}` : `L ${p[0]} ${p[1]}`)).join(' ');
  // Trend direction: last value vs first. Invert for "smaller is better" metrics.
  const delta = values[values.length - 1] - values[0];
  const isUp = invertTrend ? delta < 0 : delta > 0;
  const isDown = invertTrend ? delta > 0 : delta < 0;
  const stroke = isUp ? '#22c55e' : isDown ? '#ef4444' : '#64748b';
  const fillOpacity = 0.15;
  const lastPoint = points[points.length - 1];
  return (
    <svg width={width} height={height} role="img" aria-label={ariaLabel || 'trend'}>
      <defs>
        <linearGradient id={`sparkfill-${stroke.replace('#', '')}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity={fillOpacity} />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path
        d={`${path} L ${lastPoint[0]} ${height - pad} L ${points[0][0]} ${height - pad} Z`}
        fill={`url(#sparkfill-${stroke.replace('#', '')})`}
        stroke="none"
      />
      <path d={path} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={lastPoint[0]} cy={lastPoint[1]} r="2" fill={stroke} />
    </svg>
  );
};

// Detect SQL topic from query/solution
const detectSqlTopic = (sql) => {
  if (!sql) return 'General';
  const upperSql = sql.toUpperCase();
  
  // Check in order of specificity
  if (upperSql.includes('WINDOW') || upperSql.includes('OVER(') || upperSql.includes('OVER (')) return 'Window Functions';
  if (upperSql.includes('EXISTS') || upperSql.includes('NOT EXISTS')) return 'EXISTS';
  if (upperSql.includes('HAVING')) return 'GROUP BY & HAVING';
  if (upperSql.includes('GROUP BY')) return 'GROUP BY';
  if (upperSql.includes('LEFT JOIN') || upperSql.includes('LEFT OUTER JOIN')) return 'LEFT JOIN';
  if (upperSql.includes('RIGHT JOIN') || upperSql.includes('RIGHT OUTER JOIN')) return 'RIGHT JOIN';
  if (upperSql.includes('FULL JOIN') || upperSql.includes('FULL OUTER JOIN')) return 'FULL JOIN';
  if (upperSql.includes('INNER JOIN') || upperSql.includes('JOIN')) return 'JOIN';
  if (upperSql.includes('UNION')) return 'UNION';
  if (upperSql.includes('CASE WHEN') || upperSql.includes('CASE\n')) return 'CASE';
  if (upperSql.includes('LIKE')) return 'LIKE';
  if (upperSql.includes('IN (SELECT') || upperSql.includes('IN(SELECT')) return 'Subqueries';
  if (upperSql.includes('BETWEEN')) return 'BETWEEN';
  if (upperSql.includes('ORDER BY')) return 'ORDER BY';
  if (upperSql.includes('DISTINCT')) return 'DISTINCT';
  if (upperSql.includes('COUNT(') || upperSql.includes('SUM(') || upperSql.includes('AVG(') || upperSql.includes('MAX(') || upperSql.includes('MIN(')) return 'Aggregation';
  if (upperSql.includes('WHERE')) return 'WHERE';
  return 'SELECT';
};

// Detect ALL SQL concepts used in a query (returns array)
const detectAllSqlConcepts = (sql) => {
  if (!sql) return [];
  const upperSql = sql.toUpperCase();
  const concepts = [];
  
  // Window Functions - specific types
  if (upperSql.includes('ROW_NUMBER(')) concepts.push('ROW_NUMBER');
  if (upperSql.includes('RANK(')) concepts.push('RANK');
  if (upperSql.includes('DENSE_RANK(')) concepts.push('DENSE_RANK');
  if (upperSql.includes('LAG(')) concepts.push('LAG');
  if (upperSql.includes('LEAD(')) concepts.push('LEAD');
  if (upperSql.includes('NTILE(')) concepts.push('NTILE');
  if (upperSql.includes('OVER(') || upperSql.includes('OVER (')) concepts.push('Window Functions');
  
  // JOINs
  if (upperSql.includes('LEFT JOIN') || upperSql.includes('LEFT OUTER JOIN')) concepts.push('LEFT JOIN');
  if (upperSql.includes('RIGHT JOIN')) concepts.push('RIGHT JOIN');
  if (upperSql.includes('FULL JOIN') || upperSql.includes('FULL OUTER JOIN')) concepts.push('FULL JOIN');
  if (upperSql.includes('CROSS JOIN')) concepts.push('CROSS JOIN');
  if ((upperSql.includes('INNER JOIN') || upperSql.includes(' JOIN ')) && !concepts.some(c => c.includes('JOIN'))) concepts.push('JOIN');
  
  // Subqueries
  if (upperSql.includes('(SELECT')) concepts.push('Subquery');
  if (upperSql.includes('WITH ') && upperSql.includes(' AS (')) concepts.push('CTE');
  if (upperSql.includes('EXISTS')) concepts.push('EXISTS');
  if (upperSql.includes('NOT EXISTS')) concepts.push('NOT EXISTS');
  
  // Aggregations
  if (upperSql.includes('COUNT(')) concepts.push('COUNT');
  if (upperSql.includes('SUM(')) concepts.push('SUM');
  if (upperSql.includes('AVG(')) concepts.push('AVG');
  if (upperSql.includes('MAX(')) concepts.push('MAX');
  if (upperSql.includes('MIN(')) concepts.push('MIN');
  
  // Grouping & Filtering
  if (upperSql.includes('GROUP BY')) concepts.push('GROUP BY');
  if (upperSql.includes('HAVING')) concepts.push('HAVING');
  if (upperSql.includes('WHERE')) concepts.push('WHERE');
  if (upperSql.includes('ORDER BY')) concepts.push('ORDER BY');
  if (upperSql.includes('LIMIT')) concepts.push('LIMIT');
  
  // Operators & Functions
  if (upperSql.includes('CASE WHEN') || upperSql.includes('CASE\n')) concepts.push('CASE WHEN');
  if (upperSql.includes('COALESCE')) concepts.push('COALESCE');
  if (upperSql.includes('NULLIF')) concepts.push('NULLIF');
  if (upperSql.includes('BETWEEN')) concepts.push('BETWEEN');
  if (upperSql.includes('LIKE')) concepts.push('LIKE');
  if (upperSql.includes('IN (')) concepts.push('IN');
  if (upperSql.includes('DISTINCT')) concepts.push('DISTINCT');
  if (upperSql.includes('UNION')) concepts.push('UNION');
  
  // Date/String functions
  if (upperSql.includes('STRFTIME') || upperSql.includes('DATE(') || upperSql.includes('DATETIME(')) concepts.push('Date Functions');
  if (upperSql.includes('SUBSTR') || upperSql.includes('UPPER(') || upperSql.includes('LOWER(') || upperSql.includes('TRIM(')) concepts.push('String Functions');
  if (upperSql.includes('ROUND(') || upperSql.includes('ABS(') || upperSql.includes('CAST(')) concepts.push('Math/Conversion');
  
  return [...new Set(concepts)]; // Remove duplicates
};

