  // ── Goals Mentor modal state ───────────────────────────────────────────
  // The conversational onboarding that discovers a user's career goal &
  // sector. Three short questions, each can be skipped. Day 1 ships with
  // local keyword-extraction as a placeholder; Day 2 swaps in the AI Tutor
  // edge function with `mode: "goal_discovery"`. The modal is fundamentally
  // a chat UI: messages list + text input + (post-Q3) confirm card.
  const [showGoalsMentor, setShowGoalsMentor] = useState(false);
  // Phase machine: 'q1' → user answered Q1 → 'q2' → answered Q2 → 'q3' →
  // answered Q3 → 'wrap_up' (extracted summary shown). Confirm closes the
  // modal; "Düzelt" sends to 'editing' with sector dropdown + free-text role.
  const [mentorPhase, setMentorPhase] = useState('q1');
  const [mentorMessages, setMentorMessages] = useState([]); // [{role:'mentor'|'user', content}]
  const [mentorInput, setMentorInput] = useState('');
  // Accumulated extraction across the conversation. Populated by the
  // placeholder extractor today, by the LLM tomorrow. Each turn merges
  // partial values; null fields stay null.
  const [mentorExtracted, setMentorExtracted] = useState(null);
  const [mentorBusy, setMentorBusy] = useState(false); // disables submit during async work

  // ── Goals Mentor handlers ──────────────────────────────────────────────

  // Call AI Tutor in goal_discovery mode. Sends the chat history (user
  // turns become anthropic 'user' role, mentor turns become 'assistant')
  // and expects the model to return strict JSON with extracted fields.
  // Returns the parsed object on success, null on any failure (rate limit,
  // network, JSON parse, etc) — caller falls back to local extraction.
  const callGoalsMentorLLM = useCallback(async (chatMessages) => {
    if (!window.SUPABASE_URL || !window.SUPABASE_ANON_KEY) return null;
    try {
      // Anthropic conversation format: alternating user/assistant. Drop any
      // leading mentor messages (system prompt already has the context, and
      // Anthropic requires the first message to be 'user').
      const anthropicMessages = chatMessages
        .map((m) => ({ role: m.role === 'mentor' ? 'assistant' : 'user', content: m.content }));
      const validMessages = normalizeAiMessages(anthropicMessages);
      if (validMessages.length === 0) return null;

      const aiUsername = currentUser
        || `guest_${(typeof localStorage !== 'undefined' && localStorage.getItem('sqlquest_device_id')) || 'unknown'}`;

      const response = await fetch(`${window.SUPABASE_URL}/functions/v1/ai-tutor`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${window.SUPABASE_ANON_KEY}`,
        },
        body: JSON.stringify({
          username: aiUsername,
          messages: validMessages,
          mode: 'goal_discovery',
        }),
      });
      if (!response.ok) return null;
      const data = await response.json();
      if (!data?.text) return null;

      // Parse JSON. The model is instructed to output JSON only — but be
      // defensive: strip any markdown fences and attempt parse.
      let jsonStr = String(data.text).trim();
      if (jsonStr.startsWith('```')) {
        jsonStr = jsonStr.replace(/^```(?:json)?\s*/, '').replace(/\s*```\s*$/, '');
      }
      try {
        return JSON.parse(jsonStr);
      } catch (_) {
        // Sometimes the model wraps the JSON in extra prose despite the
        // instruction. Try to extract the first balanced JSON object.
        const match = jsonStr.match(/\{[\s\S]*\}/);
        if (match) {
          try { return JSON.parse(match[0]); } catch (_) { /* give up */ }
        }
        return null;
      }
    } catch (_) {
      return null;
    }
  }, [currentUser]);

  // Called by the Coach tab opt-in pop-up, the "Personalize further" button
  // on legacy onboarding step 3, or the ?goals=mentor URL param. Resets
  // chat state and shows Q1.
  const openGoalsMentor = useCallback(() => {
    const lang = resolveLang();
    setMentorPhase('q1');
    setMentorMessages([{ role: 'mentor', content: MENTOR_QUESTIONS[lang].q1 }]);
    setMentorInput('');
    setMentorExtracted(null);
    setMentorBusy(false);
    setShowGoalsMentor(true);
  }, []);

  // Submit user's answer for the current phase. Day 1 uses local keyword
  // extraction; Day 2 will swap in an AI Tutor edge-function call here.
  // The function signature stays the same — only the extraction step changes.
  const submitMentorAnswer = useCallback(() => {
    const text = mentorInput.trim();
    if (!text || mentorBusy) return;
    const lang = resolveLang();

    // Append user message + clear input immediately so the UI feels snappy.
    setMentorMessages((prev) => [...prev, { role: 'user', content: text }]);
    setMentorInput('');
    setMentorBusy(true);

    // Per-turn local extraction (instant feedback). For Q1/Q2 this is the
    // only signal we use. For Q3 we still run it as fallback, then call
    // the LLM in goal_discovery mode to refine the extraction with cleaner
    // structured output + a localized summary line.
    setTimeout(async () => {
      const partial = extractGoalsFromText(text);
      const localMerged = mergeGoals(mentorExtracted, partial);
      setMentorExtracted(localMerged);

      // Phase transitions: q1 → q2 → q3 → wrap_up
      if (mentorPhase === 'q1') {
        setMentorMessages((prev) => [
          ...prev, { role: 'mentor', content: MENTOR_QUESTIONS[lang].q2 },
        ]);
        setMentorPhase('q2');
        setMentorBusy(false);
        return;
      }
      if (mentorPhase === 'q2') {
        setMentorMessages((prev) => [
          ...prev, { role: 'mentor', content: MENTOR_QUESTIONS[lang].q3 },
        ]);
        setMentorPhase('q3');
        setMentorBusy(false);
        return;
      }
      if (mentorPhase === 'q3') {
        // Day 2 — LLM refinement. Build the full chat history including
        // the user message we just appended (state may not be flushed yet).
        const chatForLLM = [...mentorMessages, { role: 'user', content: text }];
        const llm = await callGoalsMentorLLM(chatForLLM);

        if (llm) {
          // LLM result wins per-field, with local merged as fallback for
          // anything LLM left null. raw_text always uses local concat.
          const refined = {
            sector: llm.sector || localMerged?.sector || null,
            role: llm.role || localMerged?.role || null,
            motivation: llm.motivation || localMerged?.motivation || null,
            experience: llm.experience || localMerged?.experience || null,
            target: llm.target || localMerged?.target || null,
            raw_text: localMerged?.raw_text || null,
            inferred_at: new Date().toISOString(),
            ai_confidence: typeof llm.ai_confidence === 'number'
              ? Math.max(0, Math.min(1, llm.ai_confidence))
              : 0.7,
            user_confirmed: false,
            // LLM-generated summary kept for the wrap message + future debug.
            summary_for_user: typeof llm.summary_for_user === 'string'
              ? llm.summary_for_user
              : null,
          };
          setMentorExtracted(refined);
          // Use LLM summary if it gave one, else compose from canonical copy.
          const wrap = refined.summary_for_user
            || (refined.sector
              ? MENTOR_QUESTIONS[lang].wrap_with_sector(
                  window.getSectorDisplayName?.(refined.sector, lang) || refined.sector)
              : MENTOR_QUESTIONS[lang].wrap_no_sector);
          setMentorMessages((prev) => [...prev, { role: 'mentor', content: wrap }]);
        } else {
          // LLM unavailable / failed / parse-error — fall back to local
          // extraction. User experience degrades silently (no error banner).
          const sectorDisplay = localMerged?.sector
            ? (window.getSectorDisplayName?.(localMerged.sector, lang) || localMerged.sector)
            : null;
          const wrap = sectorDisplay
            ? MENTOR_QUESTIONS[lang].wrap_with_sector(sectorDisplay)
            : MENTOR_QUESTIONS[lang].wrap_no_sector;
          setMentorMessages((prev) => [...prev, { role: 'mentor', content: wrap }]);
        }
        setMentorPhase('wrap_up');
        setMentorBusy(false);
      }
    }, 250);
  }, [mentorInput, mentorBusy, mentorPhase, mentorExtracted, mentorMessages, callGoalsMentorLLM]);

  // User confirmed the extracted summary. Persist to userGoals + localStorage
  // (so guests get a copy too), fire telemetry to Supabase, close the modal.
  // Telemetry is best-effort — failures never block the user's flow.
  const confirmMentorGoals = useCallback(() => {
    const finalGoals = {
      sector: mentorExtracted?.sector || window.GENERIC_SECTOR_ID,
      role: mentorExtracted?.role || null,
      motivation: mentorExtracted?.motivation || null,
      experience: mentorExtracted?.experience || null,
      target: mentorExtracted?.target || null,
      raw_text: mentorExtracted?.raw_text || null,
      inferred_at: mentorExtracted?.inferred_at || new Date().toISOString(),
      ai_confidence: mentorExtracted?.ai_confidence || null,
      user_confirmed: true,
    };
    setUserGoals(finalGoals);
    if (finalGoals.sector && finalGoals.sector !== window.GENERIC_SECTOR_ID) {
      const datasetId = getFoundationDatasetIdForSector(finalGoals.sector);
      setFoundationDatasetId(datasetId);
      try { localStorage.setItem(FOUNDATION_DATASET_STORAGE_KEY, datasetId); } catch (_) { /* ignore */ }
    }
    // Belt-and-suspenders: write a localStorage backup so guests retain
    // their goals across sessions even though they don't trigger the
    // userData save loop (which is gated on currentUser && !isGuest).
    try {
      localStorage.setItem('sqlquest_user_goals', JSON.stringify(finalGoals));
    } catch (_) { /* quota / private-mode — ignore */ }

    // Fire Supabase telemetry (best-effort, fire-and-forget). The capture-goal
    // edge function applies per-device rate limits + length caps server-side
    // so we don't have to worry about overshooting from the client.
    if (window.SUPABASE_URL && window.SUPABASE_ANON_KEY) {
      try {
        let deviceId = localStorage.getItem('sqlquest_device_id');
        if (!deviceId) {
          deviceId = (window.crypto?.randomUUID?.()
            || (Date.now() + '_' + Math.random().toString(36).slice(2, 10)));
          localStorage.setItem('sqlquest_device_id', deviceId);
        }
        const lang = resolveLang();
        fetch(`${window.SUPABASE_URL}/functions/v1/capture-goal`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'apikey': window.SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${window.SUPABASE_ANON_KEY}`,
          },
          body: JSON.stringify({
            device_id: deviceId,
            user_handle: currentUser || null,
            sector: finalGoals.sector,
            role: finalGoals.role,
            motivation: finalGoals.motivation,
            experience: finalGoals.experience,
            target: finalGoals.target,
            raw_text: finalGoals.raw_text || '',
            ai_confidence: finalGoals.ai_confidence,
            user_confirmed: true,
            language: lang,
            app_version: (typeof window !== 'undefined' && window.APP_VERSION) || null,
          }),
          keepalive: true,
        }).catch(() => { /* tracking failures must never break the flow */ });
      } catch (_) { /* localStorage / fetch unavailable — ignore */ }
    }

    setShowGoalsMentor(false);
  }, [mentorExtracted, currentUser]);

  // User dismissed the mentor (skip, X, escape). If `rememberDismissal`,
  // also stamp goalsPromptDismissedAt so the opt-in pop-up doesn't return.
  // The user can always re-open via Profile/Settings → "Set my goals".
  const dismissGoalsMentor = useCallback((rememberDismissal) => {
    setShowGoalsMentor(false);
    if (rememberDismissal) {
      const ts = Date.now();
      setGoalsPromptDismissedAt(ts);
      try {
        localStorage.setItem('sqlquest_goals_prompt_dismissed_at', String(ts));
      } catch (_) { /* ignore */ }
    }
  }, []);

  // Onboarding state
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1);
  const [onboardingData, setOnboardingData] = useState({ experience: null, goal: null });
  const [firstRunCompleted, setFirstRunCompleted] = useState(() => {
    try {
      return localStorage.getItem(FIRST_RUN_COMPLETED_KEY) === 'true'
        || !!localStorage.getItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY);
    } catch (_) {
      return false;
    }
  });
  const [firstRunGoal, setFirstRunGoal] = useState(() => {
    try {
      return localStorage.getItem(FIRST_RUN_GOAL_KEY)
        || (localStorage.getItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY) ? 'zero' : '');
    } catch (_) {
      return '';
    }
  });
  const [firstRunLevel, setFirstRunLevel] = useState(() => {
    try {
      return localStorage.getItem(FIRST_RUN_LEVEL_KEY)
        || (localStorage.getItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY) ? 'brand-new' : '');
    } catch (_) {
      return '';
    }
  });
  const [firstRunTrack, setFirstRunTrack] = useState(() => {
    try {
      return localStorage.getItem(FIRST_RUN_TRACK_KEY)
        || (localStorage.getItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY) ? 'foundations-zero' : '');
    } catch (_) {
      return '';
    }
  });
  const [showZeroSqlLesson, setShowZeroSqlLesson] = useState(false);
  const [foundationsRoadmapLessonId, setFoundationsRoadmapLessonId] = useState(() => loadSavedFoundationActiveLessonId());
  const [foundationDatasetId, setFoundationDatasetId] = useState(() => {
    try {
      return getFoundationDatasetIdForSector(localStorage.getItem(FOUNDATION_DATASET_STORAGE_KEY) || 'hr');
    } catch (_) {
      return 'hr';
    }
  });
  const [firstRunQuizAnswers, setFirstRunQuizAnswers] = useState({});
  const firstRunQuizAnswersRef = useRef(firstRunQuizAnswers);
  firstRunQuizAnswersRef.current = firstRunQuizAnswers;
  const [showFirstRunManualLevels, setShowFirstRunManualLevels] = useState(false);
  const [showFirstEntryTour, setShowFirstEntryTour] = useState(() => {
    try { return !localStorage.getItem(FIRST_ENTRY_TOUR_KEY); } catch (_) { return true; }
  });
  const [showChallengesEntryTour, setShowChallengesEntryTour] = useState(() => {
    try { return !localStorage.getItem(CHALLENGES_ENTRY_TOUR_KEY); } catch (_) { return true; }
  });
  // (legacy showTutorial / showUiTour state removed 2026-04-21; superseded by
  //  the OnboardingTour spotlight component — see showOnboardingTour below)
  const [milestonePopup, setMilestonePopup] = useState(null); // { title, message, emoji }
  const [showSubscriptionModal, setShowSubscriptionModal] = useState(false);
  
  // Pro gate helper
  const isPro = userProStatus;

  // Expiry-aware Pro, for deciding whether to ASK — never for granting access.
  //
  // `userProStatus` is the raw `proStatus` flag (set from userData at login,
  // app.jsx ~16143) and it is stale-true for dozens of expired trials. The
  // paywall gate read it, so those users were silently exempted from every
  // upgrade prompt: measured 2026-08-07, 8 of the 19 engaged-and-active users
  // who had NEVER seen the offer carried proStatus=true, four of them trials
  // that expired in July. The worst case is a 104-solve user, active that day,
  // labelled `monthly` by the client-side auto-renew with no Stripe record —
  // the single most engaged account in the set, never once asked to buy.
  //
  // This is the project's own P3 in miniature: client state is not evidence of
  // a transaction. Money truth lives in `pro_events` with reason
  // 'stripe_webhook'; the client cannot see that, but it CAN at least respect
  // the expiry date it wrote down itself.
  //
  // Deliberately NOT wired into feature gates. Revoking Hard challenges and
  // the tutor mid-session from someone who believes they are Pro is a business
  // decision with a support cost, and it is not this change. Asking them is.
  const proLiveForOffer = userProStatus && (
    proType === 'lifetime' || (proExpiry && new Date(proExpiry) > new Date())
  );
  const AI_LIMIT_FREE = 20;
  const AI_LIMIT_PRO = 50; // matches backend monthly tier; actual limit syncs from API response
  const aiLimit = isPro ? AI_LIMIT_PRO : AI_LIMIT_FREE;
  const WARMUP_FREE_LIMIT = 15;
  const THIRTY_DAY_FREE_LIMIT = 10;

  const writeProEvent = (event, reason, metadata = {}) => {
    try {
      supabaseFetch('pro_events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: JSON.stringify({
          event,
          username: currentUser || 'guest',
          reason,
          // `aid` rides on every event so the rows that write the literal
          // 'guest' for username (app_opened, pro_checkout_returned, half of
          // pro_purchase_completed — see src/utils/anon-id.js for the counts)
          // can still be stitched to the rest of that browser's history.
          // username is deliberately left alone: the Aug 3 read compares
          // against the existing series and must not see a redefinition.
          metadata: JSON.stringify({ ...metadata, aid: getAnonId() }),
          created_at: new Date().toISOString()
        })
      }).catch(() => {}); // fire and forget
    } catch(e) {} // never block UI
  };

  // Declared intent from the post-first-solve ask (interview / job_ready /
  // learning / exploring). Read fresh each call — cheap, and the user may
  // answer mid-session.
  const getUserIntent = () => {
    try { return localStorage.getItem('sqlquest_user_intent') || null; } catch (_) { return null; }
  };

  // Answer key for the email micro-lesson quizzes. KEEP IN SYNC with
  // MICRO_LESSONS in supabase/functions/skill-decay/index.ts.
  const QUIZ_ANSWERS = {
    select_basics:   { correct: 'B', title: 'SELECT basics',   explain: 'SELECT name picks just that column; LIMIT 3 caps the rows.' },
    filtering:       { correct: 'C', title: 'WHERE filtering', explain: 'WHERE runs before grouping; HAVING filters after aggregation.' },
    aggregation:     { correct: 'A', title: 'Aggregation',     explain: 'COUNT(col) skips NULLs — 10 rows minus 2 NULLs = 8.' },
    group_by:        { correct: 'B', title: 'GROUP BY',        explain: 'Aggregate conditions live in HAVING — WHERE cannot see COUNT(*).' },
    joins:           { correct: 'B', title: 'JOINs',           explain: 'LEFT JOIN keeps every left-side row, filling the right with NULLs.' },
    subqueries:      { correct: 'B', title: 'Subqueries',      explain: 'An aggregate subquery collapses to a single value to compare against.' },
    string_functions:{ correct: 'B', title: 'String functions', explain: 'SQLite GROUP_CONCAT takes no ORDER BY — order rows in a subquery first.' },
    date_functions:  { correct: 'B', title: 'Date functions',  explain: 'JULIANDAY turns dates into numbers you can subtract; text dates cannot.' },
    case_statements: { correct: 'B', title: 'CASE logic',      explain: 'CASE checks WHENs top to bottom; the first match wins.' },
    window_functions:{ correct: 'B', title: 'Window functions', explain: 'RANK leaves gaps after ties: 1, 2, 2, then 4.' },
    set_operations:  { correct: 'A', title: 'Set operations',  explain: 'UNION dedupes; UNION ALL keeps everything (and is faster).' },
    null_handling:   { correct: 'B', title: 'NULL handling',   explain: 'NULL never equals anything — IS NULL is the only correct test.' },
  };

  // Parse the quiz deep-link once on mount. Event fires immediately (the
  // click IS the measurement); the modal renders the verdict.
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const slug = params.get('quiz');
      const pick = (params.get('pick') || '').toUpperCase();
      if (!slug || !QUIZ_ANSWERS[slug] || !['A', 'B', 'C'].includes(pick)) return;
      trackActivationEvent('quiz_answered', {
        skill: slug, pick, correct: pick === QUIZ_ANSWERS[slug].correct,
      });
      setQuizLanding({ slug, pick });
    } catch (_) {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Any qualifying practice (challenge solve, daily challenge, lesson
  // exercise) advances the daily streak — Duolingo's bar is "did you
  // practice today", not "did you visit one specific mode". Gap handling
  // (freezes, resets) lives in the load path; mid-session we only ever
  // move forward by one day, at most once per local day.
  const recordDailyActivity = () => {
    try {
      const today = getTodayString();
      if (lastStreakDay === today) return;
      const newStreak = (dailyStreak || 0) + 1;
      setDailyStreak(newStreak);
      setLastStreakDay(today);
      if (newStreak > (maxDailyStreak || 0)) setMaxDailyStreak(newStreak);
      // Low-tier celebrations matter most: the old ladder started at day 5,
      // which nobody reached because the counter never counted.
      if ([2, 3, 7, 14, 30, 50, 100].includes(newStreak)) {
        setTimeout(() => showMilestone(
          '🔥',
          `${newStreak}-day streak!`,
          newStreak < 7
            ? 'Same time tomorrow — streaks are built one day at a time.'
            : 'That\'s a real habit. Keep the chain alive.'
        ), 900);
      }
    } catch (_) {}
  };

  // ── Checkout launch (H11) ──────────────────────────────────────────
  const CHECKOUT_LINKS = {
    monthly: 'https://buy.stripe.com/bJe14o2uleSw8m20nOdMI0a',
    annual: 'https://buy.stripe.com/bJe9AU0md4dScCi7QgdMI0b',
    lifetime: 'https://buy.stripe.com/6oUfZi3ypaCgeKqfiIdMI0c',
  };

  const resolveCheckoutEmail = () => {
    try {
      const userData = JSON.parse(localStorage.getItem(`sqlquest_user_${currentUser}`) || '{}');
      return userData.email || localStorage.getItem('sqlquest_checkout_email') || '';
    } catch (_) { return ''; }
  };

  // Navigate to the Stripe payment link. Same-tab on purpose: in-app
  // browsers (LinkedIn's WebView especially — our main social channel)
  // block window.open silently, killing checkout with no error. The
  // ?payment=success redirect is built for a same-tab round trip; the
  // purchase-user stash survives navigation.
  const launchCheckout = (plan, email) => {
    // Stash the purchasing identity: the payment-link redirect lands in
    // the checkout tab as a FRESH app load, and guest sessions don't
    // survive reloads — without this the buyer returns as a different
    // guest and never sees their Pro.
    try { localStorage.setItem('sqlquest_purchase_user', currentUser || ''); } catch (_) {}
    // Email rides on the click event so the checkout-abandon cron can
    // reach guests — they have no users-table row to look up.
    trackActivationEvent('pro_checkout_clicked', { plan, email: email || null });
    // Leave a breadcrumb so the next app load can tell WHY a click didn't
    // become a purchase. Until now the funnel went silent between the click
    // and the Stripe webhook, so "the button did nothing" and "they saw the
    // price and passed" were indistinguishable — and two of our most engaged
    // users (more solves than the one person who did buy) cycled through
    // three plans in under 40 seconds and left, which reads like the former.
    //
    // `left` is stamped from pagehide: if the browser never navigated away,
    // the redirect itself failed. That's the diagnosis no timing heuristic
    // can give you, so it's recorded rather than inferred.
    try {
      localStorage.setItem('sqlquest_checkout_pending', JSON.stringify({ plan, at: Date.now(), left: false }));
      const markLeft = () => {
        try {
          const m = JSON.parse(localStorage.getItem('sqlquest_checkout_pending') || 'null');
          if (m) localStorage.setItem('sqlquest_checkout_pending', JSON.stringify({ ...m, left: true }));
        } catch (_) { /* ignore */ }
      };
      window.addEventListener('pagehide', markLeft, { once: true });
    } catch (_) { /* ignore */ }
    const promo = (() => { try { return sessionStorage.getItem('sqlquest_promo') || ''; } catch (_) { return ''; } })();
    const promoSuffix = promo ? `&prefilled_promo_code=${encodeURIComponent(promo)}` : '';
    window.location.href = `${CHECKOUT_LINKS[plan]}?prefilled_email=${encodeURIComponent(email || '')}&client_reference_id=${encodeURIComponent(currentUser)}${promoSuffix}`;
  };

  // Plan button entry point: users with an email on file go straight to
  // Stripe; the rest get the one-field receipt-email step (skippable).
  const beginCheckout = (plan) => {
    const email = resolveCheckoutEmail();
    // Record the PLAN CLICK here, before the email branch.
    //
    // `pro_checkout_clicked` fires inside launchCheckout, which is only
    // reached when an email is already on file. Anyone without one — every
    // guest, and any registered user on a device whose localStorage lacks it —
    // clicks a plan, gets an email form, and produces no event at all. The
    // funnel goes dark at the exact moment of highest intent, and "nobody
    // clicked" becomes indistinguishable from "everybody hit the email wall".
    //
    // Today that distinction is academic: 105 offer impressions in the 14 days
    // to 2026-08-14 produced zero plan clicks AND zero email-gate events, so
    // nobody is reaching either path. It stops being academic the moment one
    // person does, which is precisely when we will want to trust the number.
    //
    // A separate event rather than moving pro_checkout_clicked: that series
    // runs back to 2026-07-10 and changing what it means mid-flight would
    // silently rewrite the history it is used to read.
    trackActivationEvent('pro_plan_clicked', {
      plan,
      hadEmailOnFile: !!email,
      // false here means the user is about to meet an email form they did not
      // ask for, between deciding to buy and being allowed to pay.
    });
    if (email) { launchCheckout(plan, email); return; }
    setCheckoutEmailInput('');
    setCheckoutPendingPlan(plan);
  };

  // Activation funnel analytics — fire-and-forget. Uses the existing
  // pro_events table so we can measure first success before adding schema.
  const trackActivationEvent = (event, metadata = {}, options = {}) => {
    try {
      if (options.onceKey) {
        const key = `sqlquest_funnel_${options.onceKey}_${currentUser || 'guest'}`;
        if (localStorage.getItem(key)) return;
        localStorage.setItem(key, '1');
      }
      writeProEvent(event, 'activation_funnel', {
        ...metadata,
        arrivalSrc: localStorage.getItem('sqlquest_arrival_src') || null,
        intent: getUserIntent(),
        // Coarse geo proxy for the PPP-pricing question: do checkout
        // clickers who never pay cluster in low-PPP timezones? No IP, no
        // consent-scope creep — the browser timezone is enough signal.
        tz: (() => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone || null; } catch (_) { return null; } })(),
        // Viewport, because "do people give up more on mobile?" was
        // unanswerable on 2026-08-06 — 15 of 28 users who opened challenge 91
        // fired no further event, and the only device signal available was the
        // timezone. Width is what matters (the Run button sat 325px below the
        // fold at 375px wide), so bucket it rather than storing raw pixels.
        viewport: (() => {
          try {
            const w = window.innerWidth;
            if (!w) return null;
            const band = w < 768 ? 'mobile' : w < 1024 ? 'tablet' : 'desktop';
            return `${band}:${w}x${window.innerHeight}`;
          } catch (_) { return null; }
        })(),
        solvedCount: solvedChallenges.size,
        attemptCount: challengeAttempts.length,
        isGuest: !!isGuest,
      });
    } catch (_) {}
  };

  // ── Share loop ────────────────────────────────────────────────────
  // The shareable profile URL. Always /u/:handle (api/u.js writes the
  // per-profile og: tags there) and always carrying ?ref=, so the
  // track-referral function — deployed for months with zero events, because
  // nothing ever produced a link that fed it — finally has an input.
  const profileShareUrl = () => {
    const h = String(currentUser || '').toLowerCase().trim();
    if (!h) return null;
    const base = (typeof getAppUrl === 'function' ? getAppUrl() : 'https://sqlquest.app')
      .replace(/\/+$/, '')
      .replace(/\/app(\.html)?$/, '');
    return `${base}/u/${encodeURIComponent(h)}/?ref=${encodeURIComponent(h)}`;
  };

  const copyProfileLink = async () => {
    const url = profileShareUrl();
    if (!url) return;
    let how = 'clipboard';
    try {
      await navigator.clipboard.writeText(url);
    } catch (_) {
      // Older/insecure contexts: fall back to a selectable prompt rather than
      // silently doing nothing.
      how = 'prompt';
      try { window.prompt('Copy your profile link:', url); } catch (_) { how = 'failed'; }
    }
    trackActivationEvent('profile_link_copied', { how, url });
    if (how !== 'failed' && typeof showMilestone === 'function') {
      showMilestone('🔗', i18n_t('profile', 'linkCopied'), i18n_t('profile', 'linkCopiedBody'));
    }
  };

  // Feedback submission. Writes straight to the feedback table via the same
  // anon REST path writeProEvent uses. Returns true/false so the widget can
  // show a real error instead of pretending it sent — the entire point of this
  // channel is that a message doesn't silently disappear, which is exactly
  // what the support@sqlquest.app mailto has been doing (no MX on the domain).
  const submitFeedback = async ({ message, contact, topic }) => {
    const payload = {
      username: currentUser || 'guest',
      message,
      contact,
      screen: (typeof activeTab !== 'undefined' && activeTab) || 'unknown',
      context: {
        topic: topic || null,
        solvedCount: solvedChallenges.size,
        isGuest: !!isGuest,
        isPro: !!isPro,
        intent: getUserIntent(),
        arrivalSrc: (() => { try { return localStorage.getItem('sqlquest_arrival_src'); } catch (_) { return null; } })(),
        tz: (() => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone || null; } catch (_) { return null; } })(),
        lang: (typeof navigator !== 'undefined' && navigator.language) || null,
        viewport: (typeof window !== 'undefined') ? `${window.innerWidth}x${window.innerHeight}` : null,
        ua: (typeof navigator !== 'undefined' ? navigator.userAgent : '').slice(0, 200),
      },
      created_at: new Date().toISOString(),
    };
    try {
      // Direct fetch, NOT supabaseFetch: that helper returns null both when a
      // return=minimal write succeeds (empty body) and when it fails, so it
      // cannot tell us whether the message actually landed. Everywhere else
      // that ambiguity is harmless fire-and-forget; here it would mean showing
      // "thank you" for a message that never arrived.
      if (!window.SUPABASE_URL || !window.SUPABASE_ANON_KEY) throw new Error('supabase not configured');
      const r = await fetch(`${window.SUPABASE_URL}/rest/v1/feedback`, {
        method: 'POST',
        headers: {
          apikey: window.SUPABASE_ANON_KEY,
          Authorization: `Bearer ${window.SUPABASE_ANON_KEY}`,
          'Content-Type': 'application/json',
          Prefer: 'return=minimal',
        },
        body: JSON.stringify(payload),
      });
      if (!r.ok) throw new Error(`HTTP ${r.status} ${(await r.text()).slice(0, 160)}`);
      trackActivationEvent('feedback_submitted', {
        screen: payload.screen,
        length: message.length,
        gaveContact: !!contact,
        topic: topic || null,
      });
      return true;
    } catch (e) {
      // Don't swallow this one. A feedback box that eats the message is worse
      // than no feedback box.
      console.error('feedback submit failed', e);
      trackActivationEvent('feedback_failed', { reason: String(e && e.message || e).slice(0, 120) });
      return false;
    }
  };

  // Pro modal analytics — fire-and-forget
  const trackProEvent = (event, metadata = {}) => {
    writeProEvent(event, proModalReason?.type || 'unknown', metadata);
  };

  // Track Pro modal shown
  useEffect(() => {
    if (showProModal && !userProStatus) {
      trackProEvent('modal_shown');
      trackActivationEvent('pro_modal_shown', {
        reason: proModalReason?.type || 'unknown',
        // True when the prompt only fired because the offer gate stopped
        // trusting a stale proStatus flag. Lets the read separate newly
        // unblocked users from the ones who were always going to be asked.
        staleProRecovered: !!proModalReason?.staleProRecovered,
      });
    }
  }, [showProModal]);

  // Funnel denominator: one app_opened per browser per day, fired once the
  // session settles so username/isGuest are accurate. De-dupe key is
  // browser-scoped (NOT user-scoped) — guests get a fresh guest_<ts> name
  // every load, so a per-user key would fire on every reload.
  useEffect(() => {
    if (isSessionLoading) return;
    try {
      const today = new Date().toISOString().slice(0, 10);
      if (localStorage.getItem('sqlquest_app_opened_day') === today) return;
      localStorage.setItem('sqlquest_app_opened_day', today);
      trackActivationEvent('app_opened', {
        returning: !!localStorage.getItem('sqlquest_user'),
      });
    } catch (_) {}
  }, [isSessionLoading]);

  // Track next-day return as a retention proxy. Local-only de-dupe keeps this
  // to one row per visitor per day.
  useEffect(() => {
    if (typeof window === 'undefined') return;
    try {
      const today = new Date().toISOString().slice(0, 10);
      const storageKey = `sqlquest_last_seen_day_${currentUser || 'guest'}`;
      const previous = localStorage.getItem(storageKey);
      if (previous && previous < today) {
        trackActivationEvent('returned_next_day', {
          previousSeenDay: previous,
          currentSeenDay: today,
        }, { onceKey: `returned_${today}` });
      }
      localStorage.setItem(storageKey, today);
    } catch (_) {}
  }, [currentUser]);

