  const [moreFiltersOpen, setMoreFiltersOpen] = useState(() => {
    try { return localStorage.getItem('sqlquest_practice_more_open') === 'true'; } catch { return false; }
  });
  // Free-text search over the challenge list — added May 2026 after Elena
  // fed back "I lose so much time finding the question I was working on."
  // Matches against id (e.g. "27"), title, description, skills, category.
  // Layered orthogonally on top of difficulty / company / sector filters.
  const [challengeSearch, setChallengeSearch] = useState('');
  const challengeSearchInputRef = useRef(null);
  // Company filter — "Amazon" | "Meta" | null. Layered on top of challengeFilter.
  // Read from ?company=X URL param on mount so landing-page CTAs land users on a
  // pre-filtered view ("See 34 Amazon questions") — eliminates the bait-and-switch
  // where /amazon-sql-interview/ CTA used to dump users into a generic 126-item list.
  const [companyFilter, setCompanyFilter] = useState(() => {
    if (typeof window === 'undefined') return null;
    try {
      const p = new URLSearchParams(window.location.search);
      const raw = p.get('company');
      if (!raw) return null;
      // Normalize: "amazon" → "Amazon", "jpmorgan" → "JPMorgan"
      const VALID = ['Amazon','Meta','Google','Netflix','Apple','Uber','Airbnb',
                     'Databricks','Shopify','Spotify','JPMorgan','Stripe'];
      const match = VALID.find(v => v.toLowerCase() === raw.toLowerCase());
      return match || null;
    } catch { return null; }
  });
  // Sector filter for the Practice tab — orthogonal to companyFilter. When
  // set, only show challenges whose sectorTags include this id (challenge.
  // sectorTags inline OR window.SECTOR_TAGS lookup). Initial value reads
  // ?sector= URL param so /<sector>-sql/ landing CTAs auto-filter the list.
  // The mount-effect URL handler also stamps userGoals.sector for the
  // Coach badge + AI Tutor sector context — same lever, two surfaces.
  const [sectorFilter, setSectorFilter] = useState(() => {
    if (typeof window === 'undefined') return null;
    try {
      const p = new URLSearchParams(window.location.search);
      const raw = p.get('sector');
      if (!raw) return null;
      // Match against canonical sector ids (registered in src/data/sectors.js).
      const validIds = (window.CANONICAL_SECTORS || []).map(s => s.id);
      return validIds.includes(raw) ? raw : null;
    } catch { return null; }
  });
  const fileInputRef = useRef(null);

  // Persist filter state across refreshes — paired with the useState
