  useEffect(() => { try { localStorage.setItem('sqlquest_practice_difficulty', difficultyFilter); } catch (_) {} }, [difficultyFilter]);
  useEffect(() => { try { localStorage.setItem('sqlquest_practice_status', statusFilter); } catch (_) {} }, [statusFilter]);
  useEffect(() => { try { localStorage.setItem('sqlquest_practice_path', challengePathFilter); } catch (_) {} }, [challengePathFilter]);
  useEffect(() => { try { localStorage.setItem('sqlquest_practice_more_open', String(moreFiltersOpen)); } catch (_) {} }, [moreFiltersOpen]);
  useEffect(() => { try { localStorage.setItem('sqlquest_live_tutor', liveTutorMode); } catch (_) {} }, [liveTutorMode]);

  // Cmd/Ctrl+K focuses the challenge search input. Same pattern as
  // Linear / GitHub / Slack — power-user shortcut, doesn't interfere
  // with native browser shortcuts. Bound on document; the handler
  // checks the ref so we don't try to focus an unmounted input
  // (e.g. when the user is on the Coach tab).
  useEffect(() => {
    const onKey = (e) => {
      const isMod = e.metaKey || e.ctrlKey;
      if (isMod && (e.key === 'k' || e.key === 'K')) {
        if (challengeSearchInputRef.current) {
          e.preventDefault();
          challengeSearchInputRef.current.focus();
          challengeSearchInputRef.current.select();
        }
      }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  // Live AI Tutor — fetch a brief, conversational nudge from the AI Coach
  // after a wrong submit. Edge function 'ai-tutor' has a `mode: 'live_nudge'`
  // path that emits ≤2 sentences. We render the result in the same toast
  // the local lint patterns use, but with a 🤖 prefix instead of 💡.
  // Best-effort: any failure is logged and silently dropped — the user
  // still has the diagnostic + the regular AI Help button.
  const requestSmartTutorNudge = async (challenge, userQuery, diagnosis) => {
    // Local telemetry — surfaces in the browser console when the live
    // tutor declines to fire so we can debug "why didn't help reach the
    // student?" cases the way Murat (mbalkose, 2026-05-07) hit. Cheap to
    // keep; if it ever needs to be sent off-device we wire it up here.
    if (!challenge) {
      console.debug('[live-tutor] no-fire: missing challenge', { hasUserQuery: !!userQuery, hasDiagnosis: !!diagnosis });
      return;
    }
    if (!diagnosis) {
      console.debug('[live-tutor] no-fire: diagnosis was null', { challengeId: challenge.id, userQueryLen: (userQuery || '').length });
      return;
    }
    setTutorAiLoading(true);
    try {
      const supaUrl = (typeof window !== 'undefined' && window.SUPABASE_URL) || '';
      const supaKey = (typeof window !== 'undefined' && window.SUPABASE_ANON_KEY) || '';
      if (!supaUrl) {
        // No backend wired — fall back to a hardcoded local nudge
        // derived from the diagnosis kind + headline.
        const id = `${challenge.id}-fail-${Date.now()}`;
        setTutorNudge({
          id,
          kind: 'fail_local',
          message: diagnosis.headline + ' — ' + (diagnosis.hints?.[0] || 'check the diff above for the specific row.'),
          severity: 'warning',
          source: 'local',
          timestamp: Date.now(),
        });
        return;
      }
      // Build a minimal user message — server attaches the live_nudge
      // system prompt. Format mirrors goal_discovery: messages[] is the
      // conversation slot, mode signals the prompt overlay.
      const userBlob = [
        `Challenge #${challenge.id}: ${challenge.title}`,
        `Difficulty: ${challenge.difficulty}`,
        `Description: ${challenge.description || '(none)'}`,
        `My SQL:\n${userQuery}`,
        `Auto-diagnosis: ${diagnosis.headline}. ${diagnosis.details || ''}`,
      ].join('\n\n');
      const aiUsername = (typeof currentUser === 'string' && !currentUser.startsWith('guest_'))
        ? currentUser
        : `guest_${(currentChallenge && currentChallenge.id) || 'anon'}`;
      const response = await fetch(`${supaUrl}/functions/v1/ai-tutor`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(supaKey ? { 'Authorization': `Bearer ${supaKey}`, 'apikey': supaKey } : {}),
        },
        body: JSON.stringify({
          username: aiUsername,
          mode: 'live_nudge',
          messages: [{ role: 'user', content: userBlob }],
          challenge_id: challenge.id,
        }),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      // Edge function returns { text } in live_nudge mode (mirroring
      // the existing AI tutor response shape). Accept legacy keys too.
      const nudgeText = (data.nudge || data.text || data.message || '').trim();
      if (!nudgeText) return;
      const id = `${challenge.id}-ai-${Date.now()}`;
      setTutorNudge({
        id,
        kind: 'ai_smart',
        message: nudgeText,
        severity: 'info',
        source: 'ai',
        timestamp: Date.now(),
      });
    } catch (err) {
      console.warn('Live tutor nudge failed:', err);
    } finally {
      setTutorAiLoading(false);
    }
  };

  // ─── LIVE AI TUTOR ────────────────────────────────────────────────
  // Watches the editor and surfaces nudges. Two trigger paths:
  //   A) Local lint patterns (free, fast) — fires while the student types.
  //      Catches integer division, missing JOIN ON, = NULL, aggregate in
  //      WHERE, missing GROUP BY. Only in 'coach' mode.
  //   B) Idle (60s+ no typing) — fires a generic "stuck?" nudge in 'coach'.
  // The third path — AI smart nudge after a failed submit — lives next to
  // submitChallenge so it can read the diagnosis state directly.
  useEffect(() => {
    if (liveTutorMode !== 'coach') return;
    if (!currentChallenge) return;
    lastEditAtRef.current = Date.now();
    const t = setTimeout(() => {
      const warnings = lintSQL(challengeQuery);
      if (warnings.length === 0) return;
      const w = warnings[0];
      const id = `${currentChallenge.id}-lint-${w.kind}`;
      if (tutorDismissedIds.has(id)) return;
      // Don't replace an active AI nudge with a local one — AI is higher signal.
      if (tutorNudge && tutorNudge.source === 'ai') return;
      setTutorNudge({
        id,
        kind: w.kind,
        message: w.message,
        severity: w.severity || 'warning',
        source: 'local',
        timestamp: Date.now(),
      });
    }, 1500); // debounce so we don't fire on every keystroke
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [challengeQuery, currentChallenge, liveTutorMode]);

  // Idle detector — fires once when the student stops typing for 60s on
  // an empty/near-empty query. "Coach" mode only; "Smart" stays quiet.
  useEffect(() => {
    if (liveTutorMode !== 'coach') return;
    if (!currentChallenge) return;
    const interval = setInterval(() => {
      const idleMs = Date.now() - lastEditAtRef.current;
      const trimmed = (challengeQuery || '').replace(/^--.*$/gm, '').trim();
      if (idleMs >= 60000 && trimmed.length < 20) {
        const id = `${currentChallenge.id}-idle-empty`;
        if (tutorDismissedIds.has(id)) return;
        if (tutorNudge) return;
        const mainTable = currentChallenge.tables?.[0] || 'table_name';
        setTutorNudge({
          id,
          kind: 'idle_empty',
          message: `Stuck on where to start? Try \`SELECT * FROM ${mainTable} LIMIT 5\` to see the data first — then narrow down.`,
          severity: 'info',
          source: 'local',
          timestamp: Date.now(),
        });
      }
    }, 10000); // check every 10s
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChallenge, challengeQuery, liveTutorMode]);

  // Daily Challenge state
  const [showDailyChallenge, setShowDailyChallenge] = useState(false);
  const [dailyChallengeQuery, setDailyChallengeQuery] = useState('');
  const [dailyChallengeResult, setDailyChallengeResult] = useState({ columns: [], rows: [], error: null });
  const [dailyChallengeStatus, setDailyChallengeStatus] = useState(null);
  
  // 3-Step Daily Challenge State
  const [dailyStep, setDailyStep] = useState(0); // 0=warmup, 1=core, 2=insight, 3=complete
  const [warmupAnswer, setWarmupAnswer] = useState(null);
  const [warmupResult, setWarmupResult] = useState(null); // null, 'correct', 'wrong'
  const [insightAnswer, setInsightAnswer] = useState(null);
  const [insightResult, setInsightResult] = useState(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [coreCompleted, setCoreCompleted] = useState(false);
  const [completedDailyChallenges, setCompletedDailyChallenges] = useState({}); // { "2024-01-17": true }
  const [dailyStreak, setDailyStreak] = useState(0);
  // Streak freeze: 2/month, auto-applied when user misses a day
  const [streakFreezes, setStreakFreezes] = useState(2);
  const [lastFreezeRefillMonth, setLastFreezeRefillMonth] = useState('');
  const [streakFreezeToast, setStreakFreezeToast] = useState(null); // { daysFrozen, remaining, streak }
  const [notificationsEnabled, setNotificationsEnabled] = useState(false);
  const [showReminderSetup, setShowReminderSetup] = useState(false);
  
  // Weakness Training State
  const [weaknessTracking, setWeaknessTracking] = useState({
    topics: {}, // { 'JOIN Tables': { level: 1, questions: {...}, ... } }
    lastRefresh: null,
    clearedTopics: [],
    totalCleared: 0,
    // NEW: Skill levels for radar chart (0-100 proficiency per topic)
    skillLevels: {
      'SELECT Basics': 0,
      'Filter & Sort': 0,
      'Aggregation': 0,
      'GROUP BY': 0,
      'JOIN Tables': 0,
      'Subqueries': 0,
      'String Functions': 0,
      'Date Functions': 0,
      'CASE Statements': 0,
      'Window Functions': 0
    },
    // NEW: Spaced repetition schedule
    reviewSchedule: [], // { topic, nextReview: Date, interval: days, easeFactor: 2.5 }
    // NEW: Mastery history for tracking improvement
    masteryHistory: [], // { date, skillLevels: {...} }
    // Event log: boss/weakness/review actions feed the skill formula
    // so these game modes contribute to the radar without direct mutation.
    // { type, skillKey, timestamp, payload }
    performanceEvents: []
  });
  // (24 dead state hooks removed: weakness UI state, boss battle state,
  // daily workout state, showSkillRadar, dueReviews. None of these were
  // ever read by any rendered component — the setters lived in dead chains
  // (startBossBattle, startWeaknessTraining, etc) that no JSX ever called.)

  // Daily Challenge Timer & Hint State
  const [dailyTimer, setDailyTimer] = useState(0); // seconds elapsed
  const [dailyTimerActive, setDailyTimerActive] = useState(false);
  const [dailyHintUsed, setDailyHintUsed] = useState(false);
  const [dailyAnswerShown, setDailyAnswerShown] = useState(false);
  const [dailySolveTime, setDailySolveTime] = useState(null); // final solve time
  const [showWeeklyReport, setShowWeeklyReport] = useState(false);
  const [weakTopicForTutor, setWeakTopicForTutor] = useState(null); // Topic to practice in AI Tutor
  const [studyingTopic, setStudyingTopic] = useState(null); // Currently studying a specific topic (from interview review)
  const [studyStep, setStudyStep] = useState(0); // 0=concept, 1=example, 2=challenge
  const [studyChallengeContext, setStudyChallengeContext] = useState(null); // { tables, expectedQuery, expectedResult, dataset }
  const [selectedChallengeReview, setSelectedChallengeReview] = useState(null); // For detailed challenge review
  
  // AI Learning state
  const [aiMessages, setAiMessages] = useState([]);
  const [aiInput, setAiInput] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [currentAiLesson, setCurrentAiLesson] = useState(0);
  const [aiLessonPhase, setAiLessonPhase] = useState('intro'); // 'intro', 'teaching', 'practice', 'feedback'
  const [aiQuestionCount, setAiQuestionCount] = useState(0);
  const [aiCorrectCount, setAiCorrectCount] = useState(0);
  const [aiExpectedQuery, setAiExpectedQuery] = useState('');
  const [aiExpectedResult, setAiExpectedResult] = useState({ columns: [], rows: [] });
  const [aiUserResult, setAiUserResult] = useState({ columns: [], rows: [], error: null });
  const [showAiComparison, setShowAiComparison] = useState(false);
  // Signed-out Coach email capture — for visitors who land on the Coach tab
  // but aren't ready to sign up. Submits to the capture-email Edge Function.
  const [captureEmailValue, setCaptureEmailValue] = useState('');
  const [captureEmailStatus, setCaptureEmailStatus] = useState('idle'); // idle | submitting | success | error
  const submitCaptureEmail = async () => {
    const email = (captureEmailValue || '').trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
      setCaptureEmailStatus('error');
      return;
    }
    setCaptureEmailStatus('submitting');
    // Analytics: fire before network so we still record intent even if fetch fails
    try { if (typeof window.va === 'function') window.va('event', { name: 'email_capture_submit', source: 'coach_signed_out' }); } catch (_) {}
    try {
      if (!window.SUPABASE_URL || !window.SUPABASE_ANON_KEY) {
        // No backend configured — optimistic success for local dev
        setCaptureEmailStatus('success');
        return;
      }
      const res = await fetch(`${window.SUPABASE_URL}/functions/v1/capture-email`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: window.SUPABASE_ANON_KEY,
        },
        body: JSON.stringify({ email, source: 'coach_signed_out', variant: 'coach_v1' }),
      });
      const ok = res.ok;
      setCaptureEmailStatus(ok ? 'success' : 'error');
    } catch (_) {
      setCaptureEmailStatus('error');
    }
  };

  // Post-solve radar pop — shown briefly after a correct solve, highlighting
  // the skill axes that went up. See RadarPopToast. Auto-dismisses on a timer
  // or on user click. Null when nothing to show.
  const [radarPop, setRadarPop] = useState(null); // { skills, deltas, shownAt }
  const [showFeedback, setShowFeedback] = useState(false);

  const [completedAiLessons, setCompletedAiLessons] = useState(new Set());
  // Phase 2: timestamped parallel store { [lessonId]: ISO string | null }.
  // `null` means "legacy completion with unknown time" — retrieval_check gates
  // against this. Set-based reads (size, has) stay on `completedAiLessons`
  // for UI stability; new engine paths consume `aiLessonCompletions`.
  const [aiLessonCompletions, setAiLessonCompletions] = useState({});
  const [roadmapLessonCompletions, setRoadmapLessonCompletions] = useState(new Set());
  const [foundationPractice, setFoundationPractice] = useState(() => loadSavedFoundationPracticeState() || createFoundationPracticeState(null));
  const foundationAwardedRef = useRef(new Set());
  const [showSqlSandbox, setShowSqlSandbox] = useState(true);
  const [sandboxQuery, setSandboxQuery] = useState('');
  const [sandboxResult, setSandboxResult] = useState({ columns: [], rows: [], error: null });
  const [comprehensionCount, setComprehensionCount] = useState(0);
  const [comprehensionCorrect, setComprehensionCorrect] = useState(0);
  const [lessonAttempts, setLessonAttempts] = useState(0);
  const [consecutiveCorrect, setConsecutiveCorrect] = useState(0);
  const [consecutiveWrong, setConsecutiveWrong] = useState(0);
  const [guidedBuildStep, setGuidedBuildStep] = useState(null); // null = off, 0+ = step number
  const [comprehensionConsecutive, setComprehensionConsecutive] = useState(0);
  const [expectedResultMessageId, setExpectedResultMessageId] = useState(-1);
  const [askedQuestions, setAskedQuestions] = useState([]); // Track asked questions to avoid repetition
  const [currentHintLevel, setCurrentHintLevel] = useState(0); // 0 = no hint, 1 = small hint, 2 = big hint, 3 = show answer
  // Socratic tutor state
  const [discoverRounds, setDiscoverRounds] = useState(0);
  const [attemptSQL, setAttemptSQL] = useState('');
  const [skippedAttempt, setSkippedAttempt] = useState(false);
  const [phaseStartTime, setPhaseStartTime] = useState(Date.now());
  const [studentHistory, setStudentHistory] = useState('nailed_attempt'); // 'nailed_attempt' | 'struggled_discover' | 'needed_full_reveal'
  // Exercise state
  const [exerciseIndex, setExerciseIndex] = useState(0);
  const [exerciseCorrect, setExerciseCorrect] = useState(0);
  const [exerciseAttempted, setExerciseAttempted] = useState(false);
  // Exercises Tab state
  const [selectedExerciseLesson, setSelectedExerciseLesson] = useState(0);
  const [currentExerciseIndex, setCurrentExerciseIndex] = useState(0);

  useEffect(() => {
    try {
      if (foundationPractice?.lessonId) {
        saveFoundationPracticeStateToStorage(foundationPractice);
      } else {
        clearCurrentFoundationPracticeStorage();
      }
    } catch (_) { /* ignore local persistence failures */ }
  }, [foundationPractice]);

  useEffect(() => {
    try {
      if (foundationsRoadmapLessonId) {
        localStorage.setItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY, String(foundationsRoadmapLessonId));
      } else {
        localStorage.removeItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY);
      }
    } catch (_) { /* ignore local persistence failures */ }
  }, [foundationsRoadmapLessonId]);

  // Clamp exercise index when lesson changes or exercises array is shorter than expected
  useEffect(() => {
    const lessons = window.aiLessonsData || [];
    if (lessons.length > 0 && lessons[selectedExerciseLesson]) {
      const maxIndex = lessons[selectedExerciseLesson].exercises.length - 1;
      if (currentExerciseIndex > maxIndex) {
        setCurrentExerciseIndex(0);
      }
    }
  }, [selectedExerciseLesson]);
  const [exerciseQuery, setExerciseQuery] = useState('');
  const [exerciseResult, setExerciseResult] = useState({ columns: [], rows: [], error: null });
  const [exerciseExpectedResult, setExerciseExpectedResult] = useState({ columns: [], rows: [] });
  const [showExerciseResult, setShowExerciseResult] = useState(false);
  const [completedExercises, setCompletedExercises] = useState(new Set()); // format: "lessonId-exerciseIndex"

  // Performance Tracking State (for recommendations)
  const [challengeAttempts, setChallengeAttempts] = useState([]); // Array of { challengeId, difficulty, topic, success, timestamp, firstTry, hintsUsed }
  const [dailyChallengeHistory, setDailyChallengeHistory] = useState([]); // Array of { date, difficulty, topic, success, warmupCorrect, coreCorrect, insightCorrect }
  const [recommendedDifficulty, setRecommendedDifficulty] = useState('Easy');
  const [showDifficultySelector, setShowDifficultySelector] = useState(false);
  const [selectedDailyDifficulty, setSelectedDailyDifficulty] = useState(null);
  const [showStrugglingAlert, setShowStrugglingAlert] = useState(false);
  const [weeklyReports, setWeeklyReports] = useState([]); // Array of weekly report objects
  // Keep the simplified first-run shell until the first successful solve.
  // A wrong first attempt should not "graduate" a new player into the full app
  // or trigger the legacy welcome modal.
  const isFirstRunUser = !firstRunCompleted && solvedChallenges.size === 0;
  const showFirstRunStart = isFirstRunUser && !currentChallenge && activeTab === 'guide';
  const showFirstRunSimpleShell = isFirstRunUser;
  const activeFoundationsLessonForShell = foundationsRoadmapLessonId
    ? FOUNDATIONS_ROADMAP_LESSONS[String(foundationsRoadmapLessonId)]
    : null;
  const showFoundationsFocusShell = activeTab === 'guide' && !!currentUser && !!activeFoundationsLessonForShell;
  const showLessonAdjacentChallengesShell = activeTab === 'quests' && !!currentUser && !!activeFoundationsLessonForShell && !currentChallenge;
  const showSimpleLearningShell = showFirstRunSimpleShell || showFoundationsFocusShell || showLessonAdjacentChallengesShell;
  const showPrimaryLearningTabs = true;
  const showLegacyActivityShortcuts = false;
  const showLegacyPrimaryNav = false;
  const showPracticeSubtabs = false;

  useEffect(() => {
    if (isGuest && isFirstRunUser && !currentChallenge && !['guide', 'quests'].includes(activeTab)) {
      setActiveTab('guide');
    }
  }, [isGuest, isFirstRunUser, currentChallenge, activeTab]);

  // Coach-tab funnel telemetry. 69% of users with saved state have goalId
  // null, and we could not say why: is the tab unreached, or reached in a
  // shell that never renders the goal picker? The picker converts 77% of
  // the users who see it (47 of 61 coachState objects carry a goalId), so
  // the leak is upstream of it — but WHICH shell a visitor landed in was
  // invisible. One event per user per day, shell recorded, answers it.
  // Measurement only; nothing behavioral, so it can't confound the
  // early-August cohort reads.
  useEffect(() => {
    if (activeTab !== 'guide' || !currentUser || isSessionLoading) return;
    try {
      const day = new Date().toISOString().slice(0, 10);
      const key = `sqlquest_coach_view_${day}`;
      if (localStorage.getItem(key)) return;
      localStorage.setItem(key, '1');
      trackActivationEvent('coach_tab_viewed', {
        shell: showFirstRunSimpleShell ? 'first_run'
          : showFoundationsFocusShell ? 'foundations'
          : 'full',
        hasGoal: !!coachState?.goalId,
      });
    } catch (_) { /* ignore */ }
  }, [activeTab, currentUser, isSessionLoading, showFirstRunSimpleShell, showFoundationsFocusShell]);

  useEffect(() => {
    if (activeTab === 'quests' && practiceSubTab !== 'challenges') {
      setPracticeSubTab('challenges');
    }
  }, [activeTab, practiceSubTab]);

  // Capture ?promo= from URL on mount, persist for the session so it survives
  // internal navigation. Sanitized: uppercase alnum + dash/underscore, max 40 chars.
  // The value is passed to Stripe Payment Links via prefilled_promo_code when the
  // user clicks upgrade. Invalid or expired codes are rejected by Stripe at checkout.
  //
  // Also handles ?unsubscribe=weekly from the weekly digest email — sets the
  // opt-out flag and shows a confirmation toast. Deferred for when currentUser
  // is resolved, since we need to persist to their userData.
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const raw = params.get('promo');
      const clean = raw ? raw.toUpperCase().replace(/[^A-Z0-9_-]/g, '').slice(0, 40) : '';
      if (clean) {
        sessionStorage.setItem('sqlquest_promo', clean);
        setActivePromoCode(clean);
      } else {
        const saved = sessionStorage.getItem('sqlquest_promo') || '';
        if (saved) setActivePromoCode(saved);
      }
      if (params.get('unsubscribe') === 'weekly') {
        sessionStorage.setItem('sqlquest_pending_unsub_weekly', '1');
      }
    } catch (_) {
      // sessionStorage unavailable (private mode / old browser) — silently skip.
    }
  }, []);

  // Apply pending weekly-digest unsubscribe once the user's data has finished
  // hydrating. Watching isSessionLoading going false ensures we write AFTER the
  // Supabase session-restore has written localStorage, so our change isn't
  // overwritten. If we wrote earlier, the cloud hydration would clobber our flag.
  useEffect(() => {
    if (!currentUser) return;
    if (isSessionLoading) return;
    try {
      if (sessionStorage.getItem('sqlquest_pending_unsub_weekly') === '1') {
        sessionStorage.removeItem('sqlquest_pending_unsub_weekly');
        setWeeklyDigestPreference(true);
        setShowUnsubscribeToast(true);
        setTimeout(() => setShowUnsubscribeToast(false), 5000);
      }
    } catch (_) { /* ignore */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentUser, isSessionLoading]);

  // Check for existing session on mount
  useEffect(() => {
    // Subscriptions captured by Supabase auth listeners. Declared at the
    // top of the effect (not inside conditional branches) so the cleanup
    // function below can always reach them — even if the listeners never
    // got attached. Was a real bug: when the email-verification or reset-
    // password branches didn't run, cleanup tried to .unsubscribe()
    // on these and threw "ReferenceError: authSubscription is not defined",
    // which crashed any component re-mounted afterward (Weekly modal,
    // Goals modal, etc.).
    let authSubscription;
    let resetSubscription;
    let savedUser = localStorage.getItem('sqlquest_user');
    let clearedLegacySavedGuest = false;
    if (savedUser && String(savedUser).startsWith('guest_')) {
      // Guest sessions are temporary. Older builds sometimes persisted
      // sqlquest_user=guest_..., which made reload restore the guest as a
      // normal saved user and bypass startGuestMode(). Clear it so the
      // guest-first path can create a fresh session and show level onboarding.
      localStorage.removeItem('sqlquest_user');
      localStorage.removeItem(`sqlquest_user_${savedUser}`);
      localStorage.removeItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY);
      clearAllFoundationPracticeStorage();
      savedUser = null;
      clearedLegacySavedGuest = true;
    }
    if (savedUser) {
      // When Supabase is configured, verify user still exists before restoring session
      if (isSupabaseConfigured()) {
        // Check if user exists in Supabase
        supabaseFetch(`users?username=eq.${encodeURIComponent(savedUser)}`).then(cloudData => {
          if (cloudData && cloudData.length > 0) {
            // User exists in Supabase, restore session
            loadUserSession(savedUser);
          } else {
            // User was deleted from Supabase - clear local session
            localStorage.removeItem('sqlquest_user');
            localStorage.removeItem(`sqlquest_user_${savedUser}`);
            setShowAuth(true);
          }
        }).catch(err => {
          console.error('Failed to verify user:', err);
          // On error, try to restore session anyway
          loadUserSession(savedUser);
        });
      } else {
        // Supabase not configured, restore from localStorage
        loadUserSession(savedUser);
      }
    }
    
    // Check notification settings
    const notifEnabled = localStorage.getItem('sqlquest_notifications') === 'true';
    setNotificationsEnabled(notifEnabled);
    
    // Show notification if enabled and daily challenge not completed
    if (notifEnabled && Notification.permission === 'granted') {
      const today = getTodayString();
      const completed = JSON.parse(localStorage.getItem('sqlquest_daily_notified') || '{}');
      if (!completed[today]) {
        setTimeout(() => {
          showDailyNotification();
          completed[today] = true;
          localStorage.setItem('sqlquest_daily_notified', JSON.stringify(completed));
        }, 2000);
      }
    }
    
    // Check for admin URL parameter
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('admin') === 'true') {
      setShowAdminPanel(true);
    }

    // Goals Mentor URL trigger (sector MVP). `?goals=mentor` opens the
    // conversational sector-discovery modal — useful for testing and for
    // marketing CTAs ("Set my career goals" → /?goals=mentor link). The
    // param is stripped from the URL so it doesn't survive a refresh.
    if (urlParams.get('goals') === 'mentor') {
      // Defer so initial render settles first; matches the legacy
      // onboarding modal trigger pattern (line ~4366).
      setTimeout(() => openGoalsMentor(), 400);
      const cleanParams = new URLSearchParams(window.location.search);
      cleanParams.delete('goals');
      const newSearch = cleanParams.toString();
      const newUrl = window.location.pathname
        + (newSearch ? '?' + newSearch : '')
        + window.location.hash;
      window.history.replaceState({}, document.title, newUrl);
    }

    // Sector URL trigger — used by /finans-sql, /gayrimenkul-sql, /uretim-sql
    // landing pages. The user already declared their sector by visiting the
    // landing, so we DON'T open the mentor (no friction). We just stamp the
    // sector preference and let the existing ?challenge= deep-link route
    // them straight to their first sector challenge. The user sees badge,
    // sector-prioritized drill queue, and AI Tutor sector context immediately
    // — no questions asked. They can refine via the Coach badge ✎ later.
    //
    // Important: we do NOT strip ?sector= from the URL on this pass —
    // startGuestMode (called later in the mount sequence) checks for it
    // to decide whether to auto-open the default Easy challenge. Stripping
    // here would race with that check and overwrite the deep-link target.
    // The param is harmless to leave in shareable links.
    const sectorParam = urlParams.get('sector');
    if (sectorParam && Array.isArray(window.CANONICAL_SECTORS)) {
      const valid = window.CANONICAL_SECTORS.some((s) => s.id === sectorParam);
      if (valid) {
        // Don't clobber an existing user-confirmed goal (refining sector via
        // landing is OK, but if the user already mentor'd a richer profile
        // we keep their role/motivation/target and just refresh sector).
        let saved = null;
        try { saved = JSON.parse(localStorage.getItem('sqlquest_user_goals') || 'null'); } catch (_) {}
        const merged = {
          sector: sectorParam,
          role: saved?.role || null,
          motivation: saved?.motivation || null,
          experience: saved?.experience || null,
          target: saved?.target || null,
          raw_text: saved?.raw_text || `Sector inferred from /${sectorParam}-sql landing page.`,
          inferred_at: new Date().toISOString(),
          ai_confidence: saved?.ai_confidence || 0.6,
          user_confirmed: true,
        };
        setUserGoals(merged);
        const datasetId = getFoundationDatasetIdForSector(sectorParam);
        setFoundationDatasetId(datasetId);
        try { localStorage.setItem('sqlquest_user_goals', JSON.stringify(merged)); } catch (_) {}
        try { localStorage.setItem(FOUNDATION_DATASET_STORAGE_KEY, datasetId); } catch (_) {}
        // Suppress mentor opt-in pop-up — user already declared intent.
        const ts = Date.now();
        setGoalsPromptDismissedAt(ts);
        try { localStorage.setItem('sqlquest_goals_prompt_dismissed_at', String(ts)); } catch (_) {}
        // Also suppress the legacy 3-step onboarding (experience/goal questions)
        // — sector landing CTA already declared the user's intent, asking again
        // turns the deep-link payoff into a roadblock. Same rationale as the
        // ?company= bypass.
        try { localStorage.setItem('sqlquest_onboarding_completed', 'true'); } catch (_) {}
      }
    }

    // Restore guest userGoals from localStorage. Logged-in users get this
    // from userData via the session loader (see setUserGoals(userData.goals)
    // a few thousand lines down). Guests skip that path entirely.
    try {
      const savedGoals = localStorage.getItem('sqlquest_user_goals');
      if (savedGoals) setUserGoals(JSON.parse(savedGoals));
      const savedDismiss = localStorage.getItem('sqlquest_goals_prompt_dismissed_at');
      if (savedDismiss) setGoalsPromptDismissedAt(parseInt(savedDismiss, 10) || null);
    } catch (_) { /* corrupted JSON — ignore */ }


    // Referral code is captured at module load (see top of file). Here we
    // just strip ?ref= from the visible URL so the user sees a clean link
    // they can share. Surgical strip only — we MUST preserve other params
    // (notably ?challenge=, ?company=, ?promo=) which downstream effects
    // still consume.
    if (urlParams.has('ref')) {
      const cleanParams = new URLSearchParams(window.location.search);
      cleanParams.delete('ref');
      const newSearch = cleanParams.toString();
      const newUrl = window.location.pathname
        + (newSearch ? '?' + newSearch : '')
        + window.location.hash;
      window.history.replaceState({}, document.title, newUrl);
    }

    // Deep-link to a specific challenge via ?challenge=<slug-or-id>
    // Lets creator partners share direct URLs (e.g.
    //   sqlquest.app/?challenge=mom-customer-growth  (preferred, stable)
    //   sqlquest.app/?challenge=126                  (legacy, works too)
    // from a thread or newsletter. Cold visitors from such a link should
    // land inside the challenge immediately — no landing page, no auth
    // gate, no hunting. Resolution happens in a separate effect that
    // watches the auth state (see `pendingChallengeRef` below).
    const challengeParam = urlParams.get('challenge');
    if (challengeParam) {
      let ch = null;
      ch = challenges.find(c => c.slug && c.slug === challengeParam);
      if (!ch) {
        const asId = parseInt(challengeParam, 10);
        if (!Number.isNaN(asId)) {
          ch = challenges.find(c => c.id === asId);
        }
      }
      if (ch) {
        pendingChallengeRef.current = ch;
      }
    }
    
    // Check for email verification callback
    if (checkEmailVerificationCallback()) {
      
      // Get the Supabase client and check the session
      const client = getSupabaseClient();
      if (client) {
        // Handle the auth state change
        const { data } = client.auth.onAuthStateChange(async (event, session) => {
          
          if (session?.user?.email) {
            const verifiedEmail = session.user.email.toLowerCase();
            
            // Find user by email and mark as verified
            if (isSupabaseConfigured()) {
              try {
                // Try dedicated email column first
                let users = await supabaseFetch(`users?email=eq.${encodeURIComponent(verifiedEmail)}`);
                if (!users || users.length === 0) {
                  // Fallback to data->>email
                  users = await supabaseFetch(`users?data->>email=eq.${encodeURIComponent(verifiedEmail)}`);
                }
                
                if (users && users.length > 0) {
                  const userData = users[0].data;
                  if (userData.emailVerified === false) {
                    userData.emailVerified = true;
                    await saveUserData(users[0].username, userData);
                  }
                }
              } catch (err) {
                console.error('Error updating verification status:', err);
              }
            }
            
            // Also check localStorage
            const allKeys = Object.keys(localStorage).filter(k => k.startsWith('sqlquest_user_'));
            for (const key of allKeys) {
              try {
                const data = JSON.parse(localStorage.getItem(key));
                if (data.email && data.email.toLowerCase() === verifiedEmail && !data.emailVerified) {
                  data.emailVerified = true;
                  localStorage.setItem(key, JSON.stringify(data));
                }
              } catch (e) {}
            }
          }
        });
        authSubscription = data?.subscription;

        // Also try to get current session immediately
        client.auth.getSession().then(async ({ data: { session } }) => {
          if (session?.user?.email) {
            const verifiedEmail = session.user.email.toLowerCase();

            // Update in Supabase
            if (isSupabaseConfigured()) {
              try {
                let users = await supabaseFetch(`users?email=eq.${encodeURIComponent(verifiedEmail)}`);
                if (!users || users.length === 0) {
                  users = await supabaseFetch(`users?data->>email=eq.${encodeURIComponent(verifiedEmail)}`);
                }
                
                if (users && users.length > 0) {
                  const userData = users[0].data;
                  if (userData.emailVerified === false) {
                    userData.emailVerified = true;
                    await saveUserData(users[0].username, userData);
                  }
                }
              } catch (err) {
                console.error('Error updating verification status:', err);
              }
            }
            
            // Update in localStorage
            const allKeys = Object.keys(localStorage).filter(k => k.startsWith('sqlquest_user_'));
            for (const key of allKeys) {
              try {
                const data = JSON.parse(localStorage.getItem(key));
                if (data.email && data.email.toLowerCase() === verifiedEmail && !data.emailVerified) {
                  data.emailVerified = true;
                  localStorage.setItem(key, JSON.stringify(data));
                }
              } catch (e) {}
            }
          }
        });
      }
      
      alert('✅ Email verified successfully! You can now log in.');
      window.history.replaceState({}, document.title, window.location.pathname);
    }
    
    // Check for password reset callback (resetSubscription was hoisted to
    // top of the effect so cleanup can reach it).
    const isResetCallback = checkPasswordResetCallback();
    // Detect Supabase auth errors in the URL fragment (expired links etc).
    // Hoisted out so the guest-first onboarding below can suppress its
    // auto-dismiss when we want the auth modal to stay visible.
    const authError = !isResetCallback ? checkAuthErrorCallback() : null;
    if (isResetCallback) {
      setShowResetPassword(true);
      setShowAuth(true);
      // Handle Supabase Auth session from URL hash
      const resetClient = getSupabaseClient();
      if (resetClient) {
        // Subscribe BEFORE driving the exchange so we don't miss the
        // PASSWORD_RECOVERY / SIGNED_IN event the exchange fires.
        const { data } = resetClient.auth.onAuthStateChange((event, session) => {
          if (event === 'PASSWORD_RECOVERY' || event === 'SIGNED_IN') {
            setShowResetPassword(true);
          }
        });
        resetSubscription = data?.subscription;

        // PKCE: explicitly exchange `?code=` for a session. The
        // detectSessionInUrl auto-runner does this too, but driving it
        // ourselves makes the timing deterministic — by the time the
        // user fills the reset form and clicks Update, the session is
        // already in storage, not still in flight. exchangeCodeForSession
        // is idempotent enough that a double-exchange (auto + manual)
        // just throws on the second call without breaking the first.
        const resetParams = new URLSearchParams(window.location.search);
        const pkceCode = resetParams.get('code');
        if (pkceCode) {
          resetClient.auth.exchangeCodeForSession(pkceCode).catch(err => {
            console.warn('[reset] code exchange:', err?.message || err);
          });
        }
      }
    } else if (authError) {
      // Auth error fallback: when Supabase redirects back with
      // `#error_code=otp_expired` (Yahoo/Outlook prefetch burned the
      // one-time token before the user could click), the implicit-flow
      // URL has no `type=recovery` so the reset modal never opens and
      // the user silently lands on the home page wondering why nothing
      // happened. Surface it explicitly so they know to request a new
      // link. PKCE eliminates this for new emails; this branch keeps
      // legacy emails graceful.
      const expired =
        authError.code === 'otp_expired' ||
        /expired|invalid/i.test(authError.description);
      const msg = expired
        ? 'Şifre sıfırlama linki süresi dolmuş veya kullanılmış. Lütfen yeni bir link iste — "Şifremi unuttum" butonuna tekrar tıkla.'
        : `Auth error: ${authError.description || authError.code}`;
      // Clear the error from the URL so a refresh doesn't re-trigger.
      window.history.replaceState({}, document.title, window.location.pathname);
      // Show the auth modal so the "Forgot password" link is one click away.
      setShowAuth(true);
      // Defer so React mounts the modal before we alert.
      setTimeout(() => alert(msg), 100);
    }
    
    // Admin keyboard shortcut: Ctrl+Shift+A
    const handleKeyDown = (e) => {
      if (e.ctrlKey && e.shiftKey && e.key === 'A') {
        e.preventDefault();
        setShowAdminPanel(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);

    // Guest-first onboarding: cold visitors shouldn't hit a signup wall.
    // If there's no saved session, no explicit "I want to sign in" intent
    // (?signin=1), no deep-link to a challenge (the deep-link useEffect
    // handles that path), and no reset-password flow, drop them straight
    // into guest mode. They can solve immediately, get prompted for an
    // email after first solve, and convert to a full account later.
    //
    // Data point backing this: 59% of signups in the last ~60 days never
    // solved a challenge (Muluken, Malaka, and 9+ others bounced at the
    // signup wall per the 2026-04-20 Supabase CSV). Guest-first removes
    // the wall; the post-solve email modal restores the capture funnel.
    const hasSavedUser = !!localStorage.getItem('sqlquest_user');
    const hasFoundationResume = !clearedLegacySavedGuest && !!localStorage.getItem(FOUNDATION_ACTIVE_LESSON_STORAGE_KEY);
    const wantsSignin = urlParams.get('signin') === '1';
    // ?company= / ?sector= excluded too: their resolver effect starts guest
    // mode itself and lands on the filtered Practice list. Without this
    // exclusion, this setTimeout fires AFTER that resolver and its trailing
    // setActiveTab('guide') clobbers the resolver's 'quests' — the visitor
    // was promised "20 Databricks questions" and got the placement quiz.
    const hasDeepLink = !!urlParams.get('challenge') || !!urlParams.get('company') || !!urlParams.get('sector')
      // ?payment=success (Stripe payment-link redirect) excluded too: the
      // payment-success resolver needs to look up the STASHED purchasing
      // identity — minting a fresh guest here would orphan the buyer's Pro.
      || urlParams.get('payment') === 'success';
    if (!hasSavedUser && !wantsSignin && !hasDeepLink && !isResetCallback && !authError) {
      // Defer to next tick so state setters inside startGuestMode batch
      // cleanly after the rest of mount effect completes.
      // !authError so an expired-link callback doesn't get clobbered by
      // guest mode dismissing the auth modal we just surfaced.
      setTimeout(() => {
        startGuestMode({ preserveFoundationResume: hasFoundationResume });
      }, 0);
    }

    // Deep-link arrivals skip the entry tours THIS session. The tour copy
    // narrates the default flow ("opens with the recommended Learning Path
    // category first") — wrong and disorienting when the visitor was
    // promised a specific challenge or filtered company list. localStorage
    // keys stay unset so an organic revisit still gets the tour.
    if (hasDeepLink) {
      setShowFirstEntryTour(false);
      setShowChallengesEntryTour(false);
    }

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      authSubscription?.unsubscribe?.();
      resetSubscription?.unsubscribe?.();
    };
  }, []);

  // Check daily login reward and load goals when user logs in
  useEffect(() => {
    if (currentUser && !isGuest && !isSessionLoading) {
      // Small delay to ensure session is fully loaded
      setTimeout(() => {
        checkDailyLoginReward();
        setWeeklyGoals(loadWeeklyGoals());
        recordLoginDay();
        checkResumeActivity();
        // Restore speed run history and login calendar
        try {
          const saved = JSON.parse(localStorage.getItem(`sqlquest_user_${currentUser}`) || '{}');
          if (saved.speedRunHistory) setSpeedRunHistory(saved.speedRunHistory);
          if (saved.explainHistory) setExplainHistory(saved.explainHistory);
          if (saved.loginCalendar) setLoginCalendar(prev => ({ ...prev, ...saved.loginCalendar }));
          if (saved.maxLoginStreak) setMaxLoginStreak(saved.maxLoginStreak);
        } catch(e) {}
      }, 500);
    }
  }, [currentUser, isGuest, isSessionLoading]);

  // Save user progress whenever key stats change.
  // Guests are NOT excluded. They used to be (`!isGuest`), which combined
  // with cloud-first loadUserData into a progress shredder: the guest's
  // users row was created empty at first visit, never updated, and then
  // every reload pulled that empty row over the local blob holding their
  // real work. Zero guest rows in the entire table carried a single solve
  // while 91 guests demonstrably solved 215 challenges in a fortnight.
  // saveUserData already debounces cloud writes, so guest volume rides the
  // same throttle as everyone else.
  useEffect(() => {
    if (currentUser && dbReady && !isSessionLoading) {
      (async () => {
        // Preserve existing passwordHash, salt, email, and emailVerified — and
        // spread everything else so fields this allowlist doesn't explicitly know
        // about (weeklyDigestOptOut, weeklyReportLastSeen, lastDigestSent, etc.)
        // aren't silently dropped on every save.
        const existingData = await loadUserData(currentUser);
        const userData = {
          ...(existingData || {}),
          passwordHash: existingData?.passwordHash,
          salt: existingData?.salt,
          email: existingData?.email, // Preserve email for login/password reset
          emailVerified: existingData?.emailVerified !== false, // Preserve verification status (default to true for old accounts)
          username: currentUser,
          xp,
          streak,
          lives,
          queryCount,
          solvedChallenges: [...solvedChallenges],
          unlockedAchievements: [...unlockedAchievements],
          datasetsUsed: [...datasetsUsed],
          queryHistory: queryHistory.slice(-50),
          challengeQueries, // Save challenge queries
          completedDailyChallenges, // Save daily challenge completions
          dailyStreak, // Save daily streak
          lastStreakDay, // Last local day any practice counted toward the streak
          maxDailyStreak, // Personal-best streak (identity stat)
          streakFreezes, // Streak freeze budget (0-2, refills monthly)
          lastFreezeRefillMonth, // YYYY-MM of last refill
          // Performance tracking data
          challengeAttempts: challengeAttempts.slice(-500), // Keep last 500 attempts — provenance matters for skill-calc (hints/answer-shown disappear when records prune, skewing the radar toward false mastery)
          dailyChallengeHistory: dailyChallengeHistory.slice(-60), // Keep ~2 months
          weeklyReports,
          weeklyReportLastSeen,     // last weekStart the user viewed in the modal
          weeklyDigestOptOut,       // user toggled off email digest, or hit unsubscribe
          earnedMilestones,         // append-only log of weekly milestones, deduped by id
          coachState,               // { goalId, startedAt, stepsCompleted } — Coach progress
          roadmapLessonCompletions: [...roadmapLessonCompletions],
          goals: userGoals,         // sector MVP — sector/role/motivation/etc; see docs/sector-mvp-plan.md
          goalsPromptDismissedAt,   // one-time dismiss timestamp for opt-in pop-up
          dismissedNotifs: [...dismissedNotifs], // persisted so dismissals stick across sessions
          loginCalendar,
          maxLoginStreak,
          speedRunHistory: speedRunHistory.slice(0, 20),
          speedRunBest: Math.max(...speedRunHistory.map(r => r.score), 0),
          explainHistory: explainHistory.slice(0, 50),
          // Pro Subscription data - IMPORTANT: preserve these!
          proStatus: userProStatus,
          proType: proType,
          proExpiry: proExpiry,
          proAutoRenew: proAutoRenew,
          // Interview history
          interviewHistory: interviewHistory,
          // 30-Day Challenge Progress
          thirtyDayProgress: challengeProgress,
          thirtyDayStartDate: challengeStartDate,
          // Weakness Tracking
          weaknessTracking: weaknessTracking,
          // Skill Mastery for AI Tutor
          skillMastery: skillMastery,
          // (defeatedBosses + workoutStreak + lastWorkoutDate removed —
          // Boss Battle and Daily Workout systems were retired; their
          // persisted values were never read on rehydration after the
          // setters were deleted.)
          // AI Tutor progress
          aiTutorProgress: {
            currentAiLesson,
            // NOTE: aiMessages intentionally NOT persisted — it can grow to
            // hundreds of KB per user and was the main driver of Supabase
            // egress overage. Conversation history is ephemeral.
            aiLessonPhase,
            aiQuestionCount,
            aiCorrectCount,
            aiExpectedQuery,
            completedAiLessons: [...completedAiLessons],
            aiLessonCompletions,
            comprehensionCount,
            comprehensionCorrect,
            lessonAttempts,
            consecutiveCorrect,
            comprehensionConsecutive,
            completedExercises: [...completedExercises]
          },
          lastActive: Date.now()
        };
        saveUserData(currentUser, userData);
        saveToLeaderboard(currentUser, xp, solvedChallenges.size);
      })();
    }
  }, [xp, solvedChallenges, unlockedAchievements, queryCount, aiLessonPhase, currentAiLesson, completedAiLessons, aiLessonCompletions, roadmapLessonCompletions, comprehensionCount, comprehensionCorrect, consecutiveCorrect, comprehensionConsecutive, completedExercises, challengeQueries, completedDailyChallenges, dailyStreak, challengeAttempts, dailyChallengeHistory, weeklyReports, weeklyReportLastSeen, weeklyDigestOptOut, earnedMilestones, coachState, userGoals, goalsPromptDismissedAt, loginCalendar, speedRunHistory, explainHistory, userProStatus, proType, proExpiry, proAutoRenew, interviewHistory, challengeProgress, challengeStartDate, weaknessTracking, skillMastery]);

  // Load leaderboard periodically
  useEffect(() => {
    if (currentUser) {
      loadLeaderboard().then(setLeaderboard);
      const interval = setInterval(() => {
        loadLeaderboard().then(setLeaderboard);
      }, 30000);
      return () => clearInterval(interval);
    }
  }, [currentUser]);

  // True when the URL signals explicit content intent — user clicked a
  // deep-link from LinkedIn / sector landing / company landing / profile
  // share. They came to do a specific thing; the welcome modal + tour
  // would be friction. Computed once at mount; doesn't react to history
  // changes (one-shot signal).
  const hasContentDeepLink = useMemo(() => {
    if (typeof window === 'undefined') return false;
    try {
      const p = new URLSearchParams(window.location.search);
      return p.has('challenge') || p.has('company') || p.has('sector') || p.has('profile');
    } catch (_) { return false; }
  }, []);

  // Check if should show onboarding for new users.
  // Suppress onboarding when the user arrives with explicit content intent
  // (?company=, ?challenge=, ?sector=, ?profile=) — they clicked through
  // from a landing page or shared link and know exactly what they want.
  // The personalization modal + tutorial would block the filtered content
  // from rendering, turning the paid-promise CTA into bait-and-switch.
  // They can still see the modal after their first solve if we want to
  // prompt later (not wired today).
  useEffect(() => {
    const hasSeenOnboarding = localStorage.getItem('sqlquest_onboarding_completed');
    if (!hasSeenOnboarding && !firstRunCompleted && !firstRunGoal && !firstRunLevel && !firstRunTrack && !showFirstRunSimpleShell && solvedChallenges.size === 0 && challengeAttempts.length === 0 && dbReady && !companyFilter && !hasContentDeepLink) {
      // Small delay to let the UI settle
      const timer = setTimeout(() => setShowOnboarding(true), 500);
      return () => clearTimeout(timer);
    }
  }, [dbReady, solvedChallenges.size, challengeAttempts.length, companyFilter, hasContentDeepLink, showFirstRunSimpleShell, firstRunCompleted, firstRunGoal, firstRunLevel, firstRunTrack]);

  // Reset AI daily usage at midnight
  useEffect(() => {
    const checkReset = () => {
      const today = new Date().toISOString().split('T')[0];
      const saved = JSON.parse(localStorage.getItem('sqlquest_ai_daily') || '{}');
      if (saved.date && saved.date !== today) {
        localStorage.setItem('sqlquest_ai_daily', JSON.stringify({ date: today, used: 0, plan: saved.plan || 'free' }));
        setAiDailyUsage({ used: 0, limit: 3, plan: saved.plan || 'free', remaining: 3 });
      }
    };
    const interval = setInterval(checkReset, 60000); // Check every minute
    return () => clearInterval(interval);
  }, []);

  // Daily Challenge derived state (must be before useEffects that reference it)
  const activeDailyDifficulty = selectedDailyDifficulty || recommendedDifficulty;
  const todaysChallenge = getTodaysChallenge(activeDailyDifficulty);
  const todayString = getTodayString();
  const isDailyCompleted = completedDailyChallenges[todayString] === true;
  const isDailyPracticeMode = completedDailyChallenges[todayString] === 'practice';
  const timeUntilReset = getTimeUntilReset();

  // Daily Challenge Timer
  useEffect(() => {
    let interval;
    if (dailyTimerActive && !isDailyCompleted) {
      interval = setInterval(() => {
        setDailyTimer(prev => prev + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [dailyTimerActive, isDailyCompleted]);

  // Speed Run Timer — pauses on tab switch
  useEffect(() => {
    if (!speedRunActive || speedRunPaused) return;

    const interval = setInterval(() => {
      setSpeedRunTimer(prev => {
        if (prev <= 1) {
          setTimeout(() => endSpeedRun(), 0);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [speedRunActive, speedRunPaused]);

  // Pause timer when user switches tabs
  useEffect(() => {
    if (!speedRunActive) return;
    const handleVisibility = () => {
      if (document.hidden) {
        setSpeedRunPaused(true);
      } else {
        setSpeedRunPaused(false);
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);
    return () => document.removeEventListener('visibilitychange', handleVisibility);
  }, [speedRunActive]);

  // Keyboard shortcuts for speed run
  useEffect(() => {
    if (!speedRunActive) return;
    const handleKeyDown = (e) => {
      // Tab to skip (prevent default tab behavior)
      if (e.key === 'Tab' && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
        const activeEl = document.activeElement;
        const isInEditor = activeEl?.closest?.('.sql-editor') || activeEl?.tagName === 'TEXTAREA';
        if (!isInEditor) {
          e.preventDefault();
          skipSpeedRunChallenge();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [speedRunActive, speedRunDifficulty, speedRunUsedIds]);

  const startSpeedRun = (difficulty = 'all') => {
    // Load all datasets so all challenges work
    if (db) {
      loadDataset(db, 'titanic');
      loadDataset(db, 'movies');
      loadDataset(db, 'employees');
      loadDataset(db, 'ecommerce');
    }

    setSpeedRunDifficulty(difficulty);
    setSpeedRunActive(true);
    setSpeedRunTimer(300);
    setSpeedRunScore(0);
    setSpeedRunSolved(0);
    setSpeedRunFinished(false);
    setSpeedRunQuery('');
    setSpeedRunResult({ columns: [], rows: [], error: null });
    setSpeedRunUsedIds(new Set());
    setSpeedRunFeedback(null);
    setSpeedRunShowHint(false);
    setSpeedRunCombo(0);
    setSpeedRunPaused(false);
    setSpeedRunExpected({ columns: [], rows: [] });
    setSpeedRunShowExpected(false);
    pickNextSpeedRunChallenge(difficulty, new Set(), 0);
    playSound('click');
  };

  // Smart question ordering: in 'all' mode, ramp difficulty based on solved count
  const pickNextSpeedRunChallenge = (diff, usedIds, solvedCount) => {
    let targetDiff = diff;
    if (diff === 'all') {
      // Progressive difficulty: Easy first, then Medium, then Hard
      const solved = solvedCount !== undefined ? solvedCount : speedRunSolvedRef.current;
      if (solved < 3) targetDiff = 'Easy';
      else if (solved < 6) targetDiff = 'Medium';
      else targetDiff = 'Hard';
    }

    // Try to pick from target difficulty first
    let available = challenges.filter(c => !usedIds.has(c.id) && c.difficulty === targetDiff);

    // Fallback: if no target-difficulty questions left, pick from any unused
    if (available.length === 0) {
      available = challenges.filter(c => !usedIds.has(c.id) && (diff === 'all' || c.difficulty === diff));
    }

    // Final fallback: allow repeats
    if (available.length === 0) {
      const all = challenges.filter(c => diff === 'all' || c.difficulty === diff);
      if (all.length > 0) {
        available = [all[Math.floor(Math.random() * all.length)]];
      } else return;
    }

    // Prioritize unsolved challenges (ones user hasn't solved in the main challenges tab)
    const unsolved = available.filter(c => !solvedChallenges.has(c.id));
    const pool = unsolved.length > 0 ? unsolved : available;

    const next = pool[Math.floor(Math.random() * pool.length)];
    setSpeedRunCurrentChallenge(next);
    setSpeedRunQuery('');
    setSpeedRunResult({ columns: [], rows: [], error: null });
    setSpeedRunFeedback(null);
    setSpeedRunShowHint(false);
    setSpeedRunQuestionStartTime(Date.now());
    setSpeedRunShowExpected(false);

    // Pre-compute expected output
    if (db) {
      try {
        const result = db.exec(next.solution);
        if (result.length > 0) {
          setSpeedRunExpected({ columns: result[0].columns, rows: result[0].values });
        } else {
          setSpeedRunExpected({ columns: [], rows: [] });
        }
      } catch(e) {
        setSpeedRunExpected({ columns: [], rows: [] });
      }
    }
  };

  const runSpeedRunQuery = () => {
    if (!db || !speedRunQuery.trim()) return;
    try {
      const result = db.exec(speedRunQuery);
      if (result.length > 0) {
        setSpeedRunResult({ columns: result[0].columns, rows: result[0].values, error: null });
      } else {
        setSpeedRunResult({ columns: [], rows: [], error: 'Query returned no results' });
      }
    } catch (err) {
      setSpeedRunResult({ columns: [], rows: [], error: err.message });
    }
  };

  const submitSpeedRunAnswer = () => {
    if (!db || !speedRunCurrentChallenge || !speedRunQuery.trim()) return;
    try {
      const userResult = db.exec(speedRunQuery);
      const expectedResult = db.exec(speedRunCurrentChallenge.solution);

      if (userResult.length > 0 && expectedResult.length > 0) {
        const userCols = userResult[0].columns;
        const expectedCols = expectedResult[0].columns;
        const userVals = JSON.stringify(userResult[0].values);
        const expectedVals = JSON.stringify(expectedResult[0].values);

        if (JSON.stringify(userCols) === JSON.stringify(expectedCols) && userVals === expectedVals) {
          // Correct! Apply combo multiplier
          const newCombo = speedRunCombo + 1;
          setSpeedRunCombo(newCombo);
          const multiplier = newCombo >= 5 ? 2.0 : newCombo >= 3 ? 1.5 : 1.0;
          const basePoints = speedRunCurrentChallenge.difficulty === 'Hard' ? 30 :
                        speedRunCurrentChallenge.difficulty === 'Medium' ? 20 : 10;

          // Time bonus: +5 pts if solved within 15 seconds
          const solveTime = speedRunQuestionStartTime ? (Date.now() - speedRunQuestionStartTime) / 1000 : 999;
          const timeBonus = solveTime <= 15 ? 5 : 0;

          const points = Math.round(basePoints * multiplier) + timeBonus;
          setSpeedRunScore(prev => prev + points);
          setSpeedRunSolved(prev => prev + 1);

          const comboText = multiplier > 1 ? ` ${multiplier}x combo` : '';
          const timeBonusText = timeBonus > 0 ? ` +${timeBonus} speed bonus!` : '';
          setSpeedRunFeedback({ correct: true, message: `+${points} pts!${comboText}${timeBonusText}` });
          playSound('success');

          const newUsed = new Set(speedRunUsedIds);
          newUsed.add(speedRunCurrentChallenge.id);
          setSpeedRunUsedIds(newUsed);
          const newSolved = speedRunSolved + 1;

          // Auto-advance after brief delay
          setTimeout(() => {
            pickNextSpeedRunChallenge(speedRunDifficulty, newUsed, newSolved);
          }, 400);
          return;
        }

        // Wrong answer — give specific feedback
        const userRowCount = userResult[0].values.length;
        const expectedRowCount = expectedResult[0].values.length;
        const userColCount = userCols.length;
        const expectedColCount = expectedCols.length;

        let hint = 'Not quite!';
        if (userColCount !== expectedColCount) {
          hint = `Wrong columns — expected ${expectedColCount}, got ${userColCount}. Check your SELECT.`;
        } else if (userRowCount !== expectedRowCount) {
          hint = `Wrong row count — expected ${expectedRowCount}, got ${userRowCount}. Check your WHERE/GROUP BY.`;
        } else {
          // Same shape but different values
          hint = 'Right shape, wrong values. Check your conditions or calculations.';
        }

        setSpeedRunCombo(0);
        setSpeedRunFeedback({ correct: false, message: hint + ' Try again or skip (Tab)' });
        playSound('error');
        return;
      }

      // No results from user query
      setSpeedRunCombo(0);
      setSpeedRunFeedback({ correct: false, message: 'Query returned no results. Check your table names and WHERE clause.' });
      playSound('error');
    } catch (err) {
      setSpeedRunCombo(0);
      setSpeedRunFeedback({ correct: false, message: `SQL Error: ${err.message.split(':').pop().trim().slice(0, 60)}` });
    }
  };

  const skipSpeedRunChallenge = () => {
    setSpeedRunCombo(0);
    const newUsed = new Set(speedRunUsedIds);
    if (speedRunCurrentChallenge) newUsed.add(speedRunCurrentChallenge.id);
    setSpeedRunUsedIds(newUsed);
    pickNextSpeedRunChallenge(speedRunDifficulty, newUsed);
    playSound('click');
  };

  const endSpeedRun = () => {
    setSpeedRunActive(false);
    setSpeedRunFinished(true);
    setSpeedRunPaused(false);
    // Use refs for latest values (avoids stale closure from timer effect)
    const finalScore = speedRunScoreRef.current;
    const finalSolved = speedRunSolvedRef.current;
    const finalTimer = speedRunTimerRef.current;
    setSpeedRunHistory(prev => {
      const result = {
        score: finalScore,
        solved: finalSolved,
        difficulty: speedRunDifficulty,
        date: new Date().toISOString(),
        timeUsed: 300 - finalTimer
      };
      const newHistory = [result, ...prev].slice(0, 20);
      if (currentUser) {
        try {
          const saved = JSON.parse(localStorage.getItem(`sqlquest_user_${currentUser}`) || '{}');
          saved.speedRunHistory = newHistory;
          saved.speedRunBest = Math.max(saved.speedRunBest || 0, finalScore);
          localStorage.setItem(`sqlquest_user_${currentUser}`, JSON.stringify(saved));
        } catch(e) {}
      }
      return newHistory;
    });
    playSound('success');
  };

  // === WARM UP QUIZ DATA (100 Questions) ===
