  const importChallenges = (event) => {
    const file = event.target.files[0];
    if (!file) return;
    
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const imported = JSON.parse(e.target.result);
        if (Array.isArray(imported)) {
          const baseId = Date.now();
          const newChallenges = imported.map((c, i) => ({ ...c, id: baseId + i + 1, isCustom: true }));
          const updatedChallenges = [...adminChallenges, ...newChallenges];
          setAdminChallenges(updatedChallenges);
          saveCustomChallenges(updatedChallenges);
          alert(`Imported ${newChallenges.length} challenges!`);
        }
      } catch (err) {
        alert('Invalid JSON file');
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const addToHistory = (sql, success, context) => {
    const entry = { sql, success, context, timestamp: Date.now() };
    setQueryHistory(prev => [...prev.slice(-49), entry]);
  };

  // AI Learning Lessons
  // Load lessons from external file (exercises.js)
  const aiLessons = window.aiLessonsData || [];

  // ============ STUDENT CONTEXT FOR AI ============
  
  // Build comprehensive student profile for AI context
  const buildStudentContext = () => {
    // Calculate overall level category
    const getLevelCategory = () => {
      if (currentLevel < 5) return 'Complete Beginner';
      if (currentLevel < 10) return 'Beginner';
      if (currentLevel < 20) return 'Intermediate';
      if (currentLevel < 35) return 'Advanced';
      return 'Expert';
    };
    
    // Get strongest and weakest skills
    const skillEntries = Object.entries(skillMastery);
    const sortedByLevel = [...skillEntries].sort((a, b) => b[1].level - a[1].level);
    const strongestSkills = sortedByLevel.slice(0, 3).map(([name, data]) => `${name} (Level ${data.level})`);
    const weakestSkills = sortedByLevel.slice(-3).reverse().map(([name, data]) => `${name} (Level ${data.level})`);
    
    // Calculate overall success rate
    const totalCorrect = Object.values(skillMastery).reduce((sum, s) => sum + s.correctCount, 0);
    const totalAttempts = Object.values(skillMastery).reduce((sum, s) => sum + s.totalAttempts, 0);
    const overallSuccessRate = totalAttempts > 0 ? Math.round((totalCorrect / totalAttempts) * 100) : 0;
    
    // Get recent activity
    const recentlyPracticed = skillEntries
      .filter(([_, data]) => data.lastPracticed)
      .sort((a, b) => new Date(b[1].lastPracticed) - new Date(a[1].lastPracticed))
      .slice(0, 3)
      .map(([name]) => name);
    
    // Get skills that need review (not practiced in 7+ days)
    const needsReview = skillEntries
      .filter(([_, data]) => {
        if (!data.lastPracticed) return data.totalAttempts > 0;
        const daysSince = (Date.now() - new Date(data.lastPracticed)) / (1000 * 60 * 60 * 24);
        return daysSince > 7 && data.totalAttempts > 0;
      })
      .map(([name]) => name);
    
    // Interview performance
    const interviewStats = interviewHistory.length > 0 ? {
      totalInterviews: interviewHistory.length,
      avgScore: Math.round(interviewHistory.reduce((sum, i) => sum + (i.score || 0), 0) / interviewHistory.length),
      commonMistakes: [...new Set(interviewHistory.flatMap(i => i.mistakes?.map(m => m.questionTitle) || []))].slice(0, 5)
    } : null;
    
    return {
      level: currentLevel,
      levelCategory: getLevelCategory(),
      xp: xp,
      completedLessons: completedAiLessons.size,
      totalLessons: aiLessons.length,
      strongestSkills,
      weakestSkills,
      overallSuccessRate,
      recentlyPracticed,
      needsReview,
      interviewStats,
      streak: streak,
      hintsUsedTotal: Object.values(skillMastery).reduce((sum, s) => sum + s.hintsUsed, 0)
    };
  };
  
  // Generate student context string for AI system prompt
  const getStudentContextPrompt = () => {
    const ctx = buildStudentContext();
    
    let prompt = `
=== STUDENT PROFILE ===
Level: ${ctx.level} (${ctx.levelCategory})
XP: ${ctx.xp} | Streak: ${ctx.streak} days
Lessons Completed: ${ctx.completedLessons}/${ctx.totalLessons}
Overall Success Rate: ${ctx.overallSuccessRate}%

STRONGEST SKILLS: ${ctx.strongestSkills.join(', ') || 'None yet'}
WEAKEST SKILLS: ${ctx.weakestSkills.join(', ') || 'None yet'}
`;

    if (ctx.recentlyPracticed.length > 0) {
      prompt += `\nRECENTLY PRACTICED: ${ctx.recentlyPracticed.join(', ')}`;
    }
    
    if (ctx.needsReview.length > 0) {
      prompt += `\nNEEDS REVIEW (7+ days): ${ctx.needsReview.join(', ')}`;
    }
    
    if (ctx.interviewStats) {
      prompt += `\n\nINTERVIEW PERFORMANCE:
- Completed: ${ctx.interviewStats.totalInterviews} interviews
- Average Score: ${ctx.interviewStats.avgScore}%`;
      if (ctx.interviewStats.commonMistakes.length > 0) {
        prompt += `\n- Common Mistakes: ${ctx.interviewStats.commonMistakes.join(', ')}`;
      }
    }

    prompt += `

=== TEACHING APPROACH ===
Adapt based on this student's level — but ALWAYS stay direct and code-first:`;

    if (ctx.levelCategory === 'Complete Beginner' || ctx.levelCategory === 'Beginner') {
      prompt += `
- They're new. Use plain language but don't talk down to them.
- Show the SQL first, then explain what each part does. Code before theory.
- Ask them to predict what a query returns BEFORE running it.
- When they get something right, name what they got right specifically ("Your WHERE clause is correct").
- Build from working examples — start with a query that works, then modify it.`;
    } else if (ctx.levelCategory === 'Intermediate') {
      prompt += `
- They know the basics. Don't re-explain SELECT or WHERE.
- Focus on the WHY — "You could do this with a subquery, but a JOIN is O(n) here vs O(n²)."
- Point out common interview traps: "Interviewers love asking this with a GROUP BY twist."
- Challenge them: "Before I explain, what do you think happens if you remove the HAVING clause?"
- Share real-world context: "At scale, this pattern matters because..."`;
    } else {
      prompt += `
- Treat as peer. Use proper terminology. Skip the basics entirely.
- Focus on optimization, edge cases, and interviewer expectations.
- Discuss trade-offs: "A window function is more readable here, but the correlated subquery might be what the interviewer is testing."
- Present ambiguous problems where multiple approaches are valid.
- Push back on their solutions constructively: "This works, but here's a cleaner way."`;
    }

    if (ctx.weakestSkills.length > 0) {
      prompt += `\n\nFOCUS AREAS: Pay extra attention when teaching ${ctx.weakestSkills.map(s => s.split(' (')[0]).join(', ')} - these are weak areas.`;
    }

    return prompt;
  };
  
  // Update skill mastery after an interaction
  const updateSkillMastery = (skillName, wasCorrect, usedHint = false) => {
    // Map various topic names to canonical skill names
    const skillMapping = {
      'select': 'SELECT Basics',
      'where': 'WHERE & Filtering',
      'filter': 'WHERE & Filtering',
      'order by': 'ORDER BY & LIMIT',
      'limit': 'ORDER BY & LIMIT',
      'count': 'Aggregation (COUNT, SUM, AVG)',
      'sum': 'Aggregation (COUNT, SUM, AVG)',
      'avg': 'Aggregation (COUNT, SUM, AVG)',
      'average': 'Aggregation (COUNT, SUM, AVG)',
      'aggregat': 'Aggregation (COUNT, SUM, AVG)',
      'group by': 'GROUP BY',
      'grouping': 'GROUP BY',
      'having': 'HAVING',
      'join': 'JOIN Tables',
      'inner join': 'JOIN Tables',
      'left join': 'JOIN Tables',
      'subquer': 'Subqueries',
      'nested': 'Subqueries',
      'string': 'String Functions',
      'concat': 'String Functions',
      'substr': 'String Functions',
      'date': 'Date Functions',
      'strftime': 'Date Functions',
      'time': 'Date Functions',
      'case': 'CASE Statements',
      'when': 'CASE Statements',
      'window': 'Window Functions',
      'over': 'Window Functions',
      'partition': 'Window Functions',
      'rank': 'Window Functions',
      'row_number': 'Window Functions',
      'cte': 'CTEs',
      'with': 'CTEs',
      'common table': 'CTEs',
      'union': 'UNION & Set Operations',
      'intersect': 'UNION & Set Operations',
      'except': 'UNION & Set Operations'
    };
    
    // Find the canonical skill name
    let canonicalSkill = null;
    const lowerSkill = (skillName || '').toLowerCase();
    
    // First try exact match
    if (skillMastery[skillName]) {
      canonicalSkill = skillName;
    } else {
      // Try mapping
      for (const [keyword, skill] of Object.entries(skillMapping)) {
        if (lowerSkill.includes(keyword)) {
          canonicalSkill = skill;
          break;
        }
      }
    }
    
    if (!canonicalSkill || !skillMastery[canonicalSkill]) {
      return;
    }
    
    setSkillMastery(prev => {
      const current = prev[canonicalSkill];
      const newCorrect = current.correctCount + (wasCorrect ? 1 : 0);
      const newAttempts = current.totalAttempts + 1;
      const newHints = current.hintsUsed + (usedHint ? 1 : 0);
      
      // Calculate new level (1-5) based on success rate and attempts
      const successRate = newAttempts > 0 ? newCorrect / newAttempts : 0;
      let newLevel = current.level;
      
      if (newAttempts >= 3) {
        if (successRate >= 0.9 && newAttempts >= 10) newLevel = 5;
        else if (successRate >= 0.8 && newAttempts >= 7) newLevel = 4;
        else if (successRate >= 0.7 && newAttempts >= 5) newLevel = 3;
        else if (successRate >= 0.5 && newAttempts >= 3) newLevel = 2;
        else newLevel = 1;
        
        // Reduce level if using too many hints
        if (newHints > newAttempts * 0.5) {
          newLevel = Math.max(1, newLevel - 1);
        }
      }
      
      const updated = {
        ...prev,
        [canonicalSkill]: {
          level: newLevel,
          correctCount: newCorrect,
          totalAttempts: newAttempts,
          lastPracticed: new Date().toISOString(),
          hintsUsed: newHints
        }
      };
      
      // Save to localStorage
      localStorage.setItem('sqlquest_skill_mastery', JSON.stringify(updated));
      
      return updated;
    });
  };
  
  // Get skill level for a topic (for display)
  const getSkillLevel = (skillName) => {
    const skill = skillMastery[skillName];
    if (!skill) return { level: 1, stars: '⭐', label: 'Novice' };
    
    const labels = ['Novice', 'Beginner', 'Intermediate', 'Advanced', 'Master'];
    const stars = '⭐'.repeat(skill.level);
    
    return {
      level: skill.level,
      stars,
      label: labels[skill.level - 1] || 'Novice',
      successRate: skill.totalAttempts > 0 ? Math.round((skill.correctCount / skill.totalAttempts) * 100) : 0
    };
  };

  const callAI = async (messages, systemPrompt, phase = null) => {
    // AI is available for both logged-in users and guests
    const aiUsername = currentUser || (() => {
      let guestId = localStorage.getItem('sqlquest_guest_id');
      if (!guestId) {
        guestId = 'guest_' + Math.random().toString(36).slice(2, 10);
        localStorage.setItem('sqlquest_guest_id', guestId);
      }
      return guestId;
    })();
    
    // ENHANCE: Add student context to the system prompt
    const studentContext = getStudentContextPrompt();
    let enhancedSystemPrompt = systemPrompt + '\n\n' + studentContext;

    // SECTOR CONTEXT (sector MVP — see docs/sector-mvp-plan.md):
    // If the user told the Goals Mentor what sector they're in, nudge the
    // tutor toward sector-relevant table shapes and analogies. We don't
    // force it — for a generic "what's a JOIN?" question the tutor still
    // answers generically. The aim is "when an example would help, prefer
    // one from THEIR domain". Cheap, high-leverage personalization.
    if (userGoals?.sector
        && userGoals.sector !== window.GENERIC_SECTOR_ID
        && Array.isArray(window.CANONICAL_SECTORS)) {
      const sectorRow = window.CANONICAL_SECTORS.find((s) => s.id === userGoals.sector);
      if (sectorRow) {
        const sampleTables = (sectorRow.sample_tables || []).slice(0, 5).join(', ');
        const sectorBlock = `\n\nSTUDENT'S DOMAIN CONTEXT:
The student works (or wants to work) in ${sectorRow.en} (${sectorRow.id}). When generating example queries, sample data, or analogies, prefer schemas from THEIR domain rather than generic ones. Sample tables for this sector: ${sampleTables}.${userGoals.role ? ` Their target role is ${String(userGoals.role).replace(/_/g, ' ')}.` : ''}${userGoals.target ? ` Their target outcome: ${String(userGoals.target).replace(/_/g, ' ')}.` : ''}
Do NOT force the sector if the user asks a generic question (e.g. "what does GROUP BY do?") — answer generically and only switch to sector examples when an example would actually help. The student gets bored and confused if every answer feels shoehorned.`;
        enhancedSystemPrompt += sectorBlock;
      }
    }

    // TURKISH MODE: two signals — explicit user preference (came from Türkçe
    // landing with ?lang=tr) OR detection from the latest user message. Either
    // signal flips Turkish mode on for that turn.
    //
    // The preference flag handles users who land on /turkce-sql-ogren/ and click
    // through; their FIRST Coach interaction is Turkish even before they write
    // Turkish themselves. Per-message detection still works for everyone else
    // and for mid-conversation language switches.
    let userLangPref = null;
    try { userLangPref = localStorage.getItem('sqlquest_lang'); } catch (_) {}
    const lastUserMsg = [...messages].reverse().find(m => m && m.role === 'user' && m.content);
    const isTurkish = userLangPref === 'tr' || (lastUserMsg && detectTurkish(lastUserMsg.content));
    if (isTurkish) {
      enhancedSystemPrompt = TURKISH_SYSTEM_PROMPT_PREFIX + enhancedSystemPrompt;
    }

    const validMessages = normalizeAiMessages(messages);
    if (validMessages.length === 0) return null;
    
    
    try {
      const response = await fetch(`${window.SUPABASE_URL}/functions/v1/ai-tutor`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${window.SUPABASE_ANON_KEY}`
        },
        body: JSON.stringify({
          username: aiUsername,
          messages: validMessages,
          systemPrompt: enhancedSystemPrompt,
          phase: phase || undefined,
          challenge_id: currentChallenge?.id || null
        })
      });
      
      if (response.status === 429) {
        // Rate limited
        const data = await response.json();
        setAiDailyUsage({ used: data.used, limit: data.limit, plan: data.plan });
        const today = new Date().toISOString().split('T')[0];
        localStorage.setItem('sqlquest_ai_daily', JSON.stringify({ date: today, used: data.used, plan: data.plan }));

        if (data.plan === 'guest') {
          // Guest hit limit — prompt sign-up for more calls
          setSignupPromptReason('ai_limit');
          setShowSignupPrompt(true);
          return `**AI Limit Reached**\n\nCreate a free account to get ${DAILY_LIMITS?.free || 20} AI tutor calls per day!`;
        }
        if (data.plan === 'free') {
          // Open Pro Modal with rate_limit context
          setProModalReason({ type: 'rate_limit', topic: null, solvedCount: 0 });
          setShowProModal(true);
          return `**Daily AI Limit Reached**\n\nYou've used all ${data.limit} free AI tutor calls for today.`;
        }
        return `**Daily AI Limit Reached**\n\nYou've reached your daily limit of ${data.limit} AI calls. Resets at midnight. You can still use static lessons and challenges.`;
      }
      
      if (!response.ok) {
        const errorData = await response.json();
        console.error("AI proxy error:", response.status, errorData);
        return null;
      }
      
      const data = await response.json();
      
      // Update usage display
      if (data.usage) {
        setAiDailyUsage(data.usage);
        const today = new Date().toISOString().split('T')[0];
        localStorage.setItem('sqlquest_ai_daily', JSON.stringify({ date: today, used: data.usage.used, plan: data.usage.plan || 'free' }));
      } else {
        // No server tracking — increment locally
        setAiDailyUsage(prev => {
          const newUsed = prev.used + 1;
          const updated = { ...prev, used: newUsed, remaining: Math.max(0, prev.limit - newUsed) };
          const today = new Date().toISOString().split('T')[0];
          localStorage.setItem('sqlquest_ai_daily', JSON.stringify({ date: today, used: newUsed, plan: prev.plan || 'free' }));
          return updated;
        });
      }
      
      return data.text || null;
    } catch (err) {
      console.error("AI proxy error:", err.message, err);
      return null; // Fall back to static content
    }
  };

  // Save API key handler
  const saveApiKey = (key, provider = null) => {
    if (key && (key.startsWith('sk-ant-') || key.startsWith('sk-'))) {
      // Auto-detect provider from key format
      const detectedProvider = key.startsWith('sk-ant-') ? 'claude' : 'openai';
      const finalProvider = provider || detectedProvider;
      
      setApiKey(key);
      setAiProvider(finalProvider);
      setUseAI(true);
      localStorage.setItem('sqlquest_api_key', key);
      localStorage.setItem('sqlquest_ai_provider', finalProvider);
      setShowApiKeyModal(false);
    } else if (key === '') {
      setApiKey('');
      setUseAI(false);
      localStorage.removeItem('sqlquest_api_key');
      localStorage.removeItem('sqlquest_ai_provider');
      setShowApiKeyModal(false);
    }
  };


  // Load pre-written lesson content from external file
  const lessonContent = window.lessonContentData || {};

  const getStaticResponse = (lessonId, phase, questionIndex = 0) => {
    const content = lessonContent[lessonId];
    if (!content) return "Let's continue learning!";
    
    if (phase === 'intro') return content.intro;
    if (phase === 'teaching') return content.teaching;
    if (phase === 'practice' && content.practice[questionIndex]) {
      const q = content.practice[questionIndex];
      return `QUESTION: ${q.question}\n\n[EXPECTED_SQL]${q.expected}[/EXPECTED_SQL]`;
    }
    if (phase === 'comprehension' && content.comprehension[questionIndex % 3]) {
      return `QUESTION: ${content.comprehension[questionIndex % 3]}`;
    }
    return "Great job! Let's continue.";
  };

  const getAISystemPrompt = (lesson, phase, context = {}) => {
    const tableInfo = lesson.practiceTable === 'passengers' 
      ? `Table: passengers (passenger_id, survived, pclass, name, sex, age, sibsp, parch, fare, embarked) - Titanic passenger data. survived: 0=died, 1=survived. pclass: 1=first, 2=second, 3=third class.`
      : lesson.practiceTable === 'movies'
      ? `Table: movies (id, title, year, genre, rating, votes, revenue_millions, runtime, director) - Top 100 movies with ratings and box office.`
      : lesson.practiceTable === 'employees'
      ? `Table: employees (emp_id, name, department, position, salary, hire_date, manager_id, performance_rating) - 50 company employees.`
      : `Table: orders (order_id, customer_id, product, category, quantity, price, order_date, country) and customers (customer_id, name, email, join_date, membership, total_orders)`;

    const askedQuestionsInfo = context.askedQuestions && context.askedQuestions.length > 0 
      ? `\n\nPREVIOUSLY ASKED (DO NOT REPEAT THESE):\n${context.askedQuestions.map((q, i) => `${i + 1}. ${q}`).join('\n')}`
      : '';
    
    const hintLevelInfo = context.hintLevel > 0 
      ? `\nSOCRATIC HINT LADDER (current level: ${context.hintLevel}):
Level 1 - CONCEPT NUDGE: Ask a guiding question like "What clause filters rows?" or "Which keyword counts items?" Do NOT give syntax.
Level 2 - SYNTAX HINT: Name the specific SQL keywords needed (e.g. "You'll need GROUP BY and HAVING") but don't show the full query.
Level 3 - PARTIAL SCAFFOLD: Show the query structure with blanks: "SELECT ___ FROM passengers WHERE ___ GROUP BY ___"
Level 4 - FULL REVEAL: Show the complete answer with line-by-line explanation of WHY each part is needed.
You MUST respond at level ${context.hintLevel} ONLY. Do not skip ahead.`
      : '';

    const userAnswerInfo = context.userAnswer 
      ? `\nSTUDENT'S ANSWER: "${context.userAnswer}"`
      : '';

    const expectedQueryInfo = context.expectedQuery 
      ? `\nCORRECT ANSWER: ${context.expectedQuery}`
      : '';

    // Base rules shared across all phases
    const baseRules = `You are a sharp SQL tutor using the Socratic method. Direct, code-first, no filler.

RULES:
- NO markdown (no **, ##, backticks). Use CAPS for SQL keywords.
- Keep responses SHORT. 2-4 sentences max per point.
- Never say "Great question!" or "Great job!" — name what was specifically right.
- NEVER repeat a previously asked question.

Lesson: "${lesson.title}" - ${lesson.topic}
Concepts: ${lesson.concepts.join(", ")}
${tableInfo}
${askedQuestionsInfo}`;

    // Tone calibration based on struggle level
    const toneStr = (context.consecutiveWrong || 0) >= 3 ? '\nTONE: They are frustrated. Be warm, break into tiny steps.'
      : (context.consecutiveWrong || 0) === 2 ? '\nTONE: Patient. Simplify. Use one concrete analogy.'
      : '';

    // Phase-specific prompts — each phase has a clear pedagogical purpose
    if (phase === 'hook') {
      return `${baseRules}

Phase: hook
Do NOT name the SQL concept yet. Ask ONE relatable real-world question that creates the NEED for ${lesson.concepts[0] || lesson.topic}. Make it concrete and visual. 2-3 sentences max.
Do NOT say "today we'll learn..." or "this lesson is about..."
End with a question that makes the student think. MAX 150 TOKENS.`;
    }

    if (phase === 'probe') {
      return `${baseRules}

Phase: probe
The student just answered a warm-up question about ${lesson.topic}. Read their answer carefully.

If they mentioned SQL or related terms: they have some background. Ask what they've tried before for this kind of task.
If they described the idea in plain English: they get the concept but not the SQL. Say "Good instinct. In SQL, there's a way to do exactly that. Want to take a guess at what it might look like?"
If they seem confused: say "No worries. Let me give you a tiny challenge and we'll figure it out together."

1-2 sentences max. Never lecture. Just listen and route. MAX 100 TOKENS.`;
    }

    if (phase === 'attempt') {
      return `${baseRules}

Phase: attempt
Give the student ONE concrete SQL challenge related to ${lesson.concepts.join(', ')}. They have NOT been taught this concept yet. That's the point.

Say: "Try writing a query that [specific task]. Use the ${lesson.practiceTable || 'given'} table. Don't worry about getting it right — just try."

REQUIRED: Include [EXPECTED_SQL]correct_query[/EXPECTED_SQL] for later comparison.
Keep the challenge simple enough that a guess is possible. MAX 120 TOKENS.`;
    }

    if (phase === 'discover') {
      const attemptInfo = context.attemptSQL ? `\nThe student attempted: ${context.attemptSQL}` : '';
      const expectedInfo = context.expectedQuery ? `\nThe correct answer is: ${context.expectedQuery}` : '';
      return `${baseRules}

Phase: discover
Guide the student to see what's right/wrong in their attempt. Pure Socratic questioning.
${attemptInfo}
${expectedInfo}
Discovery round: ${(context.discoverRounds || 0) + 1} of 2

Do NOT give the answer. Instead:
- If they got it right or very close: praise specifically what they got right, then say "Let me show you the formal way to write this."
- If they got the structure right but wrong keyword/clause: "You're close. Look at your query — you wrote [X]. What if there was a keyword specifically for [filtering/grouping/etc.]?"
- If they got it completely wrong: "Let's look at what you wrote. That gives you [what it does]. But you wanted [the goal]. What's missing?"
- If they wrote nothing or said they can't: "If the database could understand English, what would you tell it to do?"

Ask ONE leading question. Never more than one. Wait for their answer. MAX 200 TOKENS.`;
    }

    if (phase === 'reveal') {
      const attemptInfo = context.attemptSQL ? `\nTheir attempt: ${context.attemptSQL}` : '';
      const skipped = context.skippedAttempt;
      return `${baseRules}

Phase: reveal
NOW teach the concept. The student has ${skipped ? 'asked for help — be gentle' : 'struggled with this and earned the explanation'}.
${attemptInfo}

${skipped
  ? 'Start with: "No problem. Let me show you how this works."'
  : 'Connect it directly to their struggle. Use THEIR query as the example, not a generic one.'}

Teach ${lesson.concepts[0] || lesson.topic}:
"That thing you were looking for — it's called [CONCEPT].
Here's ${context.attemptSQL ? 'your query with [CONCEPT] added' : 'how it works'}:

[Show the corrected query or a clear example]

[CONCEPT] [1-sentence explanation of what it does].
[1-sentence explanation of syntax pattern]."

End with: "Ready to practice?" MAX 250 TOKENS.`;
    }

    if (phase === 'practice') {
      const difficulty = context.studentHistory === 'nailed_attempt'
        ? ((context.questionCount || 0) < 2 ? 'medium' : 'hard')
        : context.studentHistory === 'needed_full_reveal'
        ? ((context.questionCount || 0) < 2 ? 'easy' : 'easy-medium')
        : ((context.questionCount || 0) < 2 ? 'easy' : 'medium');

      return `${baseRules}
${hintLevelInfo}
${toneStr}

Phase: practice
PRACTICE: Create a NEW question testing: ${lesson.concepts.join(" or ")}
Difficulty: ${difficulty}
STUDENT HISTORY: ${context.studentHistory || 'nailed_attempt'}
Question count so far: ${context.questionCount || 0}

Start with "QUESTION:" then the question in 1-2 sentences.
REQUIRED: [EXPECTED_SQL]correct_query[/EXPECTED_SQL]
MAX 30 WORDS for the question.`;
    }

    if (phase === 'feedback') {
      return `${baseRules}
${toneStr}

Phase: feedback
${userAnswerInfo} ${expectedQueryInfo}
Wrong attempts in a row: ${context.consecutiveWrong || 0}
REQUIRED: Include [RESULT:correct] or [RESULT:incorrect]
If correct: Name exactly what they got right — the specific clause or function. 1 sentence.
If wrong: Name the error type (wrong clause/function/missing piece/logic/syntax), quote the broken part, show the fix. MAX 60 WORDS.`;
    }

    if (phase === 'mastery') {
      return `${baseRules}

Phase: mastery
The student has answered 3 practice questions correctly about ${lesson.concepts.join(', ')}.

Final test — make them teach it:
"One last thing. Explain to me in your own words: what does ${lesson.concepts[0] || lesson.topic} do, and when would you use it?"

Evaluate their explanation:
- If they nail it: praise what they said right. End with [RESULT:mastery]
- If close but imprecise: give ONE specific correction and ask them to try again in one sentence.
- If they can't explain: help them put it in words with a 1-sentence explanation, ask if that matches what they were thinking, then end with [RESULT:mastery]

IMPORTANT: If this is the student's second or later attempt at explaining, be generous and include [RESULT:mastery]. MAX 150 TOKENS.`;
    }

    if (phase === 'guided_build') {
      return `${baseRules}

Phase: guided_build
GUIDED BUILD: Step ${context.guidedBuildStep || 0} of building the query.
${expectedQueryInfo}
Ask ONE clause at a time: FROM → SELECT → WHERE → GROUP BY → ORDER BY.
If right: confirm and move to next step. If wrong: hint for just this clause. MAX 30 WORDS.`;
    }

    if (phase === 'comprehension') {
      return `${baseRules}

Phase: comprehension
Ask ONE conceptual question about ${lesson.concepts.join(", ")}. No code needed. MAX 25 WORDS.`;
    }

    if (phase === 'comprehension_feedback') {
      return `${baseRules}

Phase: comprehension_feedback
${userAnswerInfo}
REQUIRED: Include [RESULT:correct] or [RESULT:incorrect]
If correct: confirm the key insight in 1 sentence. If wrong: explain the core idea in 2 sentences. MAX 40 WORDS.`;
    }

    // Fallback
    return `${baseRules}\n\nPhase: ${phase}\nRespond helpfully about ${lesson.topic}. Keep it short.`;
  };

  const startAiLesson = async (lessonIndex, isRestart = false) => {
    const lesson = aiLessons[lessonIndex];
    saveLastActivity('lesson', `AI Lesson: ${lesson?.topic || 'SQL'}`, 'guide', null);
    
    setFoundationsRoadmapLessonId(null);
    // Clear any study session when starting a regular lesson
    setStudyingTopic(null);
    
    setCurrentAiLesson(lessonIndex);
    setAiLessonPhase('hook');
    setAiMessages([]);
    setAiQuestionCount(0);
    setAiCorrectCount(0);
    setConsecutiveCorrect(0);
    setConsecutiveWrong(0);
    setGuidedBuildStep(null);
    setAiExpectedQuery('');
    setAiExpectedResult({ columns: [], rows: [] });
    setExpectedResultMessageId(-1);
    setAiUserResult({ columns: [], rows: [], error: null });
    setShowAiComparison(false);
    setSandboxQuery('');
    setSandboxResult({ columns: [], rows: [], error: null });
    setComprehensionCount(0);
    setComprehensionCorrect(0);
    setComprehensionConsecutive(0);
    setAskedQuestions([]); // Reset asked questions for new lesson
    setCurrentHintLevel(0); // Reset hint level
    setAiMessages([{ role: "assistant", content: "Starting your lesson..." }]);
    // Reset Socratic tutor state
    setDiscoverRounds(0);
    setAttemptSQL('');
    setSkippedAttempt(false);
    setPhaseStartTime(Date.now());
    setStudentHistory('nailed_attempt');
    // Reset exercise state
    setExerciseIndex(0);
    setExerciseCorrect(0);
    setExerciseAttempted(false);
    if (isRestart) {
      setLessonAttempts(prev => prev + 1);
    } else {
      setLessonAttempts(0);
    }
    setQuery('');
    setResults({ columns: [], rows: [], error: null });
    setAiLoading(true);

    // Load the appropriate dataset
    if (db) {
      if (lesson.practiceTable === 'passengers') loadDataset(db, 'titanic');
      else if (lesson.practiceTable === 'movies') loadDataset(db, 'movies');
      else if (lesson.practiceTable === 'employees') loadDataset(db, 'employees');
      else loadDataset(db, 'ecommerce');
    }

    // Call the AI API — start with HOOK phase (Socratic flow)
    let response = await callAI(
      [{ role: "user", content: "Start the lesson please!" }],
      getAISystemPrompt(lesson, 'hook', {}),
      'hook'
    );

    // If API failed, show error instead of static content
    if (!response) {
      if (currentUser) {
        // Logged in but API call failed
        response = `❌ **AI Tutor Unavailable**\n\nThe AI tutor couldn't connect. Please check your internet connection and try again.`;
      } else {
        // No API key configured - this shouldn't happen since we check useAI
        response = getStaticResponse(lesson.id, 'hook');
      }
    }
    
    setAiMessages([{ role: "assistant", content: response }]);
    setAiLoading(false);
  };

  // Helper to send a quick message directly (for buttons)
  const sendQuickMessage = async (message, targetPhase) => {
    if (aiLoading) return;
    
    // IMMEDIATELY clear expected result when getting a new practice question
    if (targetPhase === 'practice') {
      setAiExpectedResult({ columns: [], rows: [] });
      setAiExpectedQuery('');
      setExpectedResultMessageId(-1);
      setAiUserResult({ columns: [], rows: [], error: null });
      setResults({ columns: [], rows: [], error: null });
      setQuery('');
      setShowAiComparison(false);
      setCurrentHintLevel(0); // Reset hint level for new question
      setConsecutiveWrong(0);
    }
    
    if (targetPhase === 'guided_build') {
      setGuidedBuildStep(0);
      setCurrentHintLevel(0);
    }
    
    setAiMessages(prev => [...prev, { role: "user", content: message }]);
    setAiLoading(true);
    setAiInput('');

    const lesson = aiLessons[currentAiLesson];
    
    // Reset streak when starting a new section
    if (targetPhase === 'practice' && (aiLessonPhase === 'teaching' || aiLessonPhase === 'reveal')) {
      setConsecutiveCorrect(0);
      setPhaseStartTime(Date.now());
    } else if (targetPhase === 'comprehension' && aiLessonPhase === 'feedback') {
      setComprehensionConsecutive(0);
    } else if (targetPhase === 'mastery') {
      setPhaseStartTime(Date.now());
    }
    
    setAiLessonPhase(targetPhase);

    // Build context for AI
    const context = {
      askedQuestions,
      questionCount: aiQuestionCount,
      hintLevel: currentHintLevel,
      consecutiveWrong,
      guidedBuildStep,
      // Socratic tutor context
      attemptSQL,
      skippedAttempt,
      discoverRounds,
      studentHistory
    };

    // Try real AI first (with sliding window)
    const MAX_HISTORY_MESSAGES = 12;
    const allMsgs = aiMessages.map(m => ({ role: m.role, content: m.content }));
    const recentMsgs = allMsgs.length > MAX_HISTORY_MESSAGES
      ? allMsgs.slice(-MAX_HISTORY_MESSAGES)
      : allMsgs;
    const conversationHistory = [
      ...recentMsgs,
      { role: "user", content: message }
    ];

    let response = await callAI(conversationHistory, getAISystemPrompt(lesson, targetPhase, context), targetPhase);
    
    // If API failed, show error instead of silent fallback
    if (!response) {
      if (currentUser) {
        response = `❌ **AI Tutor Unavailable**\n\nCouldn't connect to the AI tutor. Please check your internet and try again.`;
      } else {
        const questionIdx = targetPhase === 'practice' ? aiQuestionCount % 3 : comprehensionCount % 3;
        response = getStaticResponse(lesson.id, targetPhase, questionIdx);
      }
    }

    // Check for expected SQL and update expected result
    const sqlMatch = (response || '').match(/\[EXPECTED_SQL\]([\s\S]*?)\[\/EXPECTED_SQL\]/);
    if (sqlMatch && sqlMatch[1] && db) {
      const expectedSql = sqlMatch[1].trim();
      // Sanitize: only allow SELECT queries from AI-generated SQL
      const sqlUpper = expectedSql.trim().toUpperCase();
      if (!sqlUpper.startsWith('SELECT') && !sqlUpper.startsWith('WITH')) {
        console.warn('AI generated non-SELECT query in sendQuickMessage, skipping:', expectedSql);
        setAiExpectedQuery(expectedSql);
        setExpectedResultMessageId(-1);
      } else {
        setAiExpectedQuery(expectedSql);
        try {
          const result = db.exec(expectedSql);
          if (result.length > 0) {
            setAiExpectedResult({ columns: result[0].columns, rows: result[0].values });
            setExpectedResultMessageId(aiMessages.length + 1);
          }
        } catch (err) {
          console.error('Error running expected SQL:', err);
          setExpectedResultMessageId(-1);
        }
      }

      // Track the question to avoid repetition
      const questionMatch = (response || '').match(/QUESTION:\s*(.+?)(?:\n|$)/i);
      if (questionMatch && questionMatch[1]) {
        setAskedQuestions(prev => [...prev, questionMatch[1].trim()]);
      }
    } else {
      setExpectedResultMessageId(-1);
    }

    const cleanResponse = (response || '')
      .replace(/\[EXPECTED_SQL\][\s\S]*?\[\/EXPECTED_SQL\]/g, '')
      .replace(/\[RESULT:(correct|incorrect|mastery)\]/gi, '')
      .trim();
    
    setAiMessages(prev => [...prev, { role: "assistant", content: cleanResponse }]);
    setAiLoading(false);
  };

  // Generate response for study mode (when learning a specific topic from interview mistakes)
  const generateStudyResponse = async (userMessage, topic) => {
    // Get the initial explanation that was shown to the user
    const initialExplanation = aiMessages.length > 0 && aiMessages[0].role === 'assistant' 
      ? aiMessages[0].content 
      : '';
    
    // Build the system prompt for study mode — keep responses SHORT for fast interaction
    const studySystemPrompt = `You are a sharp, direct SQL tutor helping a student master "${topic}".

The student is in an interactive study session. They've already seen the concept explanation.

CRITICAL: Keep responses SHORT — 3-5 sentences max, or a short code snippet with 1-2 sentences.
The student learns by doing, not by reading walls of text.

CRITICAL: Keep responses SHORT — 3-5 sentences max, or a short code snippet with 1-2 sentences.

Your approach:
1. Be direct. Answer what they asked, lead with code.
2. If they submit SQL, name what's right, then pinpoint what's wrong.
3. If they're going in circles, say so: "The problem is [X]. Here's the fix."
4. If they ask for practice, give ONE specific challenge.
5. Stay focused on "${topic}". If they drift, pull them back.

Available tables: orders, customers, employees, movies, directors, passengers.
Use SQLite syntax (strftime for dates, || for concatenation). No filler. Code-first.`;

    // Build conversation history for context
    // Claude API requires alternating user/assistant messages starting with user
    // Filter to only include messages after the first user message
    const allMessages = [...aiMessages, { role: "user", content: userMessage }];
    
    // Find the first user message index
    const firstUserIdx = allMessages.findIndex(m => m.role === 'user');
    
    // Only include messages from the first user message onwards
    const conversationHistory = firstUserIdx >= 0 
      ? allMessages.slice(firstUserIdx).map(m => ({ role: m.role, content: m.content }))
      : [{ role: "user", content: userMessage }];
    
    // Call the Claude/OpenAI API
    const aiResponse = await callAI(conversationHistory, studySystemPrompt, 'study');
    
    if (aiResponse) {
      return aiResponse;
    }
    
    // API failed - show error message instead of static content
    return `❌ **AI Tutor Unavailable**\n\nThe AI tutor couldn't connect. Please check your internet connection and try again.`;
  };

  const sendAiMessage = async () => {
    if (!aiInput.trim() || aiLoading) return;
    
    const userMessage = aiInput.trim();
    setAiInput('');
    setAiMessages(prev => [...prev, { role: "user", content: userMessage }]);
    setAiLoading(true);
    setShowAiComparison(false);

    const lesson = aiLessons[currentAiLesson];
    let newPhase = aiLessonPhase;

    // If we're in study mode (studying a specific topic), stay in study mode
    if (aiLessonPhase === 'study' || studyingTopic) {
      newPhase = 'study';
      // Generate a response focused on the topic being studied
      const topicResponse = await generateStudyResponse(userMessage, studyingTopic);
      setAiMessages(prev => [...prev, { role: "assistant", content: topicResponse }]);
      setAiLoading(false);
      return;
    }

    // Deterministic phase transitions (Socratic flow)
    const lowerInput = userMessage.toLowerCase();
    const idkRegex = /\b(idk|don'?t know|no idea|i can'?t|not sure|no clue|help me|i'?m lost|i give up|show me)\b/i;

    if (aiLessonPhase === 'hook') {
      // Any response advances to probe
      newPhase = 'probe';
      setPhaseStartTime(Date.now());
    } else if (aiLessonPhase === 'probe') {
      // Any response advances to attempt
      newPhase = 'attempt';
      setPhaseStartTime(Date.now());
    } else if (aiLessonPhase === 'attempt') {
      // Branch: "I don't know" → reveal (gentler), else → discover
      if (idkRegex.test(userMessage)) {
        newPhase = 'reveal';
        setSkippedAttempt(true);
        setStudentHistory('needed_full_reveal');
      } else {
        newPhase = 'discover';
        setAttemptSQL(userMessage);
        setDiscoverRounds(0);
        setStudentHistory('nailed_attempt'); // will be updated if they struggle
      }
      setPhaseStartTime(Date.now());
    } else if (aiLessonPhase === 'discover') {
      // Max 2 rounds of Socratic discovery, then reveal
      const newRounds = discoverRounds + 1;
      setDiscoverRounds(newRounds);
      if (newRounds >= 2 || idkRegex.test(userMessage)) {
        newPhase = 'reveal';
        if (newRounds >= 1) {
          setStudentHistory('struggled_discover');
        }
      } else {
        newPhase = 'discover'; // another round of guided questioning
      }
      setPhaseStartTime(Date.now());
    } else if (aiLessonPhase === 'reveal') {
      // After reveal, move to practice
      newPhase = 'practice';
      setConsecutiveCorrect(0);
      setCurrentHintLevel(0);
      setConsecutiveWrong(0);
      setAiExpectedResult({ columns: [], rows: [] });
      setAiExpectedQuery('');
      setExpectedResultMessageId(-1);
      setAiUserResult({ columns: [], rows: [], error: null });
      setResults({ columns: [], rows: [], error: null });
      setQuery('');
      setShowAiComparison(false);
      setPhaseStartTime(Date.now());
    } else if (aiLessonPhase === 'practice') {
      newPhase = 'feedback';
      setAiQuestionCount(prev => prev + 1);
    } else if (aiLessonPhase === 'feedback') {
      // Check if user wants guided build mode
      if (lowerInput.includes('build') || lowerInput.includes('step by step') || lowerInput.includes('guide me') || lowerInput.includes('walk me through')) {
        newPhase = 'guided_build';
        setGuidedBuildStep(0);
        setCurrentHintLevel(0);
      } else if (lowerInput.includes('hint') || lowerInput.includes('stuck')) {
        newPhase = 'feedback';
        setCurrentHintLevel(prev => Math.min(prev + 1, 4));
      } else if (consecutiveCorrect >= 3) {
        // 3 correct in a row → mastery phase
        newPhase = 'mastery';
        setAiExpectedResult({ columns: [], rows: [] });
        setAiExpectedQuery('');
        setCurrentHintLevel(0);
        setConsecutiveWrong(0);
        setPhaseStartTime(Date.now());
      } else {
        newPhase = 'practice';
        setCurrentHintLevel(0);
        setConsecutiveWrong(0);
      }
    } else if (aiLessonPhase === 'mastery') {
      // Stay in mastery — [RESULT:mastery] is parsed in response handling below
      newPhase = 'mastery';
    } else if (aiLessonPhase === 'guided_build') {
      const nextStep = (guidedBuildStep || 0) + 1;
      setGuidedBuildStep(nextStep);
      if (nextStep >= 5) {
        newPhase = 'feedback';
        setGuidedBuildStep(null);
      } else {
        newPhase = 'guided_build';
      }
    } else if (aiLessonPhase === 'comprehension') {
      newPhase = 'comprehension_feedback';
      setComprehensionCount(prev => prev + 1);
    } else if (aiLessonPhase === 'comprehension_feedback') {
      if (comprehensionConsecutive >= 3) {
        newPhase = 'comprehension_feedback';
      } else {
        newPhase = 'comprehension';
      }
    }

    setAiLessonPhase(newPhase);

    // Clear old expected result when transitioning to practice phase
    if (newPhase === 'practice' && aiLessonPhase !== 'practice') {
      setAiExpectedResult({ columns: [], rows: [] });
      setAiExpectedQuery('');
      setExpectedResultMessageId(-1);
      setAiUserResult({ columns: [], rows: [], error: null });
      setResults({ columns: [], rows: [], error: null });
      setQuery('');
      setShowAiComparison(false);
    }

    // Build context for smarter AI responses
    const context = {
      askedQuestions,
      questionCount: aiQuestionCount,
      hintLevel: currentHintLevel,
      consecutiveWrong,
      guidedBuildStep,
      userAnswer: (newPhase === 'feedback' || newPhase === 'comprehension_feedback' || newPhase === 'mastery') ? userMessage : null,
      expectedQuery: aiExpectedQuery,
      // Socratic tutor context
      attemptSQL,
      skippedAttempt,
      discoverRounds,
      studentHistory
    };

    // Call the AI API with sliding window to limit token usage
    const MAX_HISTORY_MESSAGES = 12;
    const allMessages = aiMessages.map(m => ({ role: m.role, content: m.content }));
    const recentMessages = allMessages.length > MAX_HISTORY_MESSAGES
      ? allMessages.slice(-MAX_HISTORY_MESSAGES)
      : allMessages;
    const conversationHistory = [
      ...recentMessages,
      { role: "user", content: userMessage }
    ];

    let response = await callAI(conversationHistory, getAISystemPrompt(lesson, newPhase, context), newPhase);
    
    // If API failed, show error
    if (!response) {
      if (currentUser) {
        response = `❌ **AI Tutor Unavailable**\n\nCouldn't connect to the AI tutor. Please check your internet and try again.`;
      } else {
        // Not logged in - prompt to sign in
        response = "Please sign in to use the AI Tutor.";
      }
    } else {
      // AI responded - parse structured result tags
      const resultTagMatch = (response || '').match(/\[RESULT:(correct|incorrect|mastery)\]/i);
      const resultType = resultTagMatch ? resultTagMatch[1].toLowerCase() : null;
      const isResultCorrect = resultType === 'correct';
      const isResultIncorrect = resultType === 'incorrect';
      const isResultMastery = resultType === 'mastery';

      if (newPhase === 'feedback' || aiLessonPhase === 'practice') {
        const lessonTopic = lesson?.topic || lesson?.concepts?.[0] || 'SQL';
        const usedHint = currentHintLevel > 0;

        if (isResultCorrect) {
          setAiCorrectCount(prev => prev + 1);
          setConsecutiveCorrect(prev => prev + 1);
          setConsecutiveWrong(0);
          setGuidedBuildStep(null);
          updateSkillMastery(lessonTopic, true, usedHint);
        } else if (isResultIncorrect) {
          setConsecutiveCorrect(0);
          setConsecutiveWrong(prev => prev + 1);
          updateSkillMastery(lessonTopic, false, usedHint);
        }
        // If no tag found (null), don't update streaks - avoids false positives
      }
      if (newPhase === 'comprehension_feedback' || aiLessonPhase === 'comprehension') {
        const lessonTopic = lesson?.topic || lesson?.concepts?.[0] || 'SQL';

        if (isResultCorrect) {
          setComprehensionCorrect(prev => prev + 1);
          setComprehensionConsecutive(prev => prev + 1);
          updateSkillMastery(lessonTopic, true, false);
        } else if (isResultIncorrect) {
          setComprehensionConsecutive(0);
          updateSkillMastery(lessonTopic, false, false);
        }
      }
      // MASTERY phase completion — student explained the concept back
      if (newPhase === 'mastery' && isResultMastery) {
        const lessonTopic = lesson?.topic || lesson?.concepts?.[0] || 'SQL';
        updateSkillMastery(lessonTopic, true, false);
        // Auto-complete the lesson
        if (!completedAiLessons.has(lesson.id)) {
          setXP(prev => prev + 50);
          setCompletedAiLessons(prev => new Set([...prev, lesson.id]));
          setAiLessonCompletions(prev => ({ ...prev, [lesson.id]: new Date().toISOString() }));
          setAiLessonPhase('complete');
          addToHistory(`Completed AI Lesson: ${lesson.title}`, true, 'ai-learning');
        }
      }
      // Mastery fallback: count user messages in mastery phase. If 2+ attempts without [RESULT:mastery], auto-complete
      if (newPhase === 'mastery' && !isResultMastery) {
        const masteryUserMsgs = aiMessages.filter((m, i) => {
          // Count user messages that came after the mastery phase started
          // We check messages after the last phase transition to mastery
          return m.role === 'user';
        });
        // Find how many user messages occurred during mastery by checking from the end
        let masteryAttempts = 0;
        for (let i = aiMessages.length - 1; i >= 0; i--) {
          if (aiMessages[i].role === 'user') masteryAttempts++;
          else break; // stop at last assistant message
        }
        // The current userMessage is attempt #(masteryAttempts+1) since we already pushed it
        if (masteryAttempts >= 1) {
          // This is their 2nd+ attempt — auto-complete
          if (!completedAiLessons.has(lesson.id)) {
            setXP(prev => prev + 50);
            setCompletedAiLessons(prev => new Set([...prev, lesson.id]));
            setAiLessonCompletions(prev => ({ ...prev, [lesson.id]: new Date().toISOString() }));
            setAiLessonPhase('complete');
            addToHistory(`Completed AI Lesson: ${lesson.title}`, true, 'ai-learning');
          }
        }
      }
    }

    // Check for expected SQL in response and update expected result
    const sqlMatch = (response || '').match(/\[EXPECTED_SQL\]([\s\S]*?)\[\/EXPECTED_SQL\]/);
    if (sqlMatch && sqlMatch[1] && db) {
      const expectedSql = sqlMatch[1].trim();
      // Sanitize: only allow SELECT queries from AI-generated SQL
      const sqlUpper = expectedSql.trim().toUpperCase();
      if (!sqlUpper.startsWith('SELECT') && !sqlUpper.startsWith('WITH')) {
        console.warn('AI generated non-SELECT query, skipping execution:', expectedSql);
        setAiExpectedQuery(expectedSql);
        setAiExpectedResult({ columns: [], rows: [] });
        setExpectedResultMessageId(-1);
      } else {
      setAiExpectedQuery(expectedSql);
      try {
        const result = db.exec(expectedSql);
        if (result.length > 0) {
          setAiExpectedResult({ columns: result[0].columns, rows: result[0].values });
          setExpectedResultMessageId(aiMessages.length + 1);
        } else {
          setAiExpectedResult({ columns: [], rows: [] });
          setExpectedResultMessageId(-1);
        }
      } catch (err) {
        console.error('Error running expected SQL:', err);
        setAiExpectedResult({ columns: [], rows: [] });
        setExpectedResultMessageId(-1);
      }
      setAiUserResult({ columns: [], rows: [], error: null });
      setShowAiComparison(false);
      setQuery('');
      
      // Track the question to avoid repetition
      const questionMatch = (response || '').match(/QUESTION:\s*(.+?)(?:\n|$)/i);
      if (questionMatch && questionMatch[1]) {
        setAskedQuestions(prev => [...prev, questionMatch[1].trim()]);
      }
      } // end else (SELECT query sanitization)
    } else if (newPhase === 'comprehension') {
      setAiExpectedResult({ columns: [], rows: [] });
      setAiExpectedQuery('');
      setExpectedResultMessageId(-1);
    } else {
      setExpectedResultMessageId(-1);
    }

    const cleanResponse = (response || '')
      .replace(/\[EXPECTED_SQL\][\s\S]*?\[\/EXPECTED_SQL\]/g, '')
      .replace(/\[RESULT:(correct|incorrect|mastery)\]/gi, '')
      .trim();

    setTimeout(() => {
      setAiMessages(prev => [...prev, { role: "assistant", content: cleanResponse || 'Let me help you with that!' }]);
      setAiLoading(false);
    }, 300);
  };

  // Validate that a SQL query is read-only (SELECT/WITH only)
  const isReadOnlySQL = (sql) => {
    const trimmed = sql.trim().toUpperCase();
    return trimmed.startsWith('SELECT') || trimmed.startsWith('WITH') || trimmed.startsWith('EXPLAIN');
  };

  const runAiQuery = () => {
    if (!query.trim() || !db) return;

    // Only allow read-only queries
    if (!isReadOnlySQL(query)) {
      setResults({ columns: [], rows: [], error: 'Only SELECT queries are allowed. Try: SELECT * FROM table_name' });
      return;
    }

    try {
      const result = db.exec(query);
      const userResult = result.length > 0 
        ? { columns: result[0].columns, rows: result[0].values, error: null }
        : { columns: [], rows: [], error: null };
      
      setAiUserResult(userResult);
      setResults(userResult);
      setShowAiComparison(true);
      addToHistory(query, true, 'ai-learning');
    } catch (err) {
      setResults({ columns: [], rows: [], error: err.message });
      setAiUserResult({ columns: [], rows: [], error: err.message });
      setShowAiComparison(true);
      addToHistory(query, false, 'ai-learning');
    }
  };

  const runSandboxQuery = () => {
    if (!sandboxQuery.trim() || !db) return;

    if (!isReadOnlySQL(sandboxQuery)) {
      setSandboxResult({ columns: [], rows: [], error: 'Only SELECT queries are allowed. Try: SELECT * FROM table_name' });
      return;
    }

    try {
      const result = db.exec(sandboxQuery);
      const queryResult = result.length > 0 
        ? { columns: result[0].columns, rows: result[0].values, error: null }
        : { columns: [], rows: [], error: null };
      
      setSandboxResult(queryResult);
      addToHistory(sandboxQuery, true, 'ai-sandbox');
    } catch (err) {
      setSandboxResult({ columns: [], rows: [], error: err.message });
      addToHistory(sandboxQuery, false, 'ai-sandbox');
    }
  };

  const copySandboxToAnswer = () => {
    setQuery(sandboxQuery);
  };

  const submitAiQuery = async () => {
    if (!query.trim() || !db) return;

    if (!isReadOnlySQL(query)) {
      setResults({ columns: [], rows: [], error: 'Only SELECT queries are allowed. Try: SELECT * FROM table_name' });
      return;
    }

    try {
      const result = db.exec(query);
      const userResult = result.length > 0 
        ? { columns: result[0].columns, rows: result[0].values, error: null }
        : { columns: [], rows: [], error: null };
      
      setAiUserResult(userResult);
      setResults(userResult);
      setShowAiComparison(true);
      
      // Only compare if we have expected results
      const hasExpected = aiExpectedResult.rows.length > 0;
      const isCorrect = hasExpected && 
        JSON.stringify(userResult.rows) === JSON.stringify(aiExpectedResult.rows);
      
      const output = result.length > 0 
        ? `Query executed successfully! Returned ${result[0].values.length} rows.\nColumns: ${result[0].columns.join(', ')}\nFirst few rows:\n${result[0].values.slice(0, 3).map(r => r.join(', ')).join('\n')}`
        : 'Query executed but returned no results.';
      
      // Don't bias AI negatively if we don't have expected results
      let evalMessage = `I wrote this SQL query:\n\`\`\`sql\n${query}\n\`\`\`\n\nResult: ${output}`;
      if (hasExpected && isCorrect) {
        evalMessage += `\n\nThe results MATCH the expected output - this is CORRECT!`;
      } else if (hasExpected) {
        evalMessage += `\n\nThe results do NOT match expected output.`;
      } else {
        evalMessage += `\n\nPlease evaluate if this query correctly answers the question.`;
      }
      
      setAiInput('');
      setAiMessages(prev => [...prev, { role: "user", content: evalMessage }]);
      setAiLoading(true);
      setAiLessonPhase('feedback');
      setAiQuestionCount(prev => prev + 1);

      const lesson = aiLessons[currentAiLesson];
      
      // Build context for smarter feedback
      const context = {
        askedQuestions,
        questionCount: aiQuestionCount,
        hintLevel: currentHintLevel,
        consecutiveWrong,
        guidedBuildStep,
        userAnswer: query,
        expectedQuery: aiExpectedQuery
      };
      
      const MAX_HIST = 12;
      const allMsgsForEval = aiMessages.map(m => ({ role: m.role, content: m.content }));
      const recentMsgsForEval = allMsgsForEval.length > MAX_HIST
        ? allMsgsForEval.slice(-MAX_HIST)
        : allMsgsForEval;
      const conversationHistory = [
        ...recentMsgsForEval,
        { role: "user", content: evalMessage }
      ];

      const response = await callAI(
        conversationHistory,
        getAISystemPrompt(lesson, 'feedback', context),
        'feedback'
      );

      // Handle AI response or fall back to static
      let feedbackResponse = response;
      if (!feedbackResponse) {
        // Smart static fallback with detailed feedback
        if (isCorrect) {
          feedbackResponse = "Correct! Excellent work! Your query returned exactly the expected results. Ready for the next question?";
        } else if (hasExpected) {
          // Analyze what went wrong
          const userCols = userResult.columns || [];
          const expectedCols = aiExpectedResult.columns || [];
          const colMatch = JSON.stringify(userCols) === JSON.stringify(expectedCols);
          const rowCountMatch = userResult.rows.length === aiExpectedResult.rows.length;
          
          if (!colMatch) {
            feedbackResponse = `Almost there! Your query runs, but the columns don't quite match.\n\nYour columns: ${userCols.join(', ')}\nExpected: ${expectedCols.join(', ')}\n\nHint: Check your SELECT clause - are you selecting the right columns?\n\nThe expected query was:\n${aiExpectedQuery}`;
          } else if (!rowCountMatch) {
            feedbackResponse = `Good structure! But your query returned ${userResult.rows.length} rows instead of ${aiExpectedResult.rows.length}.\n\nHint: Check your WHERE clause or GROUP BY - you might be filtering too much or too little.\n\nThe expected query was:\n${aiExpectedQuery}`;
          } else {
            feedbackResponse = `So close! Your query structure looks right, but the values don't match.\n\nHint: Double-check the column names and any conditions in your WHERE clause.\n\nThe expected query was:\n${aiExpectedQuery}`;
          }
        } else {
          feedbackResponse = "Your query executed successfully! Let's move on to the next question.";
        }
      }

      // Track consecutive correct - use structured tag if available, fall back to programmatic check
      const submitResultTag = (feedbackResponse || '').match(/\[RESULT:(correct|incorrect)\]/i);
      const submitIsCorrect = submitResultTag
        ? submitResultTag[1].toLowerCase() === 'correct'
        : isCorrect; // Fall back to programmatic row comparison

      if (submitIsCorrect) {
        setAiCorrectCount(prev => prev + 1);
        setConsecutiveCorrect(prev => prev + 1);
        setConsecutiveWrong(0);
        setGuidedBuildStep(null);
      } else if (submitIsCorrect === false) {
        setConsecutiveCorrect(0);
        setConsecutiveWrong(prev => prev + 1);
      }

      // Strip result tag from displayed response
      const cleanFeedback = (feedbackResponse || '').replace(/\[RESULT:(correct|incorrect|mastery)\]/gi, '').trim();
      setAiMessages(prev => [...prev, { role: "assistant", content: cleanFeedback }]);
      setAiLoading(false);
      addToHistory(query, true, 'ai-learning');
    } catch (err) {
      setResults({ columns: [], rows: [], error: err.message });
      setAiUserResult({ columns: [], rows: [], error: err.message });
      setShowAiComparison(true);
      setConsecutiveCorrect(0); // Reset streak on error
      setConsecutiveWrong(prev => prev + 1); // Track frustration
      
      // Send error to AI with helpful context
      const errorMessage = `I tried this query but got an error:\n\`\`\`sql\n${query}\n\`\`\`\nError: ${err.message}`;
      setAiMessages(prev => [...prev, { role: "user", content: errorMessage }]);
      setAiLoading(true);

      const lesson = aiLessons[currentAiLesson];
      
      // Build context for error help
      const context = {
        askedQuestions,
        questionCount: aiQuestionCount,
        hintLevel: currentHintLevel + 1, // Increase hint level on error
        consecutiveWrong: consecutiveWrong + 1,
        guidedBuildStep,
        userAnswer: query,
        expectedQuery: aiExpectedQuery
      };
      
      const allMsgsForErr = aiMessages.map(m => ({ role: m.role, content: m.content }));
      const recentMsgsForErr = allMsgsForErr.length > 12
        ? allMsgsForErr.slice(-12)
        : allMsgsForErr;
      const conversationHistory = [
        ...recentMsgsForErr,
        { role: "user", content: errorMessage }
      ];

      const response = await callAI(
        conversationHistory,
        getAISystemPrompt(lesson, 'feedback', context) + "\n\nIMPORTANT: The student's query had a SYNTAX ERROR. Help them understand what went wrong with a specific example of how to fix it.",
        'feedback'
      );

      // Detailed static error feedback
      let errorResponse = response;
      if (!errorResponse) {
        const errLower = err.message.toLowerCase();
        if (errLower.includes('no such column')) {
          const colMatch = err.message.match(/no such column: (\w+)/i);
          errorResponse = `Column not found! The column "${colMatch?.[1] || 'specified'}" doesn't exist in this table.\n\nAvailable columns: Check the table schema on the right.\n\nExample fix: If you typed "name" but the column is "passenger_name", change it to:\nSELECT passenger_name FROM table_name`;
        } else if (errLower.includes('no such table')) {
          errorResponse = `Table not found! Make sure you're using the correct table name.\n\nFor this lesson, use: ${lesson.practiceTable}\n\nExample:\nSELECT * FROM ${lesson.practiceTable} LIMIT 5`;
        } else if (errLower.includes('syntax error')) {
          errorResponse = `Syntax error detected. Common causes:\n\n1. Missing comma between columns: SELECT col1 col2 → SELECT col1, col2\n2. Missing FROM keyword: SELECT * table → SELECT * FROM table\n3. Typo in keywords: SELEC → SELECT\n\nYour query: ${query}\n\nTry fixing the syntax and submit again!`;
        } else {
          errorResponse = `There's an error in your query: "${err.message}"\n\nLet me help:\n1. Check spelling of table and column names\n2. Make sure you have SELECT, FROM in the right order\n3. Check for missing commas or quotes\n\nThe expected structure was:\n${aiExpectedQuery || 'SELECT columns FROM table WHERE condition'}`;
        }
      }
      
      setAiMessages(prev => [...prev, { role: "assistant", content: errorResponse }]);
      setAiLoading(false);
      addToHistory(query, false, 'ai-learning');
    }
  };

  // Submit exercise answer
  const submitExercise = () => {
    if (!query.trim() || !db) return;
    
    const lesson = aiLessons[currentAiLesson];
    const currentExercise = lesson.exercises[exerciseIndex];
    
    try {
      // Run user's query
      const userResult = db.exec(query);
      const userValues = userResult.length > 0 ? JSON.stringify(userResult[0].values) : '[]';
      
      // Run expected query
      const expectedResult = db.exec(currentExercise.sql);
      const expectedValues = expectedResult.length > 0 ? JSON.stringify(expectedResult[0].values) : '[]';
      
      // Compare results
      const isCorrect = userValues === expectedValues;
      
      setAiUserResult(userResult.length > 0 
        ? { columns: userResult[0].columns, rows: userResult[0].values, error: null }
        : { columns: [], rows: [], error: null });
      setResults(userResult.length > 0 
        ? { columns: userResult[0].columns, rows: userResult[0].values, error: null }
        : { columns: [], rows: [], error: null });
      setShowAiComparison(true);
      setExerciseAttempted(true);
      
      if (isCorrect) {
        const newCorrect = exerciseCorrect + 1;
        setExerciseCorrect(newCorrect);
        addToHistory(query, true, 'ai-exercise');
        
        // Check if all exercises complete
        if (exerciseIndex >= 4) {
          // All 5 exercises done!
          setXP(prev => prev + 250);
          setCompletedAiLessons(prev => new Set([...prev, lesson.id]));
          setAiLessonCompletions(prev => ({ ...prev, [lesson.id]: new Date().toISOString() }));
          addToHistory(`Completed AI Lesson: ${lesson.title}`, true, 'ai-learning');
          setAiLessonPhase('complete');
          
          // Add congratulation message
          setAiMessages(prev => [...prev, { 
            role: "assistant", 
            content: `🎉 CONGRATULATIONS! You've completed all 5 exercises perfectly!\n\nYou've mastered "${lesson.title}" and earned 250 XP!\n\n${currentAiLesson < aiLessons.length - 1 ? "Ready for the next lesson? Click 'Next Lesson' to continue your SQL journey!" : "Amazing! You've completed all lessons in SQL Quest!"}`
          }]);
        } else {
          // Move to next exercise
          setExerciseIndex(prev => prev + 1);
          setExerciseAttempted(false);
          setQuery('');
          setAiUserResult({ columns: [], rows: [], error: null });
          setResults({ columns: [], rows: [], error: null });
          setShowAiComparison(false);
        }
      } else {
        addToHistory(query, false, 'ai-exercise');
      }
    } catch (err) {
      setResults({ columns: [], rows: [], error: err.message });
      setAiUserResult({ columns: [], rows: [], error: err.message });
      setShowAiComparison(true);
      addToHistory(query, false, 'ai-exercise');
    }
  };

  useEffect(() => {
    const initSQL = async () => {
      try {
        const SQL = await window.initSqlJs({ locateFile: f => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${f}` });
        const database = new SQL.Database();
        setDb(database);
        loadDataset(database, 'titanic');
        setDbReady(true);
      } catch (err) { 
        console.error('SQL.js init failed:', err); 
        // Still show the app even if DB fails
        setDbReady(true);
      }
    };
    
    // Check if script already loaded
    if (window.initSqlJs) {
      initSQL();
      return;
    }
    
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/sql-wasm.js';
    script.onload = () => {
      initSQL();
    };
    script.onerror = (err) => {
      console.error('Failed to load sql-wasm.js:', err);
      setDbReady(true); // Show app anyway
    };
    document.head.appendChild(script);
    return () => { if (document.head.contains(script)) document.head.removeChild(script); };
  }, []);

