                          setDailyAnswerShown(false);
                          setDailyTimer(0);
                          // Mark as practice mode (preserve true completion, only set practice if not already completed)
                          setCompletedDailyChallenges(prev => ({ ...prev, [todayString]: prev[todayString] === true ? true : 'practice' }));
